  const toggle=row=>{const key=keyOf(row);if(key!==undefined)setExpanded(keys=>keys.includes(key)?keys.filter(item=>item!==key):[...keys,key])};
  return <AntTable {...props} rowKey={rowKey} columns={columns}
    expandable={{expandedRowRender:defaultDetails,...expandable,expandedRowKeys:expanded,onExpand:(open,row)=>{expandable?.onExpand?.(open,row);const key=keyOf(row);setExpanded(keys=>open?[...new Set([...keys,key])]:keys.filter(item=>item!==key))}}}
    onRow={(row,index)=>{const original=onRow?.(row,index)||{};return {...original,style:{cursor:'pointer',...original.style},onClick:event=>{original.onClick?.(event);if(onRow||event.target.closest('button,a,input,select,textarea,[role="button"],[role="checkbox"],.ant-select'))return;toggle(row)},onKeyDown:event=>{original.onKeyDown?.(event);if(onRow||!['Enter',' '].includes(event.key)||event.target.closest('button,a,input,select,textarea,[role="button"],[role="checkbox"]'))return;event.preventDefault();toggle(row)},tabIndex:original.tabIndex??0}}}/>;
