async function downloadExcel(columns,rows,filename) {
  try {
    const {default:ExcelJS}=await import('exceljs');
    const workbook=new ExcelJS.Workbook();
    const sheet=workbook.addWorksheet('Бүртгэл');
    sheet.columns=columns.map(label=>({header:label,key:label,width:Math.min(32,Math.max(16,label.length+5))}));
    rows.forEach(row=>sheet.addRow(row));
    sheet.getRow(1).font={bold:true,color:{argb:'FFFFFFFF'}};
    sheet.getRow(1).fill={type:'pattern',pattern:'solid',fgColor:{argb:'FF7656D8'}};
    const blob=new Blob([await workbook.xlsx.writeBuffer()],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'});
    const path=await saveBlob(blob,filename);
    if(path)message.success(`Excel хадгаллаа: ${path}`);
  } catch(error) {message.error(error.message||'Excel татаж чадсангүй')}
}
async function readExcel(file) {
  const {default:ExcelJS}=await import('exceljs');
  const workbook=new ExcelJS.Workbook();await workbook.xlsx.load(await file.arrayBuffer());
  const sheet=workbook.worksheets[0];if (!sheet) throw new Error('Excel sheet олдсонгүй');
  const headers=sheet.getRow(1).values.slice(1).map(String);
  const rows=[];
  for(let index=2;index<=sheet.rowCount;index++) {
    const row=sheet.getRow(index);
    if (!row.hasValues) continue;
    rows.push({...Object.fromEntries(headers.map((header,i)=>{const cell=row.getCell(i+1);const value=cell.value&&typeof cell.value==='object'&&'result' in cell.value?cell.value.result:cell.value;return [header,value instanceof Date?dayjs(value).format(/түлш\s*авсан\s*цаг/i.test(header)?'HH:mm':'YYYY-MM-DD'):typeof value==='number'?value:cell.text]})),__excelRow:index});
  }
  return rows;
}
async function api(url, options={}) {
  const projectId=sessionStorage.getItem('mpc-project-id');
  const res=await fetch(`/api${url}`,{...options,headers:{'Content-Type':'application/json',...(projectId?{'X-Project-ID':projectId}:{}),...(options.headers || {})},credentials:'same-origin'});
  const body=await res.json().catch(()=>({}));
  if (!res.ok) throw new Error(body.error || 'Алдаа гарлаа');
  return body;
}
