function ImportButton({type,onDone,user,equipment=[],employees=[]}) {
  const [preview,setPreview]=useState(null);
  const [issues,setIssues]=useState([]);
  const [checking,setChecking]=useState(false);
  const [saving,setSaving]=useState(false);
  const [allData,setAllData]=useState(null);
  const schema=schemas[type];
  const importFields=schema.fields.filter(f=>!(user.role==='camp'&&f.key==='campId')&&!(user.role==='camp'&&type==='mealFeedback'&&['approvedAllowance','hrStatus','hrNote'].includes(f.key))&&!(type==='productionEntries'&&f.key==='operatorId'));
  if(type==='productionEntries')importFields.push(field('operatorCode','Операторын код'));
  const exportTemplate=async()=>{if(type==='productionEntries'){try{const path=await saveProductionTemplate(importFields);if(path)message.success(`Excel хадгаллаа: ${path}`)}catch(error){message.error(error.message)}}else downloadExcel(importFields.map(f=>f.label),[],`${type}-загвар.xlsx`)};
  const prepareRows=rows=>{
    const localIssues=[];
    const prepared=rows.map(row=>{
      const value={...row};
      if(type==='productionEntries'){
        delete value.operatorId;
        const code=String(value.operatorCode||'').trim();
        if(code){const matches=employees.filter(employee=>String(employee.code||'').trim()===code);if(matches.length===1)value.operatorId=matches[0].id;else localIssues.push({row:value.__excelRow,message:`${code} операторын код ${matches.length?'давхардсан':'Ажилтан бүртгэлд олдсонгүй'}`})}
        delete value.operatorCode;
      }
      if(type==='fuel'){
        const park=normalizePark(value.parkNo);
        const machine=equipment.find(item=>normalizePark(item.parkNo)===park);
        if(machine){value.equipmentId=machine.id;value.equipmentType ||= machine.kind}
        else if(park&&park!=='БУСАД'&&!value.equipmentId)localIssues.push({row:value.__excelRow,message:`${park} парк энэ төсөлд бүртгэлгүй байна`});
      }
      return value;
    });
    return {prepared,localIssues};
  };
  const checkRows=async rows=>{
    setChecking(true);
    try{const {prepared,localIssues}=prepareRows(rows);const result=await api(`/import/${type}/check`,{method:'POST',body:JSON.stringify({rows:prepared})});const found=[...localIssues,...result.issues];setIssues(found);return {prepared,found}}
    finally{setChecking(false)}
  };
  const upload=async file=>{
    try {
      const raw=await readExcel(file);
      if (!raw.length) throw new Error('Excel файл хоосон байна');
      const rows=raw.map(row=>({...Object.fromEntries(importFields.map(f=>{
        const value=row[f.label]!==undefined?row[f.label]:row[f.key];
        return [f.key,value];
      })),__excelRow:row.__excelRow,...(user.role==='camp'&&['campStays','guests','mealMenus','mealFeedback','bedAssignments'].includes(type)?{campId:user.campId}:{})}));
      if(type==='fuel')rows.forEach((row,index)=>{
        const normalized=Object.fromEntries(Object.entries(raw[index]).map(([key,val])=>[String(key).replace(/\s+/g,' ').replace(/[^\p{L}\p{N}]/gu,'').toUpperCase(),val]));
        const source=keys=>keys.map(key=>normalized[key]).find(value=>value!==undefined&&value!=='');
        row.date ||= source(['ТҮЛШАВСАНОГНОО','ӨДӨР']);
        row.parkNo ||= source(['ПАРКДУГААР']);
        row.equipmentType ||= source(['ТЕХНИКИЙНТӨРӨЛ']);
        row.liters ||= source(['ТҮЛШАВСАНЛИТР','ТҮЛШАВСАНЛИТРЛ']);
        row.receivedTime ||= source(['ТҮЛШАВСАНЦАГМИНУТ','ТҮЛШАВСАНЦАГ']);
        row.motorHours ||= source(['ТҮЛШАВСАНМОТЦАГ','ТҮЛШАВСАНМОТОЦАГ']);
        row.notes ||= source(['ТАЙЛБАРМОТЦАГАЖИЛЛАХГҮЙБОЛТЭМДЭГЛЭХ','ТАЙЛБАР']);
        row.kind ||= 'usage';
        const slashDate=String(row.date||'').match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
        if(slashDate)row.date=`${slashDate[3]}-${slashDate[1].padStart(2,'0')}-${slashDate[2].padStart(2,'0')}`;
      });
      setPreview({filename:file.name,rows});
      await checkRows(rows);
    } catch(e) {message.error(e.message)}
    return false;
  };
  const submit=async()=>{
    if(!preview)return;
    setSaving(true);
    try{const {prepared,found}=await checkRows(preview.rows);if(found.length)return;const result=await api(`/import/${type}`,{method:'POST',body:JSON.stringify({rows:prepared,filename:preview.filename})});message.success(`${result.count} мөр импортлов`);setPreview(null);setIssues([]);onDone()}
    catch(error){const match=String(error.message).match(/^(\d+)-р мөр:\s*(.*)$/);if(match)setIssues([{row:preview.rows[Number(match[1])-2]?.__excelRow||Number(match[1]),message:match[2]}]);else message.error(error.message)}finally{setSaving(false)}
  };
  const importAllData=async file=>{
    try {
      const fileBase64=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file)});
      const result=await api('/equipment-all-data/preview',{method:'POST',body:JSON.stringify({fileBase64})});
      setAllData({filename:file.name,fileBase64,originalRows:result.rows.map(row=>row.sourceRow),rows:result.rows,issues:result.issues,totalRows:result.totalRows});
    } catch(e) {message.error(e.message)}
    return false;
  };
  const checkAllData=async()=>{if(!allData)return [];setChecking(true);try{const result=await api('/equipment-all-data/check',{method:'POST',body:JSON.stringify({rows:allData.rows})});setAllData(current=>({...current,issues:result.issues}));return result.issues}finally{setChecking(false)}};
  const submitAllData=async()=>{if(!allData)return;setSaving(true);try{if((await checkAllData()).length)return;const remaining=new Set(allData.rows.map(row=>Number(row.sourceRow)));const result=await api('/equipment-all-data/import',{method:'POST',body:JSON.stringify({fileBase64:allData.fileBase64,filename:allData.filename,overrides:allData.rows.map(row=>({sourceRow:row.sourceRow,values:row})),excludedRows:allData.originalRows.filter(row=>!remaining.has(Number(row)))})});message.success(`ALL DATA: ${result.added} шинэ, ${result.updated} шинэчилсэн техник`);setAllData(null);onDone()}catch(error){const match=String(error.message).match(/^(\d+)-р мөр:\s*(.*)$/);if(match)setAllData(current=>({...current,issues:[{row:Number(match[1]),sheet:'ALL DATA',message:match[2]}]}));else message.error(error.message)}finally{setSaving(false)}};
  return <><Space wrap><Button icon={<DownloadOutlined/>} onClick={exportTemplate}>Excel загвар</Button><Upload accept=".xlsx" showUploadList={false} beforeUpload={upload}><Button icon={<UploadOutlined/>}>Excel импорт</Button></Upload>{type==='equipment'&&<Upload accept=".xlsx" showUploadList={false} beforeUpload={importAllData}><Button icon={<UploadOutlined/>}>ALL DATA импорт</Button></Upload>}</Space><ExcelImportReview open={!!preview} title={`${schema.title} · Excel импорт`} filename={preview?.filename} rows={preview?.rows} fields={importFields} issues={issues} checking={checking} saving={saving} onChange={(row,key,value)=>{setPreview(current=>({...current,rows:current.rows.map(item=>item.__excelRow===row?{...item,[key]:value}:item)}));}} onRemove={row=>{setPreview(current=>({...current,rows:current.rows.filter(item=>item.__excelRow!==row)}));setIssues(current=>current.filter(issue=>Number(issue.row)!==row))}} onCheck={()=>preview&&checkRows(preview.rows)} onImport={submit} onClose={()=>{setPreview(null);setIssues([])}}/><ExcelImportReview open={!!allData} title="ALL DATA · Excel импорт" filename={allData?.filename} rows={allData?.rows} fields={schemas.equipment.fields.filter(field=>['parkNo','kind','brand','model','vin','plateNo','site','owner','currentHours','status','availability','year','sourceStatus','notes'].includes(field.key))} issues={allData?.issues||[]} checking={checking} saving={saving} onChange={(row,key,value)=>setAllData(current=>({...current,rows:current.rows.map(item=>item.sourceRow===row?{...item,[key]:value}:item),issues:current.issues}))} onRemove={row=>setAllData(current=>({...current,rows:current.rows.filter(item=>item.sourceRow!==row),issues:current.issues.filter(issue=>Number(issue.row)!==row)}))} onCheck={checkAllData} onImport={submitAllData} onClose={()=>setAllData(null)}/></>;
}

function ProductionImport({onDone,equipment}) {
  const [preview,setPreview]=useState(null);
  const [kind,setKind]=useState('actual');
  const [issues,setIssues]=useState([]);
  const [checking,setChecking]=useState(false);
  const [saving,setSaving]=useState(false);
  async function load(file) {
    try {const summary=await parseProductionWorkbook(file);setPreview({file,summary});setIssues(summary.issues);setKind('actual')}
    catch(error){message.error(error.message)}
    return false;
  }
  const summary=preview?.summary;
  const sheet=kind==='actual'?'Actual':'Plan';
  const rows=kind==='actual'?summary?.actualRows||[]:summary?.planRows||[];
  const visibleIssues=issues.filter(issue=>issue.sheet===sheet);
  async function checkRows() {
    if(!preview)return [];
    setChecking(true);
    try{const result=await api('/import/productionEntries/check',{method:'POST',body:JSON.stringify({rows})});const next=result.issues.map(issue=>({...issue,sheet}));setIssues(current=>[...current.filter(issue=>issue.sheet!==sheet),...next]);return next}
    finally{setChecking(false)}
  }
  async function commit() {
    if(!rows.length)return message.warning('Импортлох мөр алга');
    setSaving(true);
    try {if((await checkRows()).length)return;const result=await api('/import/productionEntries',{method:'POST',body:JSON.stringify({filename:preview.file.name,rows})});message.success(`${result.count} ${kind==='actual'?'бодит рейс':'төлөвлөгөөний мөр'} амжилттай импортлогдлоо`);setPreview(null);setIssues([]);onDone()}
    catch(error){const match=String(error.message).match(/^(\d+)-р мөр:\s*(.*)$/);if(match)setIssues(current=>[...current,{row:rows[Number(match[1])-2]?.__excelRow||Number(match[1]),sheet,message:match[2]}]);else message.error(error.message)} finally{setSaving(false)}
  }
  const knownParks=new Set(equipment.map(machine=>String(machine.parkNo).trim().toUpperCase()));
  const unmatchedParks=[...new Set((rows||[]).flatMap(row=>[row.haulParkNo,row.excavatorParkNo]).filter(Boolean))].filter(park=>!knownParks.has(park));
  const extra=<><Segmented value={kind} onChange={setKind} options={[{value:'actual',label:'Бодит рейс'},{value:'plan',label:'Төлөвлөгөө'}]}/>{summary&&<div className="mt-3 flex gap-2"><Tag>Бодит {summary.actualRows.length} мөр · {money(summary.actualAmount)} м³</Tag><Tag>Төлөвлөгөө {summary.planRows.length} мөр · {money(summary.planAmount)} м³</Tag></div>}{unmatchedParks.length>0&&<Alert className="my-3" type="warning" showIcon message={`${unmatchedParks.length} парк дугаар Техник бүртгэлд байхгүй`} description={unmatchedParks.join(', ')}/>}</>;
  return <><Upload accept=".xlsx" showUploadList={false} beforeUpload={load}><Button icon={<UploadOutlined/>}>Ууцар тайлан импорт</Button></Upload><ExcelImportReview open={!!preview} title="Ууцар бүтээлийн Excel импорт" filename={preview?.file.name} rows={rows} fields={schemas.productionEntries.fields.filter(field=>!['operatorId','sourceFile','sourceSheet','sourceRow'].includes(field.key))} issues={visibleIssues} checking={checking} saving={saving} extra={extra} onChange={(row,key,value)=>{setPreview(current=>({...current,summary:{...current.summary,[kind==='actual'?'actualRows':'planRows']:current.summary[kind==='actual'?'actualRows':'planRows'].map(item=>item.__excelRow===row?{...item,[key]:value}:item)}}));}} onRemove={row=>{setPreview(current=>({...current,summary:{...current.summary,[kind==='actual'?'actualRows':'planRows']:current.summary[kind==='actual'?'actualRows':'planRows'].filter(item=>item.__excelRow!==row)}}));setIssues(current=>current.filter(issue=>issue.sheet!==sheet||Number(issue.row)!==row))}} onCheck={checkRows} onImport={commit} onClose={()=>{setPreview(null);setIssues([])}}/></>;
}

function ProductionSummary({entries,date,defaultPeriod='day'}) {
  const [period,setPeriod]=useState(defaultPeriod);
  const selected=dayjs(date);
  const start=period==='year'?selected.startOf('year'):period==='month'?selected.startOf('month'):period==='week'?selected.subtract((selected.day()+6)%7,'day'):selected;
  const end=period==='year'?selected.endOf('year'):period==='month'?selected.endOf('month'):period==='week'?start.add(6,'day'):selected;
  const rows=entries.filter(row=>row.date>=start.format('YYYY-MM-DD')&&row.date<=end.format('YYYY-MM-DD'));
  const actual=rows.filter(row=>row.kind==='actual');
  const planned=rows.filter(row=>row.kind==='plan');
  const total=items=>items.reduce((sum,row)=>sum+num(row.amount),0);
  const by=(key,items)=>[...new Set(items.map(row=>String(row[key]||'').trim()).filter(Boolean))].sort().map(name=>({name,actual:total(actual.filter(row=>String(row[key]||'').trim()===name)),plan:total(planned.filter(row=>String(row[key]||'').trim()===name)),races:actual.filter(row=>String(row[key]||'').trim()===name).reduce((sum,row)=>sum+num(row.race),0)}));
  const groupRows=(key)=>by(key,rows);
  const columns=[{title:'Нэр',dataIndex:'name'},{title:'Бодит м³',dataIndex:'actual',render:money},{title:'Рейс',dataIndex:'races',render:money},{title:'Төлөвлөгөө м³',dataIndex:'plan',render:v=>v?money(v):'—'},{title:'Зөрүү м³',render:(_,row)=>row.plan?money(row.actual-row.plan):'—'}];
  return <Card bordered={false} title="Бүтээлийн тойм" className="table-card"><div className="mb-3 overflow-x-auto"><Segmented size="small" value={period} onChange={setPeriod} options={[{value:'day',label:'Өдөр'},{value:'week',label:'7 хоног'},{value:'month',label:'Сар'},{value:'year',label:'Жил'}]}/></div><div className="mb-3 text-xs text-slate-500">{start.format('YYYY.MM.DD')} – {end.format('YYYY.MM.DD')}</div><div className="grid gap-3 sm:grid-cols-3"><div className="rounded-xl bg-violet-50 p-4"><div className="text-xs text-slate-500">Бодит бүтээл</div><strong className="text-xl text-violet-700">{money(total(actual))} м³</strong><div className="text-xs">{money(actual.reduce((sum,row)=>sum+num(row.race),0))} рейс</div></div><div className="rounded-xl bg-blue-50 p-4"><div className="text-xs text-slate-500">Төлөвлөгөө</div><strong className="text-xl text-blue-700">{planned.length?`${money(total(planned))} м³`:'—'}</strong><div className="text-xs">{planned.length?'Энэ хугацааны зорилт':'Энэ хугацаанд зорилт байхгүй'}</div></div><div className="rounded-xl bg-emerald-50 p-4"><div className="text-xs text-slate-500">Биелэлт / зөрүү</div><strong className="text-xl text-emerald-700">{planned.length?`${Math.round(total(actual)/Math.max(1,total(planned))*100)}%`:'—'}</strong><div className="text-xs">{planned.length?`${money(total(actual)-total(planned))} м³ зөрүү`:'Харьцуулах зорилт алга'}</div></div></div>{rows.length>0&&<div className="mt-4 grid gap-4 xl:grid-cols-3">{[['material','Материал'],['excavatorParkNo','Ачигч'],['haulParkNo','Автосамосвал']].map(([key,label])=><div key={key}><strong className="mb-2 block text-sm">{label}</strong><Table size="small" rowKey="name" dataSource={groupRows(key)} columns={columns} pagination={{pageSize:5,showSizeChanger:false}} scroll={{x:480}}/></div>)}</div>}<p className="mb-0 mt-3 text-xs text-slate-500">Рейсийн бүтээлийг даалгаврын илгээсэн бүтээлтэй давхардуулж орлогод тооцоогүй. Орлогын үнэ батлагдсаны дараа материал тус бүрээр холбоно.</p></Card>;
}

function FleetImport({equipment,onDone}) {
  const [open,setOpen]=useState(false);
  const [matched,setMatched]=useState(null);
  const [saving,setSaving]=useState(false);
  const [checking,setChecking]=useState(false);
  const rows=matched?.records||activeFleet.map(row=>({...row,status:'inactive',availability:'inactive',site:'Ууцар'}));
  const existing=new Set(equipment.map(row=>String(row.parkNo).trim()));
  const missing=rows.filter(row=>!existing.has(row.parkNo));
  async function load(file){try{setMatched({...await matchFleetSerials(file),filename:file.name});message.success('Серийн мэдээллийг парк дугаараар тулгалаа')}catch(error){message.error(error.message)}return false}
  async function checkMatched(){
    if(!matched)return [];
    setChecking(true);
    try{
      const next=matchFleetSerialRows(matched.sourceRows);
      const sourced=missing.filter(row=>row.sourceRow);
      const server=sourced.length?await api('/import/equipment/check',{method:'POST',body:JSON.stringify({rows:sourced.map(row=>({...row,__excelRow:row.sourceRow}))})}):{issues:[]};
      const issues=[...next.issues,...server.issues];
      setMatched(current=>({...current,issues}));
      return issues;
    }finally{setChecking(false)}
  }
  async function save(){
    if(!missing.length)return message.info('Бүх парк дугаар бүртгэлтэй байна');
    setSaving(true);
    try{
      if(matched&&(await checkMatched()).length)return;
      const result=await api('/import/equipment',{method:'POST',body:JSON.stringify({filename:matched?.filename||'Диспетчерийн парк дугаарын жагсаалт',rows:missing.map(row=>({...row,notes:'Диспетчерийн парк дугаарын эх жагсаалт. Ажлын бэлэн байдлыг баталгаажаагүй.'}))})});
      message.success(`${result.count} техникийн парк дугаар амжилттай бүртгэгдлээ`);setOpen(false);setMatched(null);onDone();
    }catch(error){message.error(error.message)}finally{setSaving(false)}
  }
  return <><Button icon={<UploadOutlined/>} onClick={()=>setOpen(true)}>Парк дугаарын жагсаалт</Button>
    <Modal title="Техникийн парк дугаар бүртгэх" open={open&&!matched} width={740} onCancel={()=>setOpen(false)} footer={<Space><Button onClick={()=>setOpen(false)}>Болих</Button><Button type="primary" loading={saving} disabled={!missing.length} onClick={save}>{missing.length} техник нэмэх</Button></Space>}>
      <Alert showIcon type="info" message="Диспетчерийн жагсаалтад байгаа парк дугаарууд" description="Одоо бүртгэлтэй техникийг давхардуулахгүй. Шинэ техникийг бэлэн бус төлөвтэй оруулна; ажиллагааны төлөвийг дараа нь шалгаж батална."/>
      <div className="mt-4"><Upload accept=".xlsx" showUploadList={false} beforeUpload={load}><Button icon={<UploadOutlined/>}>Серийн дугаарын Excel-ээр тулгах</Button></Upload></div>
      <div className="mt-4 flex gap-2"><Tag>Нийт {rows.length}</Tag><Tag color="green">Шинэ {missing.length}</Tag><Tag>Бүртгэлтэй {rows.length-missing.length}</Tag></div>
      <Table className="mt-3" size="small" rowKey="parkNo" pagination={{pageSize:8}} scroll={{y:310}} dataSource={rows} columns={[{title:'Парк',dataIndex:'parkNo'},{title:'Төрөл',dataIndex:'kind'},{title:'Марк',dataIndex:'model'},{title:'Серийн №',dataIndex:'vin',render:v=>v?'Таарсан':'—'},{title:'Төлөв',render:(_,r)=>existing.has(r.parkNo)?<Tag>Бүртгэлтэй</Tag>:<Tag color="blue">Шинэ</Tag>}]}/>
    </Modal>
    <ExcelImportReview open={!!matched} title="Серийн дугаарын Excel шалгах" filename={matched?.filename} rows={matched?.sourceRows} fields={[{key:'parkNo',label:'Парк дугаар'},{key:'vin',label:'VIN / серийн дугаар'},{key:'brand',label:'Марк'},{key:'plateNo',label:'Улсын дугаар'},{key:'year',label:'Он'}]} issues={matched?.issues||[]} checking={checking} saving={saving} extra={<Tag color="blue">Тулгасан {matched?.matched||0} парк</Tag>} onChange={(row,key,value)=>setMatched(current=>({...current,...matchFleetSerialRows(current.sourceRows.map(item=>item.sourceRow===row?{...item,[key]:value}:item))}))} onRemove={row=>setMatched(current=>({...current,...matchFleetSerialRows(current.sourceRows.filter(item=>item.sourceRow!==row))}))} onCheck={checkMatched} onImport={save} onClose={()=>{setMatched(null);setOpen(true)}}/>
  </>;
}

function EquipmentSourceReview({equipment,projectName,onDone}) {
  const [open,setOpen]=useState(false);
  const [source,setSource]=useState('chand2026');
  const [preview,setPreview]=useState(null);
  const [sourceIssues,setSourceIssues]=useState([]);
  const [checking,setChecking]=useState(false);
  const [saving,setSaving]=useState(false);
  const choices={
    chand2026:{label:'Чанд-Үйлс · 2026',project:'Чанд-Үйлс',parser:parseChandFleet,filename:'Техник мэдээлэл.xlsx'},
    uutsarSerial:{label:'Ууцар · серийн жагсаалт',project:'Ууцар',parser:parseUutsarFleet,filename:'Заамар Техникийн мэдээлэл_1.xlsx'},
    otr:{label:'Чанд-Үйлс · хуучин OTR',project:'Чанд-Үйлс',parser:parseOtrEquipment,filename:'OTR техникийн мэдээлэл.xlsx'},
    sold:{label:'Зарсан техник',project:null,parser:parseSoldEquipment,filename:'Зарсан техник.xlsx'},
  };
  const selected=choices[source];
  const review=(preview?.rows||[]).map(row=>{
    if(source==='sold')return {...row,reviewStatus:'summary'};
    const park=normalizePark(row.parkNo),vin=normalizeVin(row.vin);
    const byPark=equipment.find(item=>normalizePark(item.parkNo)===park);
    const byVin=vin?equipment.find(item=>normalizeVin(item.vin)===vin):null;
    if(byPark&&byVin&&byPark.id!==byVin.id||byVin&&normalizePark(byVin.parkNo)!==park)return {...row,reviewStatus:'conflict'};
    if(!byPark)return {...row,reviewStatus:'new'};
    try{
      const {id,createdAt,updatedAt,...before}=byPark;
      const after=mergeEquipmentSource(before,row);
      return {...row,reviewStatus:JSON.stringify(before)===JSON.stringify(after)?'same':'update'};
    }catch{return {...row,reviewStatus:'conflict'}}
  });
  const newRows=review.filter(row=>row.reviewStatus==='new');
  const updateRows=review.filter(row=>row.reviewStatus==='update');
  const conflicts=review.filter(row=>row.reviewStatus==='conflict');
  const submitRows=review.filter(row=>row.reviewStatus==='new'||row.reviewStatus==='update').map(({reviewStatus,...row})=>row);
  async function load(file){
    try{const parsed=await selected.parser(file);setPreview({...parsed,filename:file.name});setSourceIssues(parsed.issues);setOpen(false);message.success('Excel-ийн мөрүүдийг шалгалаа')}
    catch(error){message.error(error.message)}
    return false;
  }
  async function checkSourceRows(){
    if(!preview)return [];
    setChecking(true);
    try{
      const found=[];const parks=new Set();const vins=new Set();
      for(const row of review){
        const errors=[];const park=normalizePark(row.parkNo),vin=normalizeVin(row.vin);
        if(source==='sold'){
          if(!String(row.model||'').trim())errors.push('Загвар оруулна уу');
          if(!Number.isInteger(Number(row.count))||Number(row.count)<1)errors.push('Тоо ширхэг 1-ээс их бүхэл тоо байна');
        }else{
          if(!park)errors.push('Парк дугаар оруулна уу');
          if(!String(row.kind||'').trim())errors.push('Төрөл оруулна уу');
          if(!String(row.model||'').trim())errors.push('Загвар оруулна уу');
          if(source==='chand2026'&&!vin)errors.push('VIN оруулна уу');
          if(park&&parks.has(park))errors.push('Парк дугаар файл дотор давхардсан');
          if(vin&&vins.has(vin))errors.push('VIN файл дотор давхардсан');
          if(park)parks.add(park);if(vin)vins.add(vin);
          if(row.reviewStatus==='conflict')errors.push('Парк/VIN бүртгэлтэй техниктэй зөрж байна');
        }
        if(errors.length)found.push({row:row.sourceRow,sheet:row.sourceSheet||row.__sheet,message:errors.join('; ')});
      }
      if(source!=='sold'&&projectName===selected.project){
        const newCandidates=review.filter(row=>row.reviewStatus==='new'&&!found.some(issue=>Number(issue.row)===Number(row.sourceRow)));
        if(newCandidates.length){const result=await api('/import/equipment/check',{method:'POST',body:JSON.stringify({rows:newCandidates})});found.push(...result.issues)}
      }
      setSourceIssues(found);return found;
    }finally{setChecking(false)}
  }
  async function save(){
    if(projectName!==selected.project)return message.error(`Эхлээд ${selected.project} төслийг сонгоно уу`);
    if((await checkSourceRows()).length)return;
    const rows=source==='otr'?newRows.map(({reviewStatus,...row})=>row):submitRows;
    if(!rows.length)return message.info('Нэмэх эсвэл нөхөх техник алга');
    setSaving(true);
    try{
      const endpoint=source==='otr'?'/import/equipment':'/equipment-source/import';
      const result=await api(endpoint,{method:'POST',body:JSON.stringify({source,filename:preview.filename,rows})});
      message.success(source==='otr'?`${result.count} техник бүртгэгдлээ`:`${result.added} шинэ, ${result.updated} техникийн дутуу мэдээлэл нөхөгдлөө`);
      setOpen(false);setPreview(null);onDone();
    }catch(error){const match=String(error.message).match(/^(\d+)-р (?:мөр|техникийн).*?:?\s*(.*)$/);if(match)setSourceIssues([{row:rows[Number(match[1])-1]?.sourceRow||Number(match[1]),message:match[2]||error.message}]);else message.error(error.message)}finally{setSaving(false)}
  }
  const close=()=>{setOpen(false);setPreview(null)};
  const fields=source==='sold'?[{key:'model',label:'Загвар'},{key:'count',label:'Тоо ширхэг',type:'number'},{key:'buyer',label:'Худалдан авагч'},{key:'location',label:'Байршил'}]:[{key:'parkNo',label:'Парк дугаар'},{key:'vin',label:'VIN / арлын дугаар'},{key:'kind',label:'Төрөл'},{key:'brand',label:'Марк'},{key:'model',label:'Загвар'},{key:'plateNo',label:'Улсын дугаар'},{key:'year',label:'Он'},{key:'tankCapacityLiters',label:'Савны багтаамж л',type:'number'},{key:'notes',label:'Тайлбар'}];
  return <><Button icon={<UploadOutlined/>} onClick={()=>setOpen(true)}>Төслийн техникийн Excel</Button><Modal title="Техникийн эх файл сонгох" open={open} width={650} onCancel={close} footer={<Button onClick={close}>Хаах</Button>}><Select className="w-full" value={source} onChange={value=>{setSource(value);setPreview(null)}} options={Object.entries(choices).map(([value,item])=>({value,label:item.label}))}/><Alert className="my-3" showIcon type={projectName===selected.project||source==='sold'?'info':'warning'} message={source==='sold'?'Зарсан техникийн нэгтгэл — зөвхөн шалгана':`Импорт хийх төсөл: ${selected.project}`} description={`Одоо сонгосон төсөл: ${projectName||'—'}`}/><Upload accept=".xlsx" showUploadList={false} beforeUpload={load}><Button icon={<UploadOutlined/>}>{selected.filename} сонгох</Button></Upload></Modal><ExcelImportReview open={!!preview} title="Техникийн эх Excel-ийг шалгаж оруулах" filename={preview?.filename} rows={preview?.rows} fields={fields} issues={sourceIssues} checking={checking} saving={saving} extra={<div className="mb-3 flex flex-wrap gap-2"><Tag>{selected.label}</Tag>{source!=='sold'&&<><Tag color="green">Шинэ {newRows.length}</Tag><Tag color="blue">Нөхөх {updateRows.length}</Tag><Tag color="red">Зөрүүтэй {conflicts.length}</Tag></>}{projectName!==selected.project&&source!=='sold'&&<Alert type="warning" showIcon message={`${selected.project} төслийг сонгоно уу`}/>}</div>} onChange={(row,key,value)=>{setPreview(current=>({...current,rows:current.rows.map(item=>item.sourceRow===row?{...item,[key]:value}:item)}));}} onRemove={row=>{setPreview(current=>({...current,rows:current.rows.filter(item=>item.sourceRow!==row)}));setSourceIssues(current=>current.filter(issue=>Number(issue.row)!==row))}} onCheck={checkSourceRows} onImport={source==='sold'?null:save} onClose={close}/></>;
}

function RecordPage({type,lists,submissions,refresh,user,date,setDate,projectName,permissions={},onHelp}) {
  const [editing,setEditing]=useState(undefined);
  const [open,setOpen]=useState(false);
  const [sourceRow,setSourceRow]=useState(null);
  const [search,setSearch]=useState('');
  const [initialDateAdjusted,setInitialDateAdjusted]=useState(false);
  const schema=schemas[type];
  const canCreate=user.role==='admin'||permissions[type]?.includes('create');
  const canUpdate=user.role==='admin'||permissions[type]?.includes('update');
  const canDelete=user.role==='admin'||permissions[type]?.includes('delete');
  const data=lists[type] || [];
  useEffect(()=>{if(type==='productionEntries'&&!initialDateAdjusted&&data.length){setDate([...new Set(data.map(row=>row.date))].sort().at(-1));setInitialDateAdjusted(true)}},[type,data,initialDateAdjusted,setDate]);
  const employeeName=id=>{const e=lists.employees.find(x=>x.id===Number(id)); return e?`${e.lastName} ${e.firstName}`:'—'};
  const equipmentName=id=>{const e=lists.equipment.find(x=>x.id===Number(id)); return e?`${e.parkNo} · ${e.model}`:'—'};
  const render=(value,f,row)=>{
    if (f.key==='employeeId') return employeeName(value);
    if (f.key==='operatorId') {const operator=lists.employees.find(item=>item.id===Number(value));return operator?`${operator.lastName} ${operator.firstName} · ${operator.code||operator.register||operator.id}`:'—'};
    if (f.key==='originalEmployeeId'||f.key==='replacementEmployeeId'||/^operator[A-D]Id$/.test(f.key)) return employeeName(value);
    if (f.key==='guestId') return lists.guests.find(x=>x.id===Number(value))?.name || '—';
    if (f.key==='equipmentId'||f.key==='removedEquipmentId'||f.key==='installedEquipmentId') return equipmentName(value);
    if (f.key==='condition') return statusLabels[value] || value || '—';
    if (f.key==='performedBy' && Number.isInteger(Number(value)) && lists.employees.some(e=>e.id===Number(value))) return employeeName(value);
    if (f.key==='campId') return lists.camps.find(x=>x.id===Number(value))?.name || '—';
    if (f.key==='planId') return lists.plans.find(x=>x.id===Number(value))?.name || '—';
    if (f.key==='warehouseId') return lists.warehouses.find(x=>x.id===Number(value))?.name || '—';
    if (f.key==='parts') return Array.isArray(value)?value.map(part=>`${part.name} · ${part.partNo||'—'} · ${part.quantity} ш`).join(', ')||'—':'—';
    if (f.key==='transferIds') return Array.isArray(value)?value.map(id=>{const transfer=lists.equipmentTransfers.find(x=>x.id===Number(id));return transfer?`#${transfer.id} · ${transfer.partName} · ${transfer.quantity} ш`:`#${id}`}).join(', ')||'—':'—';
    if (f.key==='employeeIds') return Array.isArray(value)?value.map(employeeName).join(', ') || '—':'—';
    if (f.key==='equipmentIds') return Array.isArray(value)?value.map(equipmentName).join(', ') || '—':'—';
    if (f.key==='status' || f.key==='shift' || f.key==='availability' || f.key==='hrStatus' || f.key==='mealType' || f.key==='kind' && type==='fuel') return <StatusTag value={value}/>;
    if (f.key==='workedMotorHours') return money(Math.max(0,num(row.endHours)-num(row.startHours)));
    if (f.type==='number') return value===undefined || value===''?'—':money(value);
    if (f.key==='bankAccount') return value || '—';
    return value || '—';
  };
  const featured=type==='employees'?['firstName','lastName','register','branch','position','shiftGroup','status']:type==='attendance'?['date','employeeId','campId','status','plannedHours','actualHours']:type==='equipment'?['parkNo','kind','model','warehouseId','currentHours','availability']:type==='equipmentTransfers'?['removedDate','removedEquipmentId','partName','quantity','condition','installedEquipmentId','installedDate','performedBy']:type==='camps'?['name','location','capacity','workType']:type==='warehouses'?['name','location','manager']:type==='plans'?['name','startDate','endDate','shift','warehouseId','requiredWorkers','employeeIds','requiredEquipment','equipmentIds']:type==='productionEntries'?['date','kind','shift','operatorId','haulParkNo','excavatorParkNo','materialType','race','amount']:type==='assignments'?['date','title','shift','employeeId','equipmentId','plannedFuel']:type==='fuel'?['date','parkNo','equipmentType','liters','receivedTime','motorHours']:type==='machineLogs'?['date','workShift','equipmentId','employeeId','shiftGroup','startHours','endHours','workedMotorHours','productiveHours','repairHours','dispatcherChecked']:type==='guests'?['name','organization','arrivalDate','departureDate','campId']:type==='campStays'?['date','category','employeeId','guestId','count','breakfast','lunch','dinner']:type==='maintenance'?['date','equipmentId','workOrderNo','failureCategory','failureDescription','startTime','endTime','minutes','status','transferIds']:type==='travelExpenses'?['date','employeeId','amount','paid']:type==='shiftOverrides'?['date','originalEmployeeId','replacementEmployeeId','reason']:type==='mealMenus'?['date','campId','mealType','name','ingredients']:type==='mealFeedback'?['date','campId','employeeId','mealType','comment','hrStatus','approvedAllowance']:type==='bedAssignments'?['employeeId','campId','building','room','bed','startDate','endDate']:['date','name','category','amount'];
  const columns=featured.map(key=>{const f=schema.fields.find(x=>x.key===key); return {title:f.label,dataIndex:key,key,render:(value,row)=>render(value,f,row),ellipsis:key!=='notes',...(key==='notes'?{width:320}: {})};});
  if (type==='employees') columns.push({title:'14/14 ээлж',key:'rotation',render:(_,row)=>{const s=workState(row,date,lists.attendance,lists.shiftOverrides);return <Space><StatusTag value={s.code}/><span>{s.daysLeft?`${s.daysLeft} өдөр үлдсэн`:''}</span></Space>}});
  if (type==='employees') columns.push({title:'Өдрийн төлөв',key:'daily',render:(_,row)=>{const state=workState(row,date,lists.attendance,lists.shiftOverrides);if(state.recorded)return <Tag color={statusColors[state.code]}>{state.label}</Tag>;if(!state.available)return state.label;const tasks=lists.assignments.filter(a=>a.date===date&&Number(a.employeeId)===row.id);const done=tasks.find(a=>submissions.some(s=>s.assignment_id===a.id&&s.status==='done'));if(done)return <Tag color={done.shift==='night'?'purple':'blue'}>{done.shift==='night'?'Шөнө ажилласан':'Өдөр ажилласан'}</Tag>;if(tasks.length)return <Tag color="gold">Даалгавартай</Tag>;return <Tag>Даалгаваргүй</Tag>}});
  if (type==='camps') columns.push({title:'Ажилтан / ажиллаж буй',key:'headcount',render:(_,row)=>{const staff=lists.employees.filter(e=>Number(e.campId)===row.id);return `${staff.length} / ${staff.filter(e=>workState(e,date,lists.attendance,lists.shiftOverrides).available).length}`}});
  if (type==='warehouses') columns.push({title:'Бэлэн / нийт техник',key:'availability',render:(_,row)=>{const machines=lists.equipment.filter(e=>Number(e.warehouseId)===row.id);return `${machines.filter(e=>e.status==='ready'&&e.availability==='available').length} / ${machines.length}`}});
  if (type==='machineLogs') columns.push({title:'Мото цагийн зөрүү',key:'motorHours',render:(_,row)=><strong>{Math.max(0,num(row.endHours)-num(row.startHours)).toFixed(1)} цаг</strong>});
  if (type==='equipment') columns.push({title:'A/B/C/D оператор',key:'crew',render:(_,row)=>['A','B','C','D'].map(group=>row[`operator${group}Id`]?`${group}: ${employeeName(row[`operator${group}Id`])}`:`${group}: —`).join(' · '),ellipsis:true});
  if (type==='equipmentTransfers') columns.push({title:'Холбоотой WO',key:'workOrders',render:(_,row)=>lists.maintenance.filter(maintenance=>Array.isArray(maintenance.transferIds)&&maintenance.transferIds.some(id=>Number(id)===row.id)).map(maintenance=>maintenance.workOrderNo||`#${maintenance.id}`).join(', ')||'—'});
  if (type==='equipment'&&user.role==='admin') columns.push({title:'Эх өгөгдөл',key:'source',render:(_,row)=>row.sourceData?<Button type="link" size="small" onClick={()=>setSourceRow(row)}>ALL DATA</Button>:'—'});
  if (type==='plans') columns.push({title:'Нөөцийн үнэлгээ',key:'readiness',render:(_,row)=>{const pool=Array.isArray(row.employeeIds)&&row.employeeIds.length?lists.employees.filter(e=>row.employeeIds.some(id=>Number(id)===e.id)):lists.employees;const workers=pool.filter(e=>workState(e,date,lists.attendance,lists.shiftOverrides).available).length;const equipment=equipmentAvailability(row,lists);const stock=lists.fuel.reduce((n,f)=>n+(f.kind==='receipt'?num(f.liters):-num(f.liters)),0);const ok=workers>=num(row.requiredWorkers)&&equipment.missing===0&&stock>=num(row.plannedFuel);return <Tag color={ok?'green':'orange'}>{ok?'Хүрэлцээтэй':'Дутагдалтай'}</Tag>}});
  if (canUpdate||canDelete) columns.push({title:'Үйлдэл',key:'actions',width:110,render:(_,row)=><Space>{canUpdate&&!(type==='mealFeedback'&&user.role==='camp'&&row.hrStatus)&&<Button type="text" icon={<EditOutlined/>} onClick={()=>{setEditing(row);setOpen(true)}}/>}{canDelete&&<Popconfirm title="Бүртгэлийг устгах уу?" onConfirm={async()=>{try{await api(`/records/${type}/${row.id}`,{method:'DELETE'});await refresh();message.success('Амжилттай устгалаа')}catch(e){message.error(e.message)}}}><Button type="text" danger icon={<DeleteOutlined/>}/></Popconfirm>}</Space>});
  const filtered=data.filter(row=>(type!=='productionEntries'||row.date===date)&&`${JSON.stringify(row)} ${type==='maintenance'?equipmentName(row.equipmentId):''}`.toLowerCase().includes(search.toLowerCase()));
  const exportRows=()=>{const fields=type==='productionEntries'?[...schema.fields.filter(f=>f.key!=='operatorId'),field('operatorCode','Операторын код')]:schema.fields;return downloadExcel(fields.map(f=>f.label),filtered.map(row=>Object.fromEntries(fields.map(f=>[f.label,f.key==='operatorId'?employeeName(row.operatorId):f.key==='operatorCode'?lists.employees.find(e=>e.id===Number(row.operatorId))?.code||'':row[f.key]??'']))),`${type}-бүртгэл.xlsx`)};
  return <div className="page-stack flex flex-col gap-5"><div className="page-title-row flex items-end justify-between gap-4"><div><div className="eyebrow">БҮРТГЭЛИЙН САН</div><Title level={2}>{schema.title}</Title><Text type="secondary">Нийт {data.length} бүртгэл</Text></div><div className="toolbar flex flex-wrap items-center gap-2"><Button icon={<DownloadOutlined/>} onClick={exportRows}>Excel татах</Button>{canCreate?<><ImportButton type={type} onDone={refresh} user={user} equipment={lists.equipment} employees={lists.employees}/>{type==='productionEntries'&&<ProductionImport onDone={refresh} equipment={lists.equipment}/>} {type==='equipment'&&user.role==='admin'&&<><FleetImport equipment={lists.equipment} onDone={refresh}/><EquipmentSourceReview equipment={lists.equipment} projectName={projectName} onDone={refresh}/></>}<Button type="primary" icon={<PlusOutlined/>} onClick={()=>{setEditing(undefined);setOpen(true)}}>Шинэ бүртгэл</Button></>:null}</div></div>{type==='employees'&&<Alert type="info" showIcon message="14/14 ээлжийн төлөв" description="Ээлж эхэлсэн өдрөөс 14 өдөр ажиллаж, дараагийн 14 өдөр амарна. А, B, C, D бүлгийг тусад нь тэмдэглэнэ."/>}{type==='employees'&&<ShiftGroupSummary employees={lists.employees} date={date} attendance={lists.attendance} overrides={lists.shiftOverrides}/>}{type==='machineLogs'&&<Alert type="info" showIcon message="Мото цагийн тооцоо" description="Мото цаг = төгсгөлийн заалт − эхлэлийн заалт. Бүтээлтэй ажилласан, зогсолт, засвар болон бусад шалтгааны цагийн нийлбэр 12 байх ёстой."/>}{type==='plans'&&<Readiness lists={lists} date={date}/>}{type==='productionEntries'&&<ProductionSummary entries={data} date={date}/>}{type==='warehouses'&&<WarehouseOverview lists={lists}/>}{type==='camps'&&<CampRoster lists={lists} date={date}/>}{type==='campStays'&&<CampMealsSummary lists={lists} date={date}/>}<Card className="table-card" bordered={false}><div className="table-toolbar"><Input prefix={<SearchOutlined/>} placeholder={type==='maintenance'?'Парк дугаар, загвар, тайлбараар хайх':'Бүртгэлээс хайх'} value={search} onChange={e=>setSearch(e.target.value)} style={{width:260}}/>{(type==='employees'||type==='plans'||type==='productionEntries'||type==='camps'||type==='machineLogs'||type==='attendance'||type==='campStays')&&<DatePicker value={dayjs(date)} onChange={v=>v&&setDate(v.format('YYYY-MM-DD'))}/>}</div><Table rowKey="id" columns={columns} dataSource={filtered} expandable={{expandedRowRender:row=><Descriptions size="small" bordered column={{xs:1,sm:2}} items={schema.fields.map(f=>({key:f.key,label:f.label,children:render(row[f.key],f,row)}))}/>}} pagination={{pageSize:10,showSizeChanger:false}} scroll={{x:950}} locale={{emptyText:<Empty description="Бүртгэл алга. Шинэ бүртгэл нэмнэ үү."/>}}/></Card><Modal title={<Space>{editing?`${schema.singular} засах`:`${schema.singular} нэмэх`}<Button type="link" size="small" icon={<QuestionCircleOutlined/>} onClick={onHelp}>Бөглөх заавар</Button></Space>} open={open} footer={null} width={760} onCancel={()=>setOpen(false)} destroyOnHidden><RecordForm type={type} initial={editing} lists={lists} user={user} onCancel={()=>setOpen(false)} onSaved={()=>{setOpen(false);refresh()}}/></Modal><Modal title={`ALL DATA · ${sourceRow?.parkNo || ""}`} open={!!sourceRow} onCancel={()=>setSourceRow(null)} footer={null} width={760}><div className="max-h-[65vh] overflow-y-auto"><Table size="small" rowKey="column" pagination={false} dataSource={Object.entries(sourceRow?.sourceData || {}).filter(([,entry])=>String(entry.value || "").trim()).map(([column,entry])=>({column,heading:entry.heading,value:String(entry.value)}))} columns={[{title:"Багана",dataIndex:"column",width:85},{title:"Талбар",dataIndex:"heading"},{title:"Утга",dataIndex:"value"}]}/></div></Modal></div>
}

function equipmentAvailability(plan,lists) {
  const free=lists.equipment.filter(e=>e.status==='ready'&&e.availability==='available'&&(!plan.warehouseId||Number(e.warehouseId)===Number(plan.warehouseId)));
  const selected=Array.isArray(plan.equipmentIds)&&plan.equipmentIds.length?free.filter(e=>plan.equipmentIds.some(id=>Number(id)===e.id)):free;
  const needs=String(plan.equipmentNeeds || '').split(',').map(part=>{const [kind,count]=part.split(':');return {kind:String(kind || '').trim(),count:num(count)}}).filter(item=>item.kind&&item.count>0);
  const byKind=needs.map(item=>({...item,available:selected.filter(e=>String(e.kind || '').trim().toLowerCase()===item.kind.toLowerCase()).length}));
  const missing=Math.max(Math.max(0,num(plan.requiredEquipment)-selected.length),byKind.reduce((n,item)=>n+Math.max(0,item.count-item.available),0));
  return {count:selected.length,byKind,missing};
}

function motorHoursFor(lists,task) {
  const rows=lists.machineLogs.filter(log=>log.date===task.date&&Number(log.equipmentId)===Number(task.equipmentId)&&(!task.employeeId||Number(log.employeeId)===Number(task.employeeId)));
  return rows.length ? Number(rows.reduce((sum,log)=>sum+Math.max(0,num(log.endHours)-num(log.startHours)),0).toFixed(1)) : undefined;
}

function ShiftGroupSummary({employees,date,attendance,overrides}) {
  return <div className="grid grid-cols-2 gap-3 lg:grid-cols-4">{['A','B','C','D'].map(group=>{const staff=employees.filter(e=>e.shiftGroup===group);const working=staff.filter(e=>workState(e,date,attendance,overrides).available).length;return <div key={group} className="rounded-xl bg-white px-5 py-4 shadow-sm"><div className="flex items-center justify-between"><span className="text-xs font-bold text-violet-700">{group} ээлж</span><span className="text-[11px] text-slate-400">14/14</span></div><div className="mt-3 flex items-end gap-1"><strong className="text-2xl leading-none text-slate-800">{working}</strong><span className="text-xs text-slate-400">/ {staff.length} ажиллаж байна</span></div></div>})}</div>;
}

function RosterPage({lists,date,setDate}) {
  const [search,setSearch]=useState('');
  const employees=lists.employees;
  const rows=employees.map(employee=>({...employee,roster:workState(employee,date,lists.attendance,lists.shiftOverrides)}));
  const groups=['A','B','C','D','AB','CD'];
  const active=rows.filter(row=>row.roster.available);
  const unknown=rows.filter(row=>row.roster.code==='unassigned');
  const todayNumber=dayjs(date).startOf('day');
  const movements=rows.flatMap(row=>{
    if(!row.shiftStart||!['14/14','20/10'].includes(row.rotationPattern||'14/14'))return [];
    const cycle=row.rotationPattern==='20/10'?30:28;
    const work=row.rotationPattern==='20/10'?20:14;
    const diff=todayNumber.diff(dayjs(row.shiftStart).startOf('day'),'day');
    if(diff<0)return [];
    const phase=diff%cycle;
    return phase===0?[{...row,movement:'Ирж ажиллах'}]:phase===work?[{...row,movement:'Бууж амрах'}]:[];
  });
  const movementSummary=kind=>Object.entries(movements.filter(row=>row.movement===kind).reduce((counts,row)=>({...counts,[row.position]:(counts[row.position]||0)+1}),{})).sort((a,b)=>b[1]-a[1]);
  const filtered=rows.filter(row=>`${row.lastName} ${row.firstName} ${row.position} ${row.branch} ${row.shiftGroup}`.toLowerCase().includes(search.toLowerCase()));
  const exportRows=()=>downloadExcel(['Овог','Нэр','Салбар','Албан тушаал','Ээлж','Горим','Өдөр/шөнө','Төлөв'],filtered.map(row=>({'Овог':row.lastName,'Нэр':row.firstName,'Салбар':row.branch,'Албан тушаал':row.position,'Ээлж':row.shiftGroup,'Горим':row.rotationPattern,'Өдөр/шөнө':row.roster.shift==='night'?'Шөнө':row.roster.shift==='day'?'Өдөр':'—','Төлөв':row.roster.label})),`ээлжийн-мэдээ-${date}.xlsx`);
  return <div className="page-stack flex flex-col gap-5"><div className="page-title-row flex flex-wrap items-end justify-between gap-3"><div><div className="eyebrow">HR · ЭЭЛЖИЙН МЭДЭЭ</div><Title level={2}>Ээлжийн мэдээ</Title><Text type="secondary">Ирэх, буух ажилтан болон өдөр/шөнийн хуваарь</Text></div><Space wrap><DatePicker value={dayjs(date)} onChange={value=>value&&setDate(value.format('YYYY-MM-DD'))}/><Button icon={<DownloadOutlined/>} onClick={exportRows}>Excel татах</Button></Space></div>{unknown.length>0&&<Alert showIcon type="warning" message={`${unknown.length} ажилтны ээлжийн эхлэх өдөр эсвэл горим дутуу`} description="Хуваарьгүй хүнийг ажилласан гэж тооцохгүй. Ажилтан хэсэгт бүлэг, горим, эхлэх өдөр болон эхний өдөр/шөнийн ээлжийг бөглөнө."/>}<div className="grid grid-cols-2 gap-3 lg:grid-cols-4">{[['Нийт ажилтан',rows.length],['Ажиллах хуваарьтай',active.length],['Өдрийн ээлж',active.filter(row=>row.roster.shift==='day').length],['Шөнийн ээлж',active.filter(row=>row.roster.shift==='night').length]].map(([label,value])=><Card key={label} bordered={false}><Statistic title={label} value={value}/></Card>)}</div><div className="grid grid-cols-2 gap-3 md:grid-cols-3 xl:grid-cols-6">{groups.map(group=><Card key={group} bordered={false} size="small"><Statistic title={`${group} бүлэг`} value={rows.filter(row=>row.shiftGroup===group).length}/></Card>)}</div><Row gutter={[16,16]}>{[['Ирж ажиллах','green'],['Бууж амрах','orange']].map(([kind,color])=><Col xs={24} lg={12} key={kind}><Card bordered={false} title={`${kind}: ${movements.filter(row=>row.movement===kind).length}`} extra={<Tag color={color}>{date}</Tag>}>{movementSummary(kind).length?movementSummary(kind).map(([position,count])=><div className="overview-row" key={position}><span>{position}</span><strong>{count}</strong></div>):<Empty description="Энэ өдөр солилт алга"/>}</Card></Col>)}</Row><Card bordered={false} title="Ажилтны хуваарь" extra={<Input prefix={<SearchOutlined/>} placeholder="Нэр, албан тушаалаар хайх" value={search} onChange={event=>setSearch(event.target.value)} style={{width:250}}/>}><Table rowKey="id" dataSource={filtered} pagination={{pageSize:12}} scroll={{x:850}} columns={[{title:'Ажилтан',render:(_,row)=>`${row.lastName} ${row.firstName}`},{title:'Салбар',dataIndex:'branch'},{title:'Албан тушаал',dataIndex:'position'},{title:'Бүлэг',dataIndex:'shiftGroup',render:value=>value||'—'},{title:'Горим',dataIndex:'rotationPattern',render:value=>value||'—'},{title:'Өдөр/шөнө',render:(_,row)=>row.roster.shift==='night'?'Шөнө':row.roster.shift==='day'?'Өдөр':'—'},{title:'Төлөв',render:(_,row)=><Tag color={row.roster.available?'green':'default'}>{row.roster.label}</Tag>}]}/></Card></div>;
}

function RosterSketch({lists,permissions,user,projectId}) {
  const [start,setStart]=useState(today());
  const [exportEnd,setExportEnd]=useState(()=>dayjs().add(13,'day').format('YYYY-MM-DD'));
  const [selectedPerson,setSelectedPerson]=useState(null);
  const [editing,setEditing]=useState(null);
  const [saving,setSaving]=useState(false);
  const [bulk,setBulk]=useState(null);
  const [bulkSaving,setBulkSaving]=useState(false);
  const [rosterEntries,setRosterEntries]=useState([]);
  const [rosterLoading,setRosterLoading]=useState(false);
  const [exporting,setExporting]=useState(false);
  const [group,setGroup]=useState('all');
  const [search,setSearch]=useState('');
  const dates=Array.from({length:14},(_,index)=>dayjs(start).add(index,'day').format('YYYY-MM-DD'));
  const entryMap=useMemo(()=>new Map(rosterEntries.map(row=>[`${row.employeeId}:${row.date}`,row])),[rosterEntries]);
  const loadRoster=async()=>{const rows=await api(`/roster-entries?startDate=${start}&endDate=${dayjs(start).add(14,'day').format('YYYY-MM-DD')}`);setRosterEntries(rows)};
  useEffect(()=>{let active=true;setRosterLoading(true);api(`/roster-entries?startDate=${start}&endDate=${dayjs(start).add(14,'day').format('YYYY-MM-DD')}`).then(rows=>{if(active)setRosterEntries(rows)}).catch(error=>{if(active)message.error(error.message)}).finally(()=>{if(active)setRosterLoading(false)});return()=>{active=false}},[start,projectId]);
  const people=lists.employees.filter(person=>(group==='all'||(group==='none'?!person.shiftGroup:person.shiftGroup===group))&&`${person.lastName} ${person.firstName} ${person.position}`.toLowerCase().includes(search.toLowerCase()));
  const canCreate=user.role==='admin'||permissions.rosterEntries?.includes('create');
  const canUpdate=user.role==='admin'||permissions.rosterEntries?.includes('update');
  const canDelete=user.role==='admin'||permissions.rosterEntries?.includes('delete');
  const canEdit=canCreate||canUpdate;
  const codeLabels={d:'Өдөр',n:'Шөнө',rr:'Амралт',in:'Ирэх',out:'Буух',adl:'Чөлөө',tr:'Сургалт',si:'Өвчтэй',pl:'Аавын 10 хоног',al:'Ээлжийн амралт'};
  const cell=(person,date,entries=entryMap)=>{
    const state=workState(person,date,lists.attendance,lists.shiftOverrides);
    const entry=entries.get(`${person.id}:${date}`);
    const assignments=lists.assignments.filter(task=>task.date===date&&Number(task.employeeId)===person.id);
    const conflict=assignments.length>1||assignments.length>0&&!state.available;
    const label=entry?.code|| (conflict?'!':state.code==='day'||state.code==='night'?(state.code==='day'?'Ө':'Ш'):state.code==='ready'?(state.shift==='night'?'ш':'ө'):state.code==='travel'?'З':state.code==='leave'?'Ч':state.code==='rest'?'А':state.code==='absent'?'Х':state.code==='extended'?'С':state.code==='replaced'?'—':'·');
    return {label,conflict:!entry&&conflict,state,assignments,entry};
  };
  async function saveCell(){
    if(!editing?.code)return message.warning('Төлөв сонгоно уу');
    if(!editing.endDate||!dayjs(editing.endDate).isAfter(dayjs(editing.date)))return message.warning('Дуусах өдрийг эхлэх өдрөөс хойш сонгоно уу');
    setSaving(true);
    try{
      const body={startDate:editing.date,endDate:editing.endDate,employeeId:editing.person.id,code:editing.code,notes:editing.notes||''};
      const result=await api('/roster-entries/range',{method:'POST',body:JSON.stringify(body)});
      setEditing(null);message.success(`${result.count} өдрийн ростерын төлөв хадгалагдлаа`);await loadRoster();
    }catch(error){message.error(error.message)}finally{setSaving(false)}
  }
  async function clearCell(){
    if(!editing?.entry||!canDelete)return;
    setSaving(true);
    try{await api(`/records/rosterEntries/${editing.entry.id}`,{method:'DELETE'});setEditing(null);message.success('Гараар зассан төлөв ариллаа');await loadRoster()}
    catch(error){message.error(error.message)}finally{setSaving(false)}
  }
  const bulkPreview=(()=>{if(!bulk)return null;try{const days=buildRosterSequence(bulk.startDate,bulk.pattern,bulk.repeat?bulk.repeatCount:1);return {days,endDate:dayjs(days.at(-1).date).add(1,'day').format('YYYY-MM-DD')}}catch(error){return {error:error.message}}})();
  async function saveBulk(){
    if(!bulk?.employeeIds.length)return message.warning('Ажилтан сонгоно уу');
    if(bulkPreview?.error)return message.warning(bulkPreview.error);
    setBulkSaving(true);
    try{
      const result=await api('/roster-entries/sequence',{method:'POST',body:JSON.stringify({employeeIds:bulk.employeeIds,startDate:bulk.startDate,pattern:bulk.pattern,repeatCount:bulk.repeat?bulk.repeatCount:1,notes:bulk.notes})});
      setBulk(null);message.success(`${result.employeeCount} ажилтны ${result.days} өдрийн төлөв хадгалагдлаа`);await loadRoster();
    }catch(error){message.error(error.message)}finally{setBulkSaving(false)}
  }
  const exportRows=async()=>{setExporting(true);try{const exportDates=rosterRangeDates(start,dayjs(exportEnd).add(1,'day').format('YYYY-MM-DD'));const entries=new Map();for(let offset=0;offset<exportDates.length;offset+=31){const chunkStart=exportDates[offset],chunkEnd=dayjs(exportDates[Math.min(offset+30,exportDates.length-1)]).add(1,'day').format('YYYY-MM-DD');const rows=await api(`/roster-entries?startDate=${chunkStart}&endDate=${chunkEnd}`);for(const row of rows)entries.set(`${row.employeeId}:${row.date}`,row)}downloadExcel(['Ажилтан','Албан тушаал','Ээлж',...exportDates],people.map(person=>Object.fromEntries([['Ажилтан',`${person.lastName} ${person.firstName}`],['Албан тушаал',person.position],['Ээлж',person.shiftGroup||''],...exportDates.map(date=>[date,entries.get(`${person.id}:${date}`)?.code||cell(person,date,entries).label])])),`ростер-${start}-${exportEnd}.xlsx`)}catch(error){message.error(error.message)}finally{setExporting(false)}};
  return <div className="page-stack flex flex-col gap-5"><div className="page-title-row"><div><div className="eyebrow">HR · ЭЭЛЖИЙН ТӨЛӨВЛӨЛТ</div><Title level={2}>Ростерын зураглал</Title><Text type="secondary">Ажилтнаар мөрлөсөн 14 хоногийн ээлж, ирц, ажлын оноолтын тойм</Text></div><Space wrap><Text type="secondary">Эхлэх өдөр</Text><DatePicker aria-label="Эхлэх өдөр" placeholder="Эхлэх өдөр" value={dayjs(start)} onChange={date=>{if(date){setStart(date.format('YYYY-MM-DD'));setExportEnd(date.add(13,'day').format('YYYY-MM-DD'))}}}/><Text type="secondary">Excel дуусах өдөр</Text><DatePicker aria-label="Excel дуусах өдөр" placeholder="Excel дуусах өдөр" value={dayjs(exportEnd)} disabledDate={date=>date.isBefore(dayjs(start),'day')||date.isAfter(dayjs(start).add(399,'day'),'day')} onChange={date=>date&&setExportEnd(date.format('YYYY-MM-DD'))}/><Button type="primary" icon={<PlusOutlined/>} disabled={!canEdit||rosterLoading} onClick={()=>setBulk({employeeIds:[],startDate:start,pattern:"in-1, d-3, rr-2, out-1",repeat:false,repeatCount:52,notes:""})}>Олон ажилтны ростер</Button><Button icon={<DownloadOutlined/>} loading={exporting} onClick={exportRows}>Excel татах</Button></Space></div><Alert type="info" showIcon message="Нүд дээр дарж ростерын төлөвийг солино" description="d = өдөр, n = шөнө, rr = амралт, in = ирэх, out = буух, adl = чөлөө, tr = сургалт, si = өвчтэй, pl = аавын 10 хоног, al = ээлжийн амралт. Гараар зассан төлөв бодит ирцийн бүртгэлийг өөрчлөхгүй."/><Card bordered={false}><div className="mb-4 flex flex-wrap gap-2"><Input prefix={<SearchOutlined/>} placeholder="Ажилтан, албан тушаал хайх" value={search} onChange={event=>setSearch(event.target.value)} style={{width:250}}/><Select value={group} onChange={setGroup} style={{width:170}} options={[{value:'all',label:'Бүх ээлж'},...['A','B','C','D','AB','CD'].map(value=>({value,label:`${value} ээлж`})),{value:'none',label:'Ээлж дутуу'}]}/><Tag>{people.length} ажилтан</Tag></div><div className="roster-scroll"><table className="roster-grid"><thead><tr><th>Ажилтан</th><th>Ээлж</th>{dates.map(date=><th key={date}>{dayjs(date).format('MM.DD')}<small>{['Ня','Да','Мя','Лх','Пү','Ба','Бя'][dayjs(date).day()]}</small></th>)}</tr></thead><tbody>{people.map(person=><tr key={person.id}><th onClick={()=>setSelectedPerson(person)} style={{cursor:'pointer'}}><strong>{person.lastName} {person.firstName}</strong><small>{person.position}</small></th><td>{person.shiftGroup||'—'}</td>{dates.map(date=>{const item=cell(person,date);return <td key={date}><button type="button" disabled={rosterLoading||(item.entry?!canUpdate:!canCreate)} onClick={()=>setEditing({person,date,endDate:dayjs(date).add(1,'day').format('YYYY-MM-DD'),entry:item.entry,code:item.entry?.code||'',notes:item.entry?.notes||''})} className={`roster-cell ${item.conflict?'conflict':item.entry?'ready':item.state.code}`} title={`${person.lastName} ${person.firstName} · ${date} · ${item.entry?codeLabels[item.entry.code]:item.state.label}`}>{item.label}</button></td>})}</tr>)}</tbody></table></div>{!people.length&&<Empty description="Шүүлтэд тохирох ажилтан алга"/>}</Card><Modal title={selectedPerson?`${selectedPerson.lastName} ${selectedPerson.firstName} · 14 хоногийн дэлгэрэнгүй`:''} open={!!selectedPerson} onCancel={()=>setSelectedPerson(null)} footer={null} width={720}>{selectedPerson&&<><Descriptions size="small" bordered column={1} items={[{key:'position',label:'Албан тушаал',children:selectedPerson.position||'—'},{key:'group',label:'Ээлжийн бүлэг',children:selectedPerson.shiftGroup||'—'}]}/><div className="mt-4 max-h-80 overflow-y-auto"><Table size="small" rowKey="date" pagination={false} dataSource={dates.map(date=>({date,...cell(selectedPerson,date)}))} columns={[{title:'Өдөр',dataIndex:'date'},{title:'Төлөв',render:(_,row)=>row.entry?codeLabels[row.entry.code]:row.state.label},{title:'Ажил',render:(_,row)=>row.assignments.map(task=>task.title).join(', ')||'—'}]}/></div></>}</Modal><Modal title={editing?`${editing.person.lastName} ${editing.person.firstName} · ${editing.date}`:''} open={!!editing} onCancel={()=>setEditing(null)} onOk={saveCell} okText="Хадгалах" confirmLoading={saving}>{editing&&<div className="grid gap-3"><div><Text type="secondary">Эхлэх өдөр: {editing.date}</Text></div><div><Text>Дуусах өдөр (энэ өдөр орохгүй)</Text><DatePicker className="mt-1 w-full" value={dayjs(editing.endDate)} disabledDate={date=>!date.isAfter(dayjs(editing.date),'day')||date.isAfter(dayjs(editing.date).add(400,'day'),'day')} onChange={date=>date&&setEditing({...editing,endDate:date.format('YYYY-MM-DD')})}/><Text type="secondary">{dayjs(editing.endDate).diff(dayjs(editing.date),'day')} өдрийн төлөв хадгална</Text></div><Select className="w-full" placeholder="Төлөв сонгох" value={editing.code||undefined} options={rosterCodes.map(code=>({value:code,label:`${code} · ${codeLabels[code]}`}))} onChange={code=>setEditing({...editing,code})}/><Input.TextArea placeholder="Тайлбар" value={editing.notes} onChange={event=>setEditing({...editing,notes:event.target.value})}/>{editing.entry&&canDelete&&<Button danger onClick={clearCell} loading={saving}>Гараар зассан төлөв арилгах</Button>}</div>}</Modal><Modal title="Олон ажилтны ростер" open={!!bulk} onCancel={()=>setBulk(null)} onOk={saveBulk} okText="Хадгалах" confirmLoading={bulkSaving} okButtonProps={{disabled:!bulk?.employeeIds.length||!!bulkPreview?.error}} width={650}>
 {bulk&&<div className="grid gap-4">
  <div><Text>Ажилтнууд</Text><Select className="mt-1 w-full" mode="multiple" showSearch optionFilterProp="label" maxTagCount="responsive" placeholder="Нэрээр хайж хэдэн ч ажилтан сонгох" value={bulk.employeeIds} options={lists.employees.map(person=>({value:person.id,label:`${person.lastName} ${person.firstName} · ${person.position||'—'}`}))} onChange={employeeIds=>setBulk({...bulk,employeeIds})}/></div>
  <div><Text>Эхлэх өдөр</Text><DatePicker className="mt-1 w-full" value={dayjs(bulk.startDate)} onChange={date=>date&&setBulk({...bulk,startDate:date.format('YYYY-MM-DD')})}/></div>
  <div><Text>Төлөвийн дараалал</Text><Input className="mt-1" value={bulk.pattern} placeholder="in-1, d-3, rr-2, out-1" onChange={event=>setBulk({...bulk,pattern:event.target.value})}/><Text type="secondary">Код-тоо хэлбэрээр таслалаар тусгаарлана. d=өдөр, n=шөнө, rr=амралт, in=ирэх, out=буух, adl=чөлөө, tr=сургалт, si=өвчтэй.</Text></div>
  <div className="flex flex-wrap items-center gap-3"><Checkbox checked={bulk.repeat} onChange={event=>setBulk({...bulk,repeat:event.target.checked})}>Давтах</Checkbox>{bulk.repeat&&<><Text>Нийт хэдэн удаа</Text><InputNumber min={1} max={400} value={bulk.repeatCount} onChange={repeatCount=>setBulk({...bulk,repeatCount})}/></>}</div>
  <Input.TextArea placeholder="Тайлбар" value={bulk.notes} onChange={event=>setBulk({...bulk,notes:event.target.value})}/>
  {bulkPreview?.error?<Alert type="error" showIcon message={bulkPreview.error}/>:<Alert type="info" showIcon message={`${bulk.employeeIds.length} ажилтан · ${bulkPreview.days.length} өдөр · ${bulk.startDate}–${dayjs(bulkPreview.days.at(-1).date).format('YYYY-MM-DD')}`} description={`Дуусах өдөр сонгох шаардлагагүй. Дарааллыг ${bulk.repeat?bulk.repeatCount:1} удаа хэрэглэнэ. Сонгосон өдрүүдийн өмнөх төлөвийг шинэчилнэ.`}/>}
 </div>}
</Modal></div>;
}

function WeeklyReadiness({lists,refresh,permissions,user}) {
  const monday=value=>dayjs(value).subtract((dayjs(value).day()+6)%7,'day').format('YYYY-MM-DD');
  const [week,setWeek]=useState(monday(today()));
  const [search,setSearch]=useState('');
  const [editing,setEditing]=useState(null);
  const [saving,setSaving]=useState(false);
  const [operators,setOperators]=useState([]);
  useEffect(()=>{api('/readiness-operators').then(setOperators).catch(error=>message.error(error.message))},[]);
  const canEdit=user.role==='admin'||permissions.technicalReadiness?.includes('create')||permissions.technicalReadiness?.includes('update');
  const rows=lists.equipment.filter(machine=>`${machine.parkNo} ${machine.model} ${machine.kind}`.toLowerCase().includes(search.toLowerCase())).map(machine=>({...machine,weekly:lists.technicalReadiness?.find(row=>row.weekStart===week&&Number(row.equipmentId)===machine.id)}));
  const operator=id=>operators.find(row=>row.id===Number(id));
  const employeeName=id=>{const person=operator(id);return person?`${person.lastName} ${person.firstName}`:'—'};
  const begin=machine=>{const row=machine.weekly;setEditing({id:row?.id,equipmentId:machine.id,weekStart:week,dayStatus:row?.dayStatus||'Ажилд бэлэн',nightStatus:row?.nightStatus||'Ажилд бэлэн',dayOperatorId:row?.dayOperatorId||undefined,nightOperatorId:row?.nightOperatorId||undefined,notes:row?.notes||''})};
  async function save(){
    setSaving(true);
    try{const {id,...body}=editing;await api(`/records/technicalReadiness${id?`/${id}`:''}`,{method:id?'PUT':'POST',body:JSON.stringify(body)});await refresh();setEditing(null);message.success('7 хоногийн төлөв хадгалагдлаа')}
    catch(error){message.error(error.message)}finally{setSaving(false)}
  }
  const exportRows=()=>downloadExcel(['Модель','Парк дугаар','Өдрийн төлөв','Өдрийн оператор','Өдрийн утас','Өдрийн ID','Өдрийн салбар / компани','Шөнийн төлөв','Шөнийн оператор','Шөнийн утас','Шөнийн ID','Шөнийн салбар / компани','Тайлбар'],rows.map(row=>({'Модель':row.model||row.kind,'Парк дугаар':row.parkNo,'Өдрийн төлөв':row.weekly?.dayStatus||'','Өдрийн оператор':employeeName(row.weekly?.dayOperatorId),'Өдрийн утас':operator(row.weekly?.dayOperatorId)?.phone||'','Өдрийн ID':operator(row.weekly?.dayOperatorId)?.code||'','Өдрийн салбар / компани':operator(row.weekly?.dayOperatorId)?.branch||'','Шөнийн төлөв':row.weekly?.nightStatus||'','Шөнийн оператор':employeeName(row.weekly?.nightOperatorId),'Шөнийн утас':operator(row.weekly?.nightOperatorId)?.phone||'','Шөнийн ID':operator(row.weekly?.nightOperatorId)?.code||'','Шөнийн салбар / компани':operator(row.weekly?.nightOperatorId)?.branch||'','Тайлбар':row.weekly?.notes||''})),`техникийн-7-хоног-${week}.xlsx`);
  return <div className="page-stack flex flex-col gap-5"><div className="page-title-row flex flex-wrap items-end justify-between gap-3"><div><div className="eyebrow">ҮЙЛ АЖИЛЛАГАА · ТЕХНИК</div><Title level={2}>7 хоногийн техникийн тойм</Title><Text type="secondary">{week} – {dayjs(week).add(6,'day').format('YYYY-MM-DD')} · өдөр, шөнийн бэлэн байдал ба оператор</Text></div><Space wrap><DatePicker value={dayjs(week)} onChange={date=>date&&setWeek(monday(date))}/><Button icon={<DownloadOutlined/>} onClick={exportRows}>Excel татах</Button></Space></div><Card bordered={false}><Input prefix={<SearchOutlined/>} placeholder="Парк дугаар, модель хайх" value={search} onChange={event=>setSearch(event.target.value)} style={{maxWidth:320,marginBottom:16}}/><Table rowKey="id" dataSource={rows} scroll={{x:1600}} pagination={{pageSize:20}} onRow={machine=>({onClick:()=>canEdit&&begin(machine),style:{cursor:canEdit?'pointer':'default'}})} columns={[{title:'Модель',dataIndex:'model',render:(value,row)=>value||row.kind},{title:'Парк дугаар',dataIndex:'parkNo'},{title:'Өдрийн төлөв',render:(_,row)=>row.weekly?.dayStatus||'—'},{title:'Өдрийн оператор',render:(_,row)=>employeeName(row.weekly?.dayOperatorId)},{title:'Утас',render:(_,row)=>operator(row.weekly?.dayOperatorId)?.phone||'—'},{title:'ID',render:(_,row)=>operator(row.weekly?.dayOperatorId)?.code||'—'},{title:'Салбар / компани',render:(_,row)=>operator(row.weekly?.dayOperatorId)?.branch||'—'},{title:'Шөнийн төлөв',render:(_,row)=>row.weekly?.nightStatus||'—'},{title:'Шөнийн оператор',render:(_,row)=>employeeName(row.weekly?.nightOperatorId)},{title:'Утас',render:(_,row)=>operator(row.weekly?.nightOperatorId)?.phone||'—'},{title:'ID',render:(_,row)=>operator(row.weekly?.nightOperatorId)?.code||'—'},{title:'Салбар / компани',render:(_,row)=>operator(row.weekly?.nightOperatorId)?.branch||'—'},{title:'Тайлбар',render:(_,row)=>row.weekly?.notes||'—',width:240}]}/></Card><Modal title={editing?`${lists.equipment.find(row=>row.id===editing.equipmentId)?.parkNo} · ${week}`:''} open={!!editing} onCancel={()=>setEditing(null)} onOk={save} okText="Хадгалах" confirmLoading={saving}>{editing&&<div className="grid gap-4"><div><div className="mb-1">Өдрийн төлөв</div><Select className="w-full" value={editing.dayStatus} options={readinessStatuses.map(value=>({value,label:value}))} onChange={dayStatus=>setEditing({...editing,dayStatus})}/></div><div><div className="mb-1">Өдрийн оператор</div><Select className="w-full" showSearch allowClear optionFilterProp="label" value={editing.dayOperatorId} options={operators.map(person=>({value:person.id,label:`${person.lastName} ${person.firstName}`}))} onChange={dayOperatorId=>setEditing({...editing,dayOperatorId})}/></div><div><div className="mb-1">Шөнийн төлөв</div><Select className="w-full" value={editing.nightStatus} options={readinessStatuses.map(value=>({value,label:value}))} onChange={nightStatus=>setEditing({...editing,nightStatus})}/></div><div><div className="mb-1">Шөнийн оператор</div><Select className="w-full" showSearch allowClear optionFilterProp="label" value={editing.nightOperatorId} options={operators.map(person=>({value:person.id,label:`${person.lastName} ${person.firstName}`}))} onChange={nightOperatorId=>setEditing({...editing,nightOperatorId})}/></div><Input.TextArea placeholder="Тайлбар" value={editing.notes} onChange={event=>setEditing({...editing,notes:event.target.value})}/></div>}</Modal></div>;
}

const mpcViewPages={mpcItems:'items',mpcBalance:'balance',mpcOrders:'orders',mpcPurchases:'purchases',mpcIncome:'income',mpcIssues:'issues',mpcTransfers:'transfers'};
function MpcReadPage({view}) {
  const [data,setData]=useState(null);
  const [error,setError]=useState('');
  const [loading,setLoading]=useState(true);
  const [warehouse,setWarehouse]=useState('all');
  const [details,setDetails]=useState({});
  useEffect(()=>{let active=true;setLoading(true);setError('');setData(null);api(`/mpc-read/${view}`).then(result=>{if(active)setData(result)}).catch(reason=>{if(active)setError(reason.message)}).finally(()=>{if(active)setLoading(false)});return()=>{active=false}},[view]);
  const warehouseName=row=>String(row.warehouse?.name||row.warehouseName||row.warehouse||row.storeName||row.store?.name||row.warehouseId||'Агуулах тодорхойгүй');
  const warehouses=[...new Set((data?.rows||[]).map(warehouseName))].sort((a,b)=>a.localeCompare(b,'mn'));
  const rows=warehouse==='all'?data?.rows||[]:(data?.rows||[]).filter(row=>warehouseName(row)===warehouse);
  const showValue=value=>value===null||value===undefined||value===''?'—':typeof value==='object'?Array.isArray(value)?value.map((item,index)=><div key={index} className="mb-2 rounded border border-slate-200 p-2">{typeof item==='object'?<Descriptions size="small" column={1} items={Object.entries(item).map(([key,entry])=>({key,label:key,children:showValue(entry)}))}/>:String(item)}</div>):<Descriptions size="small" column={1} items={Object.entries(value).map(([key,entry])=>({key,label:key,children:showValue(entry)}))}/>:typeof value==='string'&&/^\d{4}-\d{2}-\d{2}T/.test(value)?dayjs(value).format('YYYY-MM-DD HH:mm'):String(value);
  async function loadDetail(row){const key=String(row.mirrorKey??row.id??row.itemId??row.docNo);if(details[key]||!row.id||view==='balance'||row.mirrorKey?.startsWith('in-'))return;setDetails(current=>({...current,[key]:{loading:true}}));try{const detail=await api(`/mpc-read/${view}/${encodeURIComponent(row.id)}`);setDetails(current=>({...current,[key]:{data:detail}}))}catch(reason){setDetails(current=>({...current,[key]:{error:reason.message}}))}}
  const columns=(data?.columns||[]).map(([key,label])=>({title:label,dataIndex:key,key,render:value=>value===null||value===undefined||value===''?'—':typeof value==='number'?money(value):typeof value==='object'?showValue(value):typeof value==='string'&&/^\d{4}-\d{2}-\d{2}T/.test(value)?dayjs(value).format('YYYY-MM-DD'):String(value)}));
  const download=()=>downloadExcel(data.columns.map(([,label])=>label),rows.map(row=>Object.fromEntries(data.columns.map(([key,label])=>[label,row[key]??'']))),`${view}-${dayjs().format('YYYY-MM-DD')}.xlsx`);
  return <div className="page-stack flex flex-col gap-5"><div className="page-title-row flex flex-wrap items-end justify-between gap-3"><div><div className="eyebrow">MPC · БАРАА МАТЕРИАЛ</div><Title level={2}>{data?.title||'MPC мэдээлэл'}</Title><Text type="secondary">{data?`${rows.length} / ${data.total} мөр · ${dayjs(data.fetchedAt).format('YYYY-MM-DD HH:mm')} шинэчилсэн`:''}</Text></div>{data&&<Button icon={<DownloadOutlined/>} onClick={download}>Excel татах</Button>}</div>{error&&<Alert type="error" showIcon message={error}/>}<Card bordered={false} loading={loading}>{data&&<><div className="mb-4 flex flex-wrap items-center gap-3"><Text strong>Агуулах:</Text><Select value={warehouse} onChange={setWarehouse} style={{minWidth:220}} options={[{value:'all',label:`Бүх агуулах (${data.rows.length})`},...warehouses.map(name=>({value:name,label:`${name} (${data.rows.filter(row=>warehouseName(row)===name).length})`}))]}/></div><Table rowKey={row=>row.mirrorKey??row.id??row.itemId??row.docNo} dataSource={rows} columns={columns} scroll={{x:'max-content'}} pagination={{pageSize:30}} expandable={{onExpand:(expanded,row)=>expanded&&loadDetail(row),expandedRowRender:row=>{const key=String(row.mirrorKey??row.id??row.itemId??row.docNo),detail=details[key];const value=detail?.data||row;return <div className="max-h-[60vh] overflow-auto">{detail?.loading&&<Text type="secondary">Дэлгэрэнгүй мэдээлэл татаж байна...</Text>}{detail?.error&&<Alert type="warning" showIcon message={detail.error}/>}<Descriptions size="small" bordered column={{xs:1,sm:2}} items={Object.entries(value).filter(([name])=>name!=='mirrorKey').map(([name,entry])=>({key:name,label:data.columns.find(([column])=>column===name)?.[1]||name,children:showValue(entry)}))}/></div>}}}/></>}</Card></div>;
}

function MpcIntegrationSettings({projectId}) {
  const [configured,setConfigured]=useState(false);
  const [loading,setLoading]=useState(true);
  const [saving,setSaving]=useState(false);
  const [form]=Form.useForm();
  useEffect(()=>{setLoading(true);api('/mpc-integration').then(result=>setConfigured(result.configured)).catch(error=>message.error(error.message)).finally(()=>setLoading(false))},[projectId]);
  async function save(values){setSaving(true);try{await api('/mpc-integration',{method:'PUT',body:JSON.stringify(values)});setConfigured(true);form.resetFields();message.success('MPC API холболт хадгалагдлаа')}catch(error){message.error(error.message)}finally{setSaving(false)}}
  return <div className="page-stack flex flex-col gap-5"><div className="page-title-row"><div><div className="eyebrow">ТОХИРГОО</div><Title level={2}>MPC API холболт</Title><Text type="secondary">MPC-ийн унших хуудсуудыг нээх үед серверээс шууд мэдээлэл авна.</Text></div></div><Card bordered={false} loading={loading}><Alert type={configured?'success':'warning'} showIcon message={configured?'Холболтын эрх бүртгэлтэй':'Холболтын эрх бүртгэгдээгүй'} className="mb-5"/><Form form={form} layout="vertical" onFinish={save} style={{maxWidth:420}}><Form.Item name="username" label="MPC нэвтрэх нэр" rules={[{required:true}]}><Input autoComplete="off"/></Form.Item><Form.Item name="password" label="MPC нууц үг" rules={[{required:true}]}><Input.Password autoComplete="new-password"/></Form.Item><Button type="primary" htmlType="submit" loading={saving}>Холболт хадгалах</Button></Form></Card></div>;
}

function ProjectsPage({projects,projectId,refresh,onSelect}) {
  const [editing,setEditing]=useState(null);
  const [name,setName]=useState('');
  const [saving,setSaving]=useState(false);
  const save=async()=>{setSaving(true);try{await api(`/projects${editing?.id?`/${editing.id}`:''}`,{method:editing?.id?'PUT':'POST',body:JSON.stringify({name})});setEditing(null);setName('');await refresh();message.success('Төсөл хадгалагдлаа')}catch(error){message.error(error.message)}finally{setSaving(false)}};
  const remove=async row=>{try{await api(`/projects/${row.id}`,{method:'DELETE'});await refresh();message.success('Төсөл устлаа')}catch(error){message.error(error.message)}};
  return <div className="page-stack flex flex-col gap-5"><div className="page-title-row flex flex-wrap items-end justify-between gap-3"><div><div className="eyebrow">ТОХИРГОО · MPC</div><Title level={2}>Төслийн нэрс</Title><Text type="secondary">Нэрийг MPC дээрх төслийн нэртэй яг ижил бичнэ. Төсөл бүрийн MPC API эрхийг тусад нь тохируулна.</Text></div><Button type="primary" icon={<PlusOutlined/>} onClick={()=>{setEditing({});setName('')}}>Төсөл нэмэх</Button></div><Card bordered={false}><Table rowKey="id" dataSource={projects} pagination={false} columns={[{title:'Төслийн нэр',dataIndex:'name'},{title:'MPC API',render:(_,row)=>row.id===projectId?'Сонгосон төсөл':'Төслийг сонгоод тохируулна'},{title:'Үйлдэл',render:(_,row)=><Space><Button size="small" onClick={()=>onSelect(row.id)}>Сонгох</Button><Button size="small" icon={<EditOutlined/>} onClick={()=>{setEditing(row);setName(row.name)}}>Засах</Button><Popconfirm title="Хоосон төслийг устгах уу?" onConfirm={()=>remove(row)}><Button size="small" danger icon={<DeleteOutlined/>} disabled={Number(row.id)===Number(projectId)}>Устгах</Button></Popconfirm></Space>}]}/></Card><Modal title={editing?.id?'Төслийн нэр засах':'Төсөл нэмэх'} open={!!editing} onCancel={()=>setEditing(null)} onOk={save} okText="Хадгалах" confirmLoading={saving} okButtonProps={{disabled:name.trim().length<2}}><Input value={name} onChange={event=>setName(event.target.value)} placeholder="MPC дээрх яг ижил нэр" maxLength={100}/></Modal></div>;
}

function WarehouseOverview({lists}) {
  return <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{lists.warehouses.map(warehouse=>{
    const equipment=lists.equipment.filter(item=>Number(item.warehouseId)===warehouse.id&&item.availability==='available'&&item.status==='ready');
    const kinds=Object.entries(equipment.reduce((counts,item)=>({...counts,[item.kind]:(counts[item.kind]||0)+1}),{})).sort((a,b)=>b[1]-a[1]);
    const plans=lists.plans.filter(plan=>Number(plan.warehouseId)===warehouse.id);
    const missing=plans.reduce((sum,plan)=>sum+equipmentAvailability(plan,lists).missing,0);
    return <div key={warehouse.id} className="rounded-xl bg-white px-5 py-4 shadow-sm"><div className="flex items-center justify-between gap-3"><div><strong className="text-sm text-slate-800">{warehouse.name}</strong><div className="mt-1 text-xs text-slate-400">{warehouse.location || 'Байршил тодорхойгүй'}</div></div><Tag color={missing?'orange':'green'}>{missing?`${missing} техник дутуу`:'Хүрэлцээтэй'}</Tag></div><div className="mt-4 border-t border-slate-100 pt-3 text-xs text-slate-600">Бэлэн техник <b className="float-right text-slate-800">{equipment.length}</b></div><div className="mt-2 space-y-1 text-xs text-slate-500">{kinds.map(([kind,count])=><div key={kind} className="flex justify-between gap-2"><span>{kind}</span><strong>{count}</strong></div>)}</div></div>
  })}</div>;
}

function CampRoster({lists,date}) {
  const [campId,setCampId]=useState(lists.camps[0]?.id);
  useEffect(()=>{if(!lists.camps.some(c=>c.id===campId)) setCampId(lists.camps[0]?.id)},[lists.camps,campId]);
  const camp=lists.camps.find(c=>c.id===campId);
  const staff=lists.employees.filter(e=>Number(e.campId)===Number(campId));
  const working=staff.filter(e=>workState(e,date,lists.attendance,lists.shiftOverrides).available).length;
  return <Card bordered={false} title="Camp-ийн ээлжийн бүрэлдэхүүн" extra={<Select value={campId} onChange={setCampId} options={lists.camps.map(c=>({value:c.id,label:c.name}))} style={{minWidth:180}} placeholder="Camp сонгох"/>}><div className="mb-4 flex flex-wrap gap-3 text-xs"><Tag color="green">Ажиллаж буй {working}</Tag><Tag>Амралттай {staff.filter(e=>workState(e,date,lists.attendance,lists.shiftOverrides).code==='rest').length}</Tag><Tag color="gold">Чөлөөтэй {staff.filter(e=>e.status==='leave').length}</Tag><span className="text-slate-500">{camp?.workType || ''}</span></div><Table rowKey="id" size="small" dataSource={staff} pagination={{pageSize:6}} columns={[{title:'Ажилтан',render:(_,e)=>`${e.lastName} ${e.firstName}`},{title:'Албан тушаал',dataIndex:'position'},{title:'Ээлж',dataIndex:'shiftGroup'},{title:'Төлөв',render:(_,e)=>{const state=workState(e,date,lists.attendance,lists.shiftOverrides);return <Tag color={statusColors[state.code]}>{state.label}</Tag>}},{title:'Дараагийн солилт',render:(_,e)=>{const state=workState(e,date,lists.attendance,lists.shiftOverrides);return state.daysLeft?`${state.daysLeft} өдөр`:'—'}}]}/></Card>;
}

function CampMealsSummary({lists,date}) {
  const rows=lists.campStays.filter(row=>row.date===date);
  const categories=[['employee','Үндсэн ажилтан'],['guest','Зочин'],['rental','Түрээсийн ажилтан']];
  const totals=categories.map(([category,label])=>{const subset=rows.filter(row=>row.category===category);return {category,label,people:subset.reduce((sum,row)=>sum+num(row.count),0),meals:subset.reduce((sum,row)=>sum+num(row.breakfast)+num(row.lunch)+num(row.dinner),0),food:subset.reduce((sum,row)=>sum+(num(row.breakfast)+num(row.lunch)+num(row.dinner))*num(row.mealRate),0),lodging:subset.reduce((sum,row)=>sum+num(row.count)*num(row.lodgingRate),0)}});
  const missingRates=rows.filter(row=>(num(row.breakfast)+num(row.lunch)+num(row.dinner))>0&&!num(row.mealRate));
  const exportRows=()=>downloadExcel(['Ангилал','Хүний тоо','Хоолны тоо','Хоолны зардал ₮','Хоногийн зардал ₮','Нийт ₮'],totals.map(row=>({'Ангилал':row.label,'Хүний тоо':row.people,'Хоолны тоо':row.meals,'Хоолны зардал ₮':row.food,'Хоногийн зардал ₮':row.lodging,'Нийт ₮':row.food+row.lodging})),`camp-хоол-${date}.xlsx`);
  return <Card bordered={false} title={`${date} · Хоног, хоолны тооцоо`} extra={<Button size="small" icon={<DownloadOutlined/>} onClick={exportRows}>Excel татах</Button>}><Alert type="info" showIcon className="mb-4" message="Тооцооллын зарчим" description="Хоолны тоо × нэгж үнэ; хоноглосон хүний тоо × хоногийн үнэ. Түрээсийн ажилтны хоолыг тусад нь харуулна."/>{missingRates.length>0&&<Alert type="warning" showIcon className="mb-4" message={`${missingRates.length} мөрөнд хоолны үнэ дутуу байна`}/>}<div className="grid gap-3 sm:grid-cols-3">{totals.map(row=><div key={row.category} className="rounded-xl border border-slate-100 bg-slate-50 p-4"><strong className="block text-sm text-slate-800">{row.label}</strong><span className="mt-2 block text-xs text-slate-500">{row.people} хүн · {row.meals} хоол</span><strong className="mt-3 block text-lg text-violet-700">{money(row.food+row.lodging)} ₮</strong><span className="text-xs text-slate-500">Хоол {money(row.food)} ₮ · Хоног {money(row.lodging)} ₮</span></div>)}</div></Card>;
}

function Readiness({lists,date}) {
  const fuel=lists.fuel.reduce((n,f)=>n+(f.kind==='receipt'?num(f.liters):-num(f.liters)),0);
  return <div className="readiness-grid">{lists.plans.map(p=>{const equipment=equipmentAvailability(p,lists);const warehouse=lists.warehouses.find(w=>w.id===Number(p.warehouseId));const pool=Array.isArray(p.employeeIds)&&p.employeeIds.length?lists.employees.filter(e=>p.employeeIds.some(id=>Number(id)===e.id)):lists.employees;const active=pool.filter(e=>workState(e,date,lists.attendance,lists.shiftOverrides).available).length;const workerGap=Math.max(0,num(p.requiredWorkers)-active);const fuelGap=Math.max(0,num(p.plannedFuel)-fuel);return <Card key={p.id} bordered={false} className="readiness-card"><div className="readiness-top"><strong>{p.name}</strong><Tag color={workerGap||equipment.missing||fuelGap?'orange':'green'}>{workerGap||equipment.missing||fuelGap?'Нөөц дутуу':'Бэлэн'}</Tag></div>{warehouse&&<div className="text-[11px] text-violet-700 mb-2">Агуулах: {warehouse.name}</div>}<div className="readiness-row"><span>Хүн хүч</span><b>{active} / {num(p.requiredWorkers)}</b><small>{workerGap?`${workerGap} дутуу`:'Хүрэлцээтэй'}</small></div><div className="readiness-row"><span>Техник</span><b>{equipment.count} / {num(p.requiredEquipment)}</b><small>{equipment.missing?`${equipment.missing} дутуу`:'Хүрэлцээтэй'}</small></div>{equipment.byKind.map(item=><div className="readiness-row" key={item.kind}><span>{item.kind}</span><b>{item.available} / {item.count}</b><small>{item.available<item.count?`${item.count-item.available} дутуу`:'Хүрэлцээтэй'}</small></div>)}<div className="readiness-row"><span>Түлш</span><b>{money(fuel)} / {money(p.plannedFuel)} л</b><small>{fuelGap?`${money(fuelGap)} л дутуу`:'Хүрэлцээтэй'}</small></div></Card>})}</div>
}

function TimesheetPage({lists,date,refresh,user,permissions={}}) {
  const [month,setMonth]=useState(dayjs(date).format('YYYY-MM'));
  const [search,setSearch]=useState('');
  const [selectedId,setSelectedId]=useState(null);
  const [entryDate,setEntryDate]=useState(date);
  const [entryStatus,setEntryStatus]=useState('day');
  const [hours,setHours]=useState(12);
  const [saving,setSaving]=useState(false);
  const dates=monthDates(month);
  const canEdit=user.role==='admin'||permissions.attendance?.includes('create');
  const employees=lists.employees.filter(employee=>`${employee.code||''} ${employee.lastName} ${employee.firstName} ${employee.branch||''} ${employee.position||''}`.toLowerCase().includes(search.toLowerCase()));
  const records=new Map(lists.attendance.filter(item=>dates.includes(item.date)).map(item=>[`${item.employeeId}:${item.date}`,item]));
  const selected=lists.employees.find(employee=>employee.id===selectedId);
  const daily=selected?Object.fromEntries(dates.map(day=>[day,records.get(`${selected.id}:${day}`)])):{};
  const summary=attendanceSummary(daily,dates);
  const activeRecord=selected?records.get(`${selected.id}:${entryDate}`):null;
  useEffect(()=>{if(!activeRecord)return;setEntryStatus(activeRecord.status);setHours(Number(activeRecord.actualHours||0))},[selectedId,entryDate,activeRecord?.id,activeRecord?.updated_at]);
  async function save() {
    if(!selected)return message.warning('Ажилтан сонгоно уу');
    if(!entryDate.startsWith(month))return message.warning('Сонгосон сарын өдөр оруулна уу');
    setSaving(true);
    try {
      await api('/attendance/submit',{method:'POST',body:JSON.stringify({rows:[{date:entryDate,employeeId:selected.id,status:entryStatus,plannedHours:['day','night'].includes(entryStatus)?12:0,actualHours:['day','night'].includes(entryStatus)?Number(hours||0):0,notes:activeRecord?.notes||''}]})});
      await refresh();message.success(`${selected.lastName} ${selected.firstName} · ${entryDate} ирцийг амжилттай хадгаллаа`);
    } catch(error){message.error(error.message)} finally {setSaving(false)}
  }
  const columns=[{title:'Ажилтан',key:'employee',fixed:'left',width:190,render:(_,employee)=><Button type="link" onClick={()=>setSelectedId(employee.id)} className="!h-auto !p-0 !text-left"><span className="block font-semibold">{employee.lastName} {employee.firstName}</span><span className="block text-xs text-slate-500">{employee.code||'Кодгүй'} · {employee.position||''}</span></Button>},...dates.map(day=>({title:day.slice(-2),key:day,width:48,align:'center',render:(_,employee)=>{const status=records.get(`${employee.id}:${day}`)?.status;return <Button size="small" type="text" title={`${day} · ${statusLabels[status]||'Бүртгэлгүй'}`} onClick={()=>{setSelectedId(employee.id);setEntryDate(day)}} className="!min-w-8 !px-1">{status?<Tag color={statusColors[status]} className="!m-0">{attendanceCode[status]||'?'}</Tag>:<span className="text-slate-400">·</span>}</Button>}})),{title:'Өдөр',key:'day',width:65,render:(_,employee)=>dates.filter(day=>records.get(`${employee.id}:${day}`)?.status==='day').length},{title:'Шөнө',key:'night',width:65,render:(_,employee)=>dates.filter(day=>records.get(`${employee.id}:${day}`)?.status==='night').length}];
  const summaryTags=[['Өдөр',summary.day,'blue'],['Шөнө',summary.night,'purple'],['Ирсэн',summary.arrival,'green'],['Буусан',summary.departure,'orange'],['Ажилласан цаг',summary.workedHours,'geekblue']];
  return <div className="page-stack flex flex-col gap-5"><div className="page-title-row flex flex-wrap items-end justify-between gap-3"><div><div className="eyebrow">HR · ЦАГИЙН БҮРТГЭЛ</div><Title level={2}>Сарын цагийн мэдээ</Title><Text type="secondary">Ажилтнаа сонгоод өдөр бүрийн ирцийг бүртгэнэ. Доор нь задаргаа харагдана.</Text></div><Space wrap><DatePicker picker="month" value={dayjs(`${month}-01`)} onChange={value=>{if(value){setMonth(value.format('YYYY-MM'));setEntryDate(value.startOf('month').format('YYYY-MM-DD'))}}}/><Button icon={<DownloadOutlined/>} onClick={()=>exportBook1Timesheet({month,employees,attendance:lists.attendance,includeSalary:['admin','hr'].includes(user.role)}).then(path=>{if(path)message.success(`Excel хадгаллаа: ${path}`)}).catch(error=>message.error(error.message))}>Excel татах</Button></Space></div><Alert showIcon type="info" message="Ир = ирсэн, Өд = өдөр ажилласан, Бу = буусан, Шө = шөнө ажилласан" description="Өдөр болон шөнийн ажлын бодит цагийг тусад нь оруулна. Ирсэн/буусан өдөр нь замын өдөрт тооцогдоно. Хоосон нүд бүртгэлгүй гэсэн үг."/><Card bordered={false}><Input prefix={<SearchOutlined/>} value={search} onChange={event=>setSearch(event.target.value)} placeholder="Код, нэр, албан тушаалаар хайх" style={{maxWidth:340,marginBottom:16}}/><Table rowKey="id" dataSource={employees} columns={columns} size="small" scroll={{x:'max-content'}} pagination={{pageSize:15,showSizeChanger:false}}/></Card><Card bordered={false} title={selected?`${selected.lastName} ${selected.firstName} · ${selected.code||selected.register||selected.id}`:'Ажилтнаа сонгоно уу'}>{!selected?<Empty description="Дээрх хүснэгтээс ажилтны нэр эсвэл өдрийг дарна уу"/>:<><div className="grid gap-4 md:grid-cols-2 xl:grid-cols-4"><div><div className="mb-2 font-medium">1. Өдөр</div><DatePicker className="w-full" value={dayjs(entryDate)} onChange={value=>value&&setEntryDate(value.format('YYYY-MM-DD'))} disabledDate={value=>value.format('YYYY-MM')!==month}/></div><div><div className="mb-2 font-medium">2. Ирцийн төлөв</div><Select className="w-full" value={entryStatus} onChange={value=>{setEntryStatus(value);setHours(['day','night'].includes(value)?12:0)}} options={['arrival','day','night','departure','rest','leave','absent','travel'].map(value=>({value,label:`${attendanceCode[value]} · ${statusLabels[value]}`}))}/></div><div><div className="mb-2 font-medium">3. Ажилласан цаг</div><InputNumber className="w-full" min={0} max={24} value={hours} onChange={value=>setHours(value||0)} disabled={!['day','night'].includes(entryStatus)}/></div><div className="flex items-end"><Button type="primary" block size="large" loading={saving} disabled={!canEdit} onClick={save}>{activeRecord?'Ирц шинэчлэх':'Ирц хадгалах'}</Button></div></div>{!canEdit&&<Alert className="mt-4" showIcon type="warning" message="Ирц бүртгэх эрхгүй байна"/>}<div className="mt-6 border-t border-slate-100 pt-5"><div className="mb-3 font-semibold">Сарын задаргаа</div><Space wrap>{summaryTags.map(([label,value,color])=><Tag key={label} color={color}>{label}: {value}</Tag>)}</Space><div className="mt-4 grid grid-cols-7 gap-2 sm:grid-cols-10 lg:grid-cols-15">{dates.map(day=><button key={day} type="button" onClick={()=>setEntryDate(day)} className={`rounded-lg border p-2 text-center ${entryDate===day?'border-violet-500 bg-violet-50':'border-slate-200'}`}><span className="block text-xs text-slate-500">{day.slice(-2)}</span><strong>{attendanceCode[daily[day]?.status]||'·'}</strong></button>)}</div></div></>}</Card></div>;
}
function PayrollPage({lists,date,refresh,permissions,user}) {
  const [month,setMonth]=useState(dayjs(date).format('YYYY-MM'));
  const [half,setHalf]=useState('first');
  const [branch,setBranch]=useState('all');
  const [position,setPosition]=useState('all');
  const [shift,setShift]=useState('all');
  const [state,setState]=useState('all');
  const [search,setSearch]=useState('');
  const [editing,setEditing]=useState(null);
  const [detail,setDetail]=useState(null);
  const [saving,setSaving]=useState(false);
  const [payrollImport,setPayrollImport]=useState(null);
  const [importShare,setImportShare]=useState(true);
  const [form]=Form.useForm();
  const canEdit=user.role==='admin'||permissions.payrollEntries?.includes('create')||permissions.payrollEntries?.includes('update');
  const rows=useMemo(()=>payrollRows(lists.employees,lists.attendance,lists.payrollEntries,month,half),[lists,month,half]);
  const shown=rows.filter(row=>{
    const employee=row.employee;
    return (branch==='all'||employee.branch===branch)&&(position==='all'||employee.position===position)&&(shift==='all'||employee.shiftGroup===shift)&&(state==='all'||(state==='ready'?!row.errors.length&&!row.skipped:state==='skipped'?!!row.skipped:!!row.errors.length))&&`${employee.lastName} ${employee.firstName} ${employee.register} ${employee.position}`.toLowerCase().includes(search.toLowerCase());
  });
  const ready=shown.filter(row=>!row.errors.length&&!row.skipped);
  const branches=[...new Set(lists.employees.map(e=>e.branch).filter(Boolean))].sort();
  const positions=[...new Set(lists.employees.map(e=>e.position).filter(Boolean))].sort();
  const employeeByRegister=new Map(lists.employees.map(e=>[String(e.register||'').trim().toUpperCase(),e]));
  const previewRows=payrollImport?.rows.map(row=>({...row,employee:employeeByRegister.get(row.register)}))||[];
  const importable=previewRows.filter(row=>row.employee&&!lists.payrollEntries.some(entry=>Number(entry.employeeId)===row.employee.id&&entry.month===month&&entry.half===half));
  const [payrollChecking,setPayrollChecking]=useState(false);
  async function checkPayroll(data){
    setPayrollChecking(true);
    try{
      const found=[];const seen=new Set();const values=[];
      for(const row of data.rows){
        const errors=[];const register=String(row.register||'').trim().toUpperCase();
        if(!register)errors.push('Регистрийн дугаар оруулна уу');
        else if(seen.has(register))errors.push('Регистр файл дотор давхардсан');
        seen.add(register);
        if(!Number.isFinite(Number(row.plannedDays))||Number(row.plannedDays)<=0)errors.push('Ажиллавал зохих хоног 0-ээс их байна');
        if(!Number.isFinite(Number(row.salary))||Number(row.salary)<=0)errors.push('Үндсэн цалин 0-ээс их байна');
        if(!Number.isFinite(Number(row.insuredShare))||Number(row.insuredShare)<0||Number(row.insuredShare)>1)errors.push('НДШ тооцох хувь 0–1 байна');
        const employee=employeeByRegister.get(register);
        if(!employee)errors.push('Регистртэй ажилтан бүртгэлд олдсонгүй');
        if(errors.length){found.push({row:row.sourceRow,message:errors.join('; ')});continue}
        if(lists.payrollEntries.some(entry=>Number(entry.employeeId)===employee.id&&entry.month===month&&entry.half===half))continue;
        values.push({employeeId:employee.id,month,half,plannedHours:Number(row.plannedDays)*12,...(importShare?{insuredShare:Number(row.insuredShare)}:{}),__excelRow:row.sourceRow});
      }
      if(values.length){const result=await api('/import/payrollEntries/check',{method:'POST',body:JSON.stringify({rows:values})});found.push(...result.issues)}
      setPayrollImport(current=>current?{...current,issues:found}:current);
      return {found,values};
    }finally{setPayrollChecking(false)}
  }
  async function loadPayrollWorkbook(file){try{const parsed=await parsePayrollWorkbook(file);const data={filename:file.name,...parsed};setPayrollImport(data);await checkPayroll(data)}catch(error){message.error(error.message)}return false}
  async function importWorkbook(){if(!payrollImport)return;setSaving(true);try{const {found,values}=await checkPayroll(payrollImport);if(found.length)return;if(!values.length)throw new Error('Импортлох шинэ мөр алга');const result=await api('/import/payrollEntries',{method:'POST',body:JSON.stringify({filename:payrollImport.filename,rows:values})});message.success(`${result.count} ажилтны цалингийн суурь мэдээлэл амжилттай импортлогдлоо`);setPayrollImport(null);refresh()}catch(error){const match=String(error.message).match(/^(\d+)-р мөр:\s*(.*)$/);if(match)setPayrollImport(current=>({...current,issues:[{row:current.rows[Number(match[1])-2]?.sourceRow||Number(match[1]),message:match[2]}]}));else message.error(error.message)}finally{setSaving(false)}}
  function edit(row){setEditing(row);form.setFieldsValue({plannedHours:row.entry?.plannedHours,workedHours:row.entry?.workedHours,travelDays:row.entry?.travelDays,baseSalary:row.entry?.baseSalary,insuredShare:row.entry?.insuredShare,insuranceRate:row.entry?.insuranceRate,taxRate:row.entry?.taxRate,extraPay:row.entry?.extraPay,otherDeduction:row.entry?.otherDeduction,skipPayroll:row.entry?.skipPayroll,skipReason:row.entry?.skipReason,notes:row.entry?.notes});}
  async function save(values){setSaving(true);try{const body={employeeId:editing.employee.id,month,half,...Object.fromEntries(Object.entries(values).filter(([,value])=>value!==undefined&&value!==null&&value!==''))};const path=editing.entry?`/records/payrollEntries/${editing.entry.id}`:'/records/payrollEntries';await api(path,{method:editing.entry?'PUT':'POST',body:JSON.stringify(body)});message.success('Цалингийн тохируулга амжилттай хадгалагдлаа');setEditing(null);form.resetFields();refresh()}catch(error){message.error(error.message)}finally{setSaving(false)}}
  async function remove(){if(!editing?.entry)return;setSaving(true);try{await api(`/records/payrollEntries/${editing.entry.id}`,{method:'DELETE'});message.success('Цалингийн тохируулга амжилттай устлаа');setEditing(null);form.resetFields();refresh()}catch(error){message.error(error.message)}finally{setSaving(false)}}
  const labels=['Хэлтэс тасаг','Овог','Нэр','Регистрийн дугаар','Албан тушаал','Ээлж','Ажиллавал зохих хоног','Ажиллавал зохих цаг','Ажилласан өдөр','Ажилласан цаг','Зам хоног','Үндсэн цалин','НДШ цалин · лавлагаа','НДШ тооцох хувь','Ажилласан цагийн цалин','Зам хоногийн цалин','Нэмэгдэл','Нийт бодогдсон цалин','НДШ тооцох суурь','НДШ','ХХОАТ суурь','Хөнгөлөлт','ХХОАТ','Бусад суутгал','Нийт суутгал','Гарт олгох','Дансаар олгох','Кассаар олгох','Банк','Данс','Төлөв'];
  const exportRows=()=>downloadExcel(labels,shown.map(row=>Object.fromEntries(labels.map((label,index)=>[label,[row.employee.branch||'',row.employee.lastName,row.employee.firstName,row.employee.register,row.employee.position,row.employee.shiftGroup||'',row.plannedHours/12,row.plannedHours,row.time.dayCount+row.time.nightCount,row.workedHours,row.travelDays,row.baseSalary,row.employee.socialSalary||'',row.insuredShare,row.workPay,row.travelPay,row.extraPay,row.grossPay,row.insuredBase,row.insurance,row.taxBase,row.taxRelief,row.incomeTax,row.otherDeduction,row.totalDeduction,row.netPay,row.bankPay,row.cashPay,row.employee.bankName||'',row.employee.bankAccount||'',row.skipped?`Цалин бодохгүй · ${row.skipReason}`:row.errors.join('; ')||'Шалгахад бэлэн'][index]]))),`цалин-${month}-${half==='first'?'01-15':'16-сүүл'}.xlsx`);
  const columns=[{title:'Ажилтан',key:'employee',fixed:'left',width:190,render:(_,r)=><div><strong>{r.employee.lastName} {r.employee.firstName}</strong><div className="text-xs text-slate-500">{r.employee.position}</div></div>},{title:'Хэлтэс',key:'branch',width:145,render:(_,r)=>r.employee.branch||'—'},{title:'Ээлж',key:'shift',width:70,render:(_,r)=>r.employee.shiftGroup||'—'},{title:'Зохих цаг',dataIndex:'plannedHours',width:95},{title:'Ажилласан цаг',dataIndex:'workedHours',width:105},{title:'Зам хоног',dataIndex:'travelDays',width:90},{title:'Үндсэн цалин',dataIndex:'baseSalary',width:125,render:money},{title:'НДШ %',dataIndex:'insuredShare',width:80,render:v=>`${Math.round(v*100)}%`},{title:'Нийт цалин',dataIndex:'grossPay',width:125,render:money},{title:'НДШ',dataIndex:'insurance',width:110,render:money},{title:'ХХОАТ',dataIndex:'incomeTax',width:110,render:money},{title:'Гарт олгох',dataIndex:'netPay',width:130,render:money},{title:'Дансаар',dataIndex:'bankPay',width:125,render:money},{title:'Кассаар',dataIndex:'cashPay',width:125,render:money},{title:'Шалгалт',key:'errors',width:180,render:(_,r)=>r.skipped?<Tag>Бодохгүй</Tag>:r.errors.length?<Tag color="orange">{r.errors.length} асуудал</Tag>:<Tag color="green">Бэлэн</Tag>},{title:'Үйлдэл',key:'actions',fixed:'right',width:145,render:(_,r)=><Space size={4}><Button size="small" onClick={()=>setDetail(r)}>Задалгаа</Button>{canEdit&&<Button size="small" onClick={()=>edit(r)}>Засах</Button>}</Space>}];
  return <div className="page-stack flex flex-col gap-5"><div className="page-title-row flex flex-wrap items-end justify-between gap-3"><div><div className="eyebrow">HR · ЦАЛИН БОДОЛТ</div><Title level={2}>Цалингийн тооцоо</Title><Text type="secondary">Цагийн бүртгэл, үндсэн цалин, НДШ ба ХХОАТ-ын задрал</Text></div><Space wrap><DatePicker picker="month" value={dayjs(`${month}-01`)} onChange={v=>v&&setMonth(v.format('YYYY-MM'))}/><Segmented value={half} onChange={setHalf} options={[{value:'first',label:'1–15'},{value:'second',label:'16–сүүл'}]}/><Button icon={<DownloadOutlined/>} onClick={exportRows}>Excel татах</Button>{canEdit&&<Upload accept=".xlsx" showUploadList={false} beforeUpload={loadPayrollWorkbook}><Button icon={<UploadOutlined/>}>Цалингийн Excel импорт</Button></Upload>}</Space></div><Alert type="info" showIcon message="Excel загварын тооцоо" description="Ажилласан цалин = үндсэн цалин ÷ ажиллавал зохих цаг × бодит цаг. Зам хоног = цагийн тариф × зам хоног; НДШ суурь = нийт цалин × тохируулсан хувь. Данс = НДШ суурь − суутгал; касс = нийт цалин − НДШ суурь. Тооцоог олгохоос өмнө HR баталгаажуулна."/>{rows.some(r=>r.errors.length)>0&&<Alert type="warning" showIcon message={`${rows.filter(r=>r.errors.length).length} ажилтны өгөгдөл дутуу`} description="Улбар шар мөрийн задрал дээр дарж алдааг харна. Дутуу мөрийн тооцоог бэлэн дүнгийн нийлбэрт оруулаагүй."/>}<Row gutter={12}><Col xs={24} sm={8}><Card bordered={false}><Statistic title="Шалгахад бэлэн" value={ready.length} suffix={`/ ${shown.length}`}/></Card></Col><Col xs={12} sm={8}><Card bordered={false}><Statistic title="Дансаар · бэлэн мөр" value={ready.reduce((n,r)=>n+r.bankPay,0)} formatter={money} suffix="₮"/></Card></Col><Col xs={12} sm={8}><Card bordered={false}><Statistic title="Кассаар · бэлэн мөр" value={ready.reduce((n,r)=>n+r.cashPay,0)} formatter={money} suffix="₮"/></Card></Col></Row><Card bordered={false}><Space wrap className="mb-4"><Input prefix={<SearchOutlined/>} placeholder="Ажилтан хайх" value={search} onChange={e=>setSearch(e.target.value)} style={{width:230}}/><Select value={branch} onChange={setBranch} style={{width:190}} options={[{value:'all',label:'Бүх хэлтэс'},...branches.map(value=>({value,label:value}))]}/><Select value={position} onChange={setPosition} showSearch optionFilterProp="label" style={{width:190}} options={[{value:'all',label:'Бүх албан тушаал'},...positions.map(value=>({value,label:value}))]}/><Select value={shift} onChange={setShift} style={{width:125}} options={[{value:'all',label:'Бүх ээлж'},...['A','B','C','D','AB','CD'].map(value=>({value,label:value}))]}/><Select value={state} onChange={setState} style={{width:155}} options={[{value:'all',label:'Бүх төлөв'},{value:'ready',label:'Бэлэн'},{value:'issue',label:'Асуудалтай'},{value:'skipped',label:'Бодохгүй'}]}/></Space><Table rowKey={r=>r.employee.id} dataSource={shown} columns={columns} scroll={{x:1750}} pagination={{pageSize:20}} size="small"/></Card><Modal title={detail?`${detail.employee.lastName} ${detail.employee.firstName} · Цалингийн задрал`:''} open={!!detail} footer={<Button onClick={()=>setDetail(null)}>Хаах</Button>} onCancel={()=>setDetail(null)}><Descriptions column={1} size="small" bordered items={detail?[['Ажиллавал зохих цаг',detail.plannedHours],['Ажилласан цаг',detail.workedHours],['Цагийн тариф',money(detail.hourlyRate)],['Ажилласан цагийн цалин',money(detail.workPay)],['Зам хоногийн цалин',money(detail.travelPay)],['Нэмэгдэл',money(detail.extraPay)],['Нийт цалин',money(detail.grossPay)],['НДШ тооцох суурь',money(detail.insuredBase)],['НДШ',money(detail.insurance)],['ХХОАТ суурь',money(detail.taxBase)],['Хөнгөлөлт',money(detail.taxRelief)],['ХХОАТ',money(detail.incomeTax)],['Бусад суутгал',money(detail.otherDeduction)],['Гарт олгох',money(detail.netPay)],['Дансаар',money(detail.bankPay)],['Кассаар',money(detail.cashPay)],['Шалгалт',detail.skipped?`Бодохгүй · ${detail.skipReason}${detail.notes?` · ${detail.notes}`:''}`:detail.errors.join('; ')||'Бэлэн']].map(([label,children])=>({key:label,label,children})):[]}/></Modal><Modal title={editing?`${editing.employee.lastName} ${editing.employee.firstName} · Тохируулга`:''} open={!!editing} footer={null} onCancel={()=>{setEditing(null);form.resetFields()}} destroyOnHidden><Alert type="info" showIcon className="mb-4" message="Хоосон орхисон талбарт ажилтан болон цагийн бүртгэлийн утгыг ашиглана."/><Form form={form} layout="vertical" onFinish={save}><div className="grid gap-x-3 sm:grid-cols-2">{[['plannedHours','Ажиллавал зохих цаг'],['workedHours','Ажилласан цаг'],['travelDays','Зам хоног'],['baseSalary','Үндсэн цалин ₮'],['insuredShare','НДШ тооцох хувь (0–1)'],['insuranceRate','НДШ хувь (0–1)'],['taxRate','ХХОАТ хувь (0–1)'],['extraPay','Нэмэгдэл ₮'],['otherDeduction','Бусад суутгал ₮']].map(([key,label])=><Form.Item key={key} name={key} label={label} rules={[{type:'number',min:0,max:['insuredShare','insuranceRate','taxRate'].includes(key)?1:undefined}]}><InputNumber className="w-full" min={0} max={['insuredShare','insuranceRate','taxRate'].includes(key)?1:undefined} step={['insuredShare','insuranceRate','taxRate'].includes(key)?0.01:1} placeholder={String(editing?.[key]??'')}/></Form.Item>)}</div><Form.Item name="skipPayroll" valuePropName="checked"><Checkbox>Энэ хугацаанд цалин бодохгүй</Checkbox></Form.Item><Form.Item name="skipReason" label="Бодохгүй шалтгаан"><Select allowClear options={[{value:"rest",label:"Амралт"},{value:"terminated",label:"Ажлаас гарсан"},{value:"discipline",label:"Сахилгын асуудал"},{value:"other",label:"Бусад"},{value:"unknown",label:"Шалтгаан тодорхойгүй"}]}/></Form.Item><Form.Item name="notes" label="Өөрчлөлтийн тайлбар"><Input.TextArea rows={2}/></Form.Item><Space className="w-full justify-end">{editing?.entry&&<Popconfirm title="Тохируулгыг устгах уу?" onConfirm={remove}><Button danger disabled={saving}>Устгах</Button></Popconfirm>}<Button onClick={()=>setEditing(null)}>Болих</Button><Button type="primary" htmlType="submit" loading={saving}>Хадгалах</Button></Space></Form></Modal><ExcelImportReview open={!!payrollImport} title="Цалингийн Excel шалгах" filename={payrollImport?.filename} rows={payrollImport?.rows} fields={[{key:'register',label:'Регистрийн дугаар'},{key:'sourceName',label:'Ажилтны нэр'},{key:'plannedDays',label:'Ажиллавал зохих хоног',type:'number'},{key:'salary',label:'Үндсэн цалин',type:'number'},{key:'insuredShare',label:'НДШ тооцох хувь (0–1)',type:'number'}]} issues={payrollImport?.issues||[]} checking={payrollChecking} saving={saving} extra={<Alert type="info" showIcon className="mb-3" message={`${month} · ${half==='first'?'1–15':'16–сүүл'} хугацаанд импортлоно`} description={<Checkbox checked={importShare} onChange={event=>setImportShare(event.target.checked)}>НДШ тооцох хувийг хэрэглэх</Checkbox>}/>} onChange={(sourceRow,key,value)=>setPayrollImport(current=>({...current,rows:current.rows.map(row=>row.sourceRow===sourceRow?{...row,[key]:value}:row),issues:current.issues.filter(issue=>Number(issue.row)!==sourceRow)}))} onRemove={sourceRow=>setPayrollImport(current=>({...current,rows:current.rows.filter(row=>row.sourceRow!==sourceRow),issues:current.issues.filter(issue=>Number(issue.row)!==sourceRow)}))} onCheck={()=>payrollImport&&checkPayroll(payrollImport)} onImport={importWorkbook} onClose={()=>setPayrollImport(null)}/></div>;
}

function CampCheck({lists,user,date,setDate,refresh}) {
  const staff=useMemo(()=>lists.employees.filter(employee=>Number(employee.campId)===Number(user.campId)),[lists.employees,user.campId]);
  const camp=lists.camps.find(item=>item.id===Number(user.campId));
  const [checks,setChecks]=useState({});
  const [saving,setSaving]=useState(false);
  useEffect(()=>{
    setChecks(Object.fromEntries(staff.map(employee=>{
      const record=lists.attendance.find(row=>Number(row.employeeId)===employee.id&&row.date===date);
      return [employee.id,{status:record?.status || null,actualHours:num(record?.actualHours),notes:record?.notes || ''}];
    })));
  },[staff,lists.attendance,date]);
  const checked=staff.filter(employee=>checks[employee.id]?.status).length;
  function update(id,change){setChecks(current=>({...current,[id]:{...current[id],...change}}))}
  async function submit(){
    if(checked!==staff.length)return message.warning('Ажилтан бүрийн төлөвийг сонгоно уу');
    setSaving(true);
    try {
      const rows=staff.map(employee=>({date,employeeId:employee.id,campId:user.campId,...checks[employee.id]}));
      const result=await api('/attendance/submit',{method:'POST',body:JSON.stringify({rows})});
      message.success(`${result.count} ажилтны цаг бүртгэл илгээгдлээ`);refresh();
    } catch(e){message.error(e.message)} finally{setSaving(false)}
  }
  return <div className="page-stack flex flex-col gap-5"><div className="page-title-row flex items-end justify-between gap-4"><div><div className="eyebrow">CAMP АХЛАХЫН ӨДӨР ТУТМЫН БҮРТГЭЛ</div><Title level={2}>Хүмүүсээ шалгах</Title><Text type="secondary">{camp?.name || 'Camp тохируулаагүй'} · ажилласан эсэхийг нэг бүрчлэн тэмдэглэнэ</Text></div><DatePicker value={dayjs(date)} onChange={v=>v&&setDate(v.format('YYYY-MM-DD'))}/></div><div className="flex flex-wrap items-center justify-between gap-3 rounded-xl bg-white px-5 py-4 shadow-sm"><div><strong className="text-base text-slate-800">{checked} / {staff.length} шалгасан</strong><p className="mb-0 mt-1 text-xs text-slate-500">Өдөр, шөнө, ажиллаагүй, амралт эсвэл чөлөөний төлөв сонгоно</p></div><Button type="primary" size="large" loading={saving} disabled={!staff.length||checked!==staff.length} onClick={submit}>Бүртгэл илгээх</Button></div>{!camp&&<Alert type="warning" showIcon message="Энэ хэрэглэгчид camp оноогоогүй байна. Админ Хэрэглэгчид хэсгээс camp сонгоно уу."/>}{staff.length?<div className="grid gap-3">{staff.map(employee=>{const choice=checks[employee.id]||{};const rotation=workState(employee,date,lists.attendance,lists.shiftOverrides);return <div key={employee.id} className="rounded-xl bg-white p-4 shadow-sm sm:p-5"><div className="flex flex-wrap items-start justify-between gap-2"><div><strong className="text-sm text-slate-800">{employee.lastName} {employee.firstName}</strong><div className="mt-1 text-xs text-slate-500">{employee.position} · {employee.shiftGroup || '—'} ээлж</div></div><Tag color={rotation.available?'green':'default'}>{rotation.label}</Tag></div><div className="mt-4 grid grid-cols-2 gap-2 sm:grid-cols-3 xl:grid-cols-6">{[['day','Өдөр ажилласан'],['night','Шөнө ажилласан'],['travel','Замд явсан'],['absent','Ажиллаагүй'],['rest','Амралттай'],['leave','Чөлөөтэй']].map(([status,label])=><button key={status} type="button" onClick={()=>update(employee.id,{status,actualHours:['day','night'].includes(status)?(['day','night'].includes(choice.status)?choice.actualHours:12):0})} className={`min-h-10 rounded-lg border px-2 py-2 text-xs font-semibold transition-colors ${choice.status===status?'border-violet-500 bg-violet-50 text-violet-700':'border-slate-200 bg-white text-slate-600 hover:border-violet-300'}`}>{label}</button>)}</div><div className="mt-3 grid gap-2 sm:grid-cols-[160px_1fr]">{['day','night'].includes(choice.status)&&<InputNumber min={0} max={24} value={choice.actualHours} onChange={value=>update(employee.id,{actualHours:value||0})} addonAfter="цаг" style={{width:'100%'}}/>}<Input placeholder="Тайлбар (сонголтоор)" value={choice.notes} onChange={event=>update(employee.id,{notes:event.target.value})}/></div></div>})}</div>:<Card bordered={false}><Empty description="Энэ camp-д ажилтан бүртгээгүй байна"/></Card>}</div>;
}

function TasksPage({lists,submissions,refresh,user,date,setDate}) {
  const [checks,setChecks]=useState({});
  const [saving,setSaving]=useState(false);
  const tasks=lists.assignments.filter(task=>task.date===date).sort((a,b)=>String(a.shift).localeCompare(String(b.shift))||String(a.title).localeCompare(String(b.title)));
  useEffect(()=>{
    setChecks(Object.fromEntries(tasks.map(task=>{
      const submitted=submissions.find(row=>row.assignment_id===task.id&&row.work_date===date);
      return [task.id,submitted?{status:submitted.status,actualHours:submitted.actual_hours,actualFuel:submitted.actual_fuel,actualOutput:submitted.actual_output,note:submitted.note || ''}:{}];
    })));
  },[date,lists.assignments,submissions]);
  const update=(id,patch)=>setChecks(previous=>({...previous,[id]:{...previous[id],...patch}}));
  const marked=tasks.filter(task=>['done','not_done'].includes(checks[task.id]?.status)).length;
  const completed=tasks.filter(task=>checks[task.id]?.status==='done').length;
  async function submit(){
    if(marked!==tasks.length)return message.warning('Ажил бүрийн хийсэн эсэхийг сонгоно уу');
    setSaving(true);
    try{
      const rows=tasks.map(task=>({assignmentId:task.id,status:checks[task.id].status,actualHours:checks[task.id].status==='done'?num(checks[task.id].actualHours):0,actualFuel:checks[task.id].status==='done'?num(checks[task.id].actualFuel):0,actualOutput:checks[task.id].status==='done'?num(checks[task.id].actualOutput):0,note:checks[task.id].note || ''}));
      const result=await api('/submissions/batch',{method:'POST',body:JSON.stringify({rows})});
      message.success(`${result.count} ажлын гүйцэтгэл амжилттай илгээгдлээ`);
      await refresh();
    }catch(error){message.error(error.message)}finally{setSaving(false)}
  }
  return <div className="page-stack flex flex-col gap-5"><div className="page-title-row flex items-end justify-between gap-4"><div><div className="eyebrow">ӨДРИЙН АЖЛЫН ХУВААРЬ</div><Title level={2}>{date===today()?'Өнөөдрийн ажлын хуваарь':'Ажлын хуваарь'}</Title><Text type="secondary">Төлөвлөгөөнд оноосон ажилтан, техник болон хийх ажлыг шалгаж илгээнэ</Text></div><DatePicker value={dayjs(date)} onChange={value=>value&&setDate(value.format('YYYY-MM-DD'))}/></div><div className="flex flex-wrap items-center justify-between gap-3 rounded-xl bg-white px-5 py-4 shadow-sm"><div><strong className="text-base text-slate-800">{marked} / {tasks.length} ажил шалгасан</strong><p className="mb-0 mt-1 text-xs text-slate-500">Хийсэн {completed} · Хийгээгүй {marked-completed} · Хүлээгдэж буй {tasks.length-marked}</p></div>{user.role==='hr'?<Tag>Зөвхөн харах</Tag>:<Button type="primary" size="large" loading={saving} disabled={!tasks.length||marked!==tasks.length} onClick={submit}>Бүртгэл илгээх</Button>}</div>{tasks.length?<div className="grid gap-3">{tasks.map(task=>{const employee=lists.employees.find(row=>row.id===Number(task.employeeId));const machine=lists.equipment.find(row=>row.id===Number(task.equipmentId));const plan=lists.plans.find(row=>row.id===Number(task.planId));const check=checks[task.id] || {};const submitted=submissions.find(row=>row.assignment_id===task.id&&row.work_date===date);const state=employee?workState(employee,date,lists.attendance,lists.shiftOverrides):null;return <Card key={task.id} bordered={false} className="task-card"><div className="flex flex-wrap items-start justify-between gap-3"><div><span className="task-date">{task.date} · {task.shift==='night'?'Шөнийн':'Өдрийн'} ээлж</span><h3 className="mb-1 mt-2 text-base font-bold">{task.title}</h3><p className="m-0 text-xs text-slate-500">{plan?.name || task.site || 'Төлөвлөгөө'}{task.site&&plan?` · ${task.site}`:''}</p></div><StatusTag value={submitted?.status || 'pending'}/></div><div className="mt-4 flex flex-wrap gap-2"><Tag color="blue"><TeamOutlined/> {employee?`${employee.lastName} ${employee.firstName}`:'Техникийн ажил'}</Tag>{employee?.shiftGroup&&<Tag color="purple">{employee.shiftGroup} ээлж</Tag>}{state&&<Tag color={state.available?'green':'orange'}>{state.label}</Tag>}{machine&&<Tag color="cyan"><ToolOutlined/> {machine.parkNo} · {machine.model}</Tag>}</div><div className="mt-4 flex flex-wrap items-center gap-3"><strong className="text-xs text-slate-600">Гүйцэтгэл</strong><div className="grid w-full grid-cols-1 gap-2 sm:w-auto sm:grid-cols-2">{[['done','Ажилласан / хийсэн'],['not_done','Ажиллаагүй / хийгээгүй']].map(([status,label])=><button key={status} type="button" aria-pressed={check.status===status} onClick={()=>update(task.id,{status,actualHours:status==='done'?(check.actualHours ?? motorHoursFor(lists,task) ?? task.plannedHours ?? 0):0,actualFuel:status==='done'?(check.actualFuel ?? 0):0,actualOutput:status==='done'?(check.actualOutput ?? 0):0})} className={`min-h-10 rounded-lg border px-3 py-2 text-xs font-semibold ${check.status===status?'border-violet-500 bg-violet-50 text-violet-700':'border-slate-200 bg-white text-slate-600'}`}>{label}</button>)}</div></div>{check.status==='done'&&<div className="mt-4 grid grid-cols-1 gap-2 sm:grid-cols-3"><label className="text-xs text-slate-500">Бодит цаг<InputNumber min={0} max={24} value={check.actualHours} onChange={value=>update(task.id,{actualHours:value})} addonAfter="цаг" style={{width:'100%',marginTop:5}}/></label><label className="text-xs text-slate-500">Зарцуулсан түлш<InputNumber min={0} value={check.actualFuel} onChange={value=>update(task.id,{actualFuel:value})} addonAfter="л" style={{width:'100%',marginTop:5}}/></label><label className="text-xs text-slate-500">Бодит бүтээл<InputNumber min={0} value={check.actualOutput} onChange={value=>update(task.id,{actualOutput:value})} style={{width:'100%',marginTop:5}}/></label></div>}<Input className="mt-3" placeholder="Тайлбар (сонголтоор)" value={check.note} onChange={event=>update(task.id,{note:event.target.value})}/>{submitted&&<p className="mb-0 mt-2 text-xs text-slate-400">Өмнө илгээсэн: {submitted.submittedByName}</p>}</Card>})}</div>:<Card bordered={false}><Empty description="Энэ өдөрт хуваарь алга. Админ Бүтээл хэсэгт ажилтан, техник оноож төлөвлөгөө хадгална."/></Card>}</div>;
}

function calculate(lists,submissions) {
  const completed=submissions.filter(s=>s.status==='done');
  const assignmentMap=new Map(lists.assignments.map(a=>[a.id,a]));
  const planMap=new Map(lists.plans.map(p=>[p.id,p]));
  const revenue=completed.reduce((sum,s)=>sum+num(s.actual_output)*num(planMap.get(Number(assignmentMap.get(s.assignment_id)?.planId))?.unitRevenue),0);
  const fuelPrice=lists.fuel.filter(f=>f.kind==='receipt'&&num(f.pricePerLiter)>0).at(0)?.pricePerLiter || 0;
  const fuelExpense=completed.reduce((sum,s)=>sum+num(s.actual_fuel)*num(fuelPrice),0);
  const otherExpense=lists.other.reduce((sum,o)=>sum+num(o.amount),0);
  const fuelStock=lists.fuel.reduce((sum,f)=>sum+(f.kind==='receipt'?num(f.liters):-num(f.liters)),0);
  const plannedFuel=lists.assignments.reduce((sum,a)=>sum+num(a.plannedFuel),0);
  const usedFuel=completed.reduce((sum,s)=>sum+num(s.actual_fuel),0);
  return {completed,revenue,fuelExpense,otherExpense,totalExpense:fuelExpense+otherExpense,profit:revenue-fuelExpense-otherExpense,fuelStock,plannedFuel,usedFuel,fuelVariance:plannedFuel-usedFuel};
}

function Dashboard({lists,submissions,date,setDate,onNavigate}) {
  const metrics=calculate(lists,submissions);
  const active=lists.employees.filter(e=>workState(e,date,lists.attendance,lists.shiftOverrides).available).length;
  const ready=lists.equipment.filter(e=>e.status==='ready'&&e.availability==='available').length;
  const lastDays=Array.from({length:7},(_,i)=>dayjs(date).subtract(6-i,'day').format('YYYY-MM-DD'));
  const graph=lastDays.map(d=>{const entries=submissions.filter(s=>s.work_date===d&&s.status==='done');const hauls=lists.productionEntries.filter(row=>row.date===d&&row.kind==='actual');return {name:dayjs(d).format('MM.DD'),Бүтээл:hauls.length?hauls.reduce((n,row)=>n+num(row.amount),0):entries.reduce((n,s)=>n+num(s.actual_output),0),Түлш:entries.reduce((n,s)=>n+num(s.actual_fuel),0)}});
  const recent=submissions.slice(0,5);
  const campRows=lists.campStays.filter(row=>row.date===date);
  const campCount=category=>campRows.filter(row=>row.category===category).reduce((total,row)=>total+num(row.count),0);
  const attendanceRows=lists.attendance.filter(row=>row.date===date);
  const stops=lists.maintenance.filter(row=>row.date===date&&row.status!=='closed');
  const unknownRotation=lists.employees.filter(e=>!e.shiftStart||!e.shiftGroup).length;
  return <div className="page-stack flex flex-col gap-5"><div className="page-title-row flex items-end justify-between gap-4"><div><div className="eyebrow">УУРХАЙН УДИРДЛАГА</div><Title level={2}>Хяналтын самбар</Title><Text type="secondary">{dayjs(date).format('YYYY оны MM сарын DD')} · Өдрийн нөхцөл байдал</Text></div><DatePicker value={dayjs(date)} onChange={v=>v&&setDate(v.format('YYYY-MM-DD'))}/></div><div className="metric-grid grid gap-4"><Card bordered={false} className="metric-card"><div className="metric-icon green"><TeamOutlined/></div><span>Ээлжээр ажиллах боломжтой</span><strong>{active}<small> / {lists.employees.length}</small></strong><p>Хуваарь дутуу {unknownRotation} ажилтан</p></Card><Card bordered={false} className="metric-card"><div className="metric-icon blue"><ToolOutlined/></div><span>Бэлэн техник</span><strong>{ready}<small> / {lists.equipment.length}</small></strong><p>Засварт байгаа {lists.equipment.filter(e=>e.status==='maintenance').length}</p></Card><Card bordered={false} className="metric-card"><div className="metric-icon violet"><CheckCircleOutlined/></div><span>Гүйцэтгэсэн ажил</span><strong>{metrics.completed.length}<small> / {lists.assignments.length}</small></strong><p>Нийт даалгаврын биелэлт</p></Card><Card bordered={false} className="metric-card"><div className="metric-icon orange"><FireOutlined/></div><span>Түлшний үлдэгдэл</span><strong>{money(metrics.fuelStock)}<small> л</small></strong><p>Орлого ба зарцуулалтын зөрүү</p></Card></div><div className="grid gap-4 lg:grid-cols-2"><Card bordered={false} title="Camp · өнөөдрийн бүртгэл" extra={<Button type="link" onClick={()=>onNavigate('campStays')}>Дэлгэрэнгүй</Button>}><div className="grid grid-cols-3 gap-2 text-center"><div className="rounded-xl bg-violet-50 p-3"><strong className="block text-xl text-violet-700">{campCount('employee')}</strong><span className="text-xs">Үндсэн ажилтан</span></div><div className="rounded-xl bg-blue-50 p-3"><strong className="block text-xl text-blue-700">{campCount('guest')}</strong><span className="text-xs">Зочин</span></div><div className="rounded-xl bg-orange-50 p-3"><strong className="block text-xl text-orange-700">{campCount('rental')}</strong><span className="text-xs">Түрээсийн ажилтан</span></div></div><p className="mb-0 mt-3 text-xs text-slate-500">Зөвхөн тухайн өдөр camp-д бүртгэсэн хоногийн тоо. Бүртгэлгүй хүнийг ирсэнд тооцохгүй.</p></Card><Card bordered={false} title="Ээлж ба техникийн зогсолт" extra={<Button type="link" onClick={()=>onNavigate('maintenance')}>Зогсолтын бүртгэл</Button>}><div className="flex flex-wrap gap-2"><Tag color="blue">Өдөр ажилласан {attendanceRows.filter(row=>row.status==='day').length}</Tag><Tag color="purple">Шөнө ажилласан {attendanceRows.filter(row=>row.status==='night').length}</Tag><Tag color="orange">Зогссон техник {new Set(stops.map(row=>row.equipmentId)).size}</Tag></div>{stops.length?<div className="mt-3 grid gap-1 text-xs">{stops.slice(0,3).map(row=><span key={row.id}>{lists.equipment.find(item=>item.id===Number(row.equipmentId))?.parkNo||'Техник'} · {row.reason}</span>)}</div>:<p className="mb-0 mt-3 text-xs text-slate-500">Өнөөдрийн зогсолт бүртгэгдээгүй.</p>}{unknownRotation>0&&<p className="mb-0 mt-2 text-xs text-orange-700">{unknownRotation} ажилтны ээлжийн эхлэх өдөр эсвэл бүлэг дутуу тул ирэх/буух тоог бүрэн гаргах боломжгүй.</p>}</Card></div><Row gutter={[18,18]}><Col xs={24} xl={16}><Card bordered={false} className="chart-card" title="Сүүлийн 7 өдрийн гүйцэтгэл" extra={<span className="chart-extra">Бүтээл / түлш</span>}><ResponsiveContainer width="100%" height={290}><LineChart data={graph} margin={{top:12,right:14,left:-20,bottom:0}}><CartesianGrid stroke="#edf0f4" vertical={false}/><XAxis dataKey="name" axisLine={false} tickLine={false}/><YAxis axisLine={false} tickLine={false}/><Tooltip/><Legend/><Line type="monotone" dataKey="Бүтээл" stroke="#7257d9" strokeWidth={3} dot={false}/><Line type="monotone" dataKey="Түлш" stroke="#2bbf83" strokeWidth={3} dot={false}/></LineChart></ResponsiveContainer></Card></Col><Col xs={24} xl={8}><Card bordered={false} className="overview-card" title="Тайлангийн тойм"><div className="overview-row"><span>Бүтээлийн орлого</span><b>{money(metrics.revenue)} ₮</b></div><div className="overview-row"><span>Нийт зарлага</span><b>{money(metrics.totalExpense)} ₮</b></div><div className="overview-row total"><span>Үр дүн</span><b>{money(metrics.profit)} ₮</b></div><Button type="link" onClick={()=>onNavigate('reports')}>Дэлгэрэнгүй тайлан →</Button></Card></Col></Row><Row gutter={[18,18]}><Col xs={24} xl={14}><Card bordered={false} title="Төлөвлөгөөний нөөц" extra={<Button type="link" onClick={()=>onNavigate('plans')}>Бүгдийг харах</Button>}><Readiness lists={{...lists,plans:lists.plans.slice(0,2)}} date={date}/>{!lists.plans.length&&<Empty description="Төлөвлөгөө бүртгээгүй"/>}</Card></Col><Col xs={24} xl={10}><Card bordered={false} title="Сүүлийн гүйцэтгэл">{recent.length?<div className="activity-list">{recent.map(s=><div className="activity-item" key={s.id}><div className="activity-dot"><FileDoneOutlined/></div><div><strong>{lists.assignments.find(a=>a.id===s.assignment_id)?.title || 'Даалгавар'}</strong><span>{s.submittedByName} · {dayjs(s.submitted_at).format('MM.DD HH:mm')}</span></div><StatusTag value={s.status}/></div>)}</div>:<Empty description="Илгээсэн гүйцэтгэл алга"/>}</Card></Col></Row></div>
}

function AttendanceReport({lists,date,scope}) {
  const rows=lists.attendance.filter(row=>scope==='all'||row.date===date);
  const count=status=>rows.filter(row=>row.status===status).length;
  return <Card bordered={false} title="Camp-ийн ирцийн тайлан" className="table-card" extra={<Space wrap><Tag color="blue">Өдөр {count('day')}</Tag><Tag color="purple">Шөнө {count('night')}</Tag><Tag color="cyan">Зам {count('travel')}</Tag><Tag color="red">Ажиллаагүй {count('absent')}</Tag><Tag>Амралт {count('rest')}</Tag><Tag color="gold">Чөлөө {count('leave')}</Tag></Space>}><Table rowKey="id" dataSource={rows} scroll={{x:800}} pagination={{pageSize:8}} columns={[{title:'Өдөр',dataIndex:'date'},{title:'Ажилтан',render:(_,row)=>{const e=lists.employees.find(item=>item.id===Number(row.employeeId));return e?`${e.lastName} ${e.firstName}`:'—'}},{title:'Camp',render:(_,row)=>lists.camps.find(item=>item.id===Number(row.campId))?.name || '—'},{title:'Төлөв',dataIndex:'status',render:value=><StatusTag value={value}/>},{title:'Ажилласан цаг',dataIndex:'actualHours',render:value=>num(value)},{title:'Тайлбар',dataIndex:'notes'}]}/></Card>;
}

function MotorHoursReport({lists,date,scope}) {
  const rows=lists.machineLogs.filter(log=>scope==='all'||log.date===date).map(log=>({
    ...log,
    employee:lists.employees.find(e=>e.id===Number(log.employeeId)),
    equipment:lists.equipment.find(e=>e.id===Number(log.equipmentId)),
    motorHours:Math.max(0,num(log.endHours)-num(log.startHours)),
  }));
  const total=rows.reduce((sum,row)=>sum+row.motorHours,0);
  return <Card bordered={false} title="Диспетчерийн мото цаг" extra={<Tag color="purple">Нийт {total.toFixed(1)} цаг</Tag>} className="table-card"><Table rowKey="id" dataSource={rows} scroll={{x:900}} pagination={{pageSize:8}} columns={[{title:'Өдөр',dataIndex:'date'},{title:'Өдөр/шөнө',dataIndex:'workShift',render:v=>statusLabels[v]||'—'},{title:'A/B/C/D',dataIndex:'shiftGroup'},{title:'Оператор',render:(_,r)=>r.employee?`${r.employee.lastName} ${r.employee.firstName}`:'—'},{title:'Техник',render:(_,r)=>r.equipment?.parkNo || '—'},{title:'Эхлэл',dataIndex:'startHours'},{title:'Төгсгөл',dataIndex:'endHours'},{title:'Мото цаг',dataIndex:'motorHours',render:v=>v.toFixed(1)},{title:'12 цагийн тэнцэл',render:(_,r)=>r.productiveHours===undefined?<Tag>Хуучин мөр</Tag>:<Tag color={Math.abs(shiftHourTotal(r)-12)<0.01?'green':'red'}>{shiftHourTotal(r).toFixed(1)} / 12</Tag>},{title:'Зогсолтын задаргаа',render:(_,r)=>shiftHourFields.filter(([key])=>key!=='productiveHours'&&num(r[key])>0).map(([key,label])=>`${label}: ${num(r[key])} цаг`).join(' · ')||r.stopReason||'—'},{title:'Шалгасан',dataIndex:'dispatcherChecked',render:v=><Tag color={v==='yes'?'green':'orange'}>{v==='yes'?'Тийм':'Үгүй'}</Tag>}]}/></Card>
}

function AllowanceReport({lists,date,scope}) {
  const rows=lists.mealFeedback.filter(row=>row.hrStatus==='approved'&&(scope==='all'||row.date===date));
  const total=rows.reduce((sum,row)=>sum+num(row.approvedAllowance),0);
  const exportRows=()=>downloadExcel(['Өдөр','Ажилтан','Camp','Санал хүсэлт','Баталсан нэмэгдэл ₮'],rows.map(row=>{const employee=lists.employees.find(item=>item.id===Number(row.employeeId));return {'Өдөр':row.date,'Ажилтан':employee?`${employee.lastName} ${employee.firstName}`:'','Camp':lists.camps.find(item=>item.id===Number(row.campId))?.name||'','Санал хүсэлт':row.comment,'Баталсан нэмэгдэл ₮':num(row.approvedAllowance)}}),'баталсан-хоолны-нэмэгдэл.xlsx');
  return <Card bordered={false} title="HR баталсан хоолны нэмэгдэл" extra={<Space wrap><Tag color="purple">Нийт {money(total)} ₮</Tag><Button size="small" icon={<DownloadOutlined/>} onClick={exportRows}>Excel татах</Button></Space>} className="table-card"><Alert type="info" showIcon className="mb-4" message="Цалингийн нэмэгдлийн санал" description="Зөвхөн HR баталсан дүнг энд харуулна. Үндсэн цалин болон ашиг/алдагдлын тооцоонд автоматаар нэмээгүй."/><Table rowKey="id" dataSource={rows} scroll={{x:700}} pagination={{pageSize:8}} columns={[{title:'Өдөр',dataIndex:'date'},{title:'Ажилтан',render:(_,row)=>{const employee=lists.employees.find(item=>item.id===Number(row.employeeId));return employee?`${employee.lastName} ${employee.firstName}`:'—'}},{title:'Camp',render:(_,row)=>lists.camps.find(item=>item.id===Number(row.campId))?.name||'—'},{title:'Санал хүсэлт',dataIndex:'comment'},{title:'Нэмэгдэл ₮',dataIndex:'approvedAllowance',render:money}]}/></Card>;
}

function Reports({lists,submissions,date,setDate}) {
  const [scope,setScope]=useState('all');
  const reportSubs=scope==='day'?submissions.filter(s=>s.work_date===date):submissions;
  const reportLists=scope==='day'?{...lists,assignments:lists.assignments.filter(a=>a.date===date),other:lists.other.filter(o=>o.date===date),productionEntries:lists.productionEntries.filter(row=>row.date===date)}:lists;
  const m=calculate(reportLists,reportSubs);
  const planMap=new Map(lists.plans.map(p=>[p.id,p]));
  const assignmentMap=new Map(lists.assignments.map(a=>[a.id,a]));
  const rows=reportSubs.map(s=>{const a=assignmentMap.get(s.assignment_id);const p=planMap.get(Number(a?.planId));return {...s,title:a?.title || 'Устгасан даалгавар',employee:lists.employees.find(e=>e.id===Number(a?.employeeId)),equipment:lists.equipment.find(e=>e.id===Number(a?.equipmentId)),income:s.status==='done'?num(s.actual_output)*num(p?.unitRevenue):0}});
  const exportReport=()=>{const columns=['Өдөр','Ажил','Ажилтан','Техник','Төлөв','Бодит цаг','Бүтээл','Түлш л','Орлого ₮','Илгээсэн'];const data=rows.map(r=>({'Өдөр':r.work_date,'Ажил':r.title,'Ажилтан':r.employee?`${r.employee.lastName} ${r.employee.firstName}`:'','Техник':r.equipment?.parkNo || '','Төлөв':statusLabels[r.status],'Бодит цаг':r.actual_hours,'Бүтээл':r.actual_output,'Түлш л':r.actual_fuel,'Орлого ₮':r.income,'Илгээсэн':r.submittedByName}));downloadExcel(columns,data,'mpc-hr-тайлан.xlsx')};
  return <div className="page-stack flex flex-col gap-5"><div className="page-title-row flex items-end justify-between gap-4"><div><div className="eyebrow">ДҮН ШИНЖИЛГЭЭ</div><Title level={2}>Тайлан</Title><Text type="secondary">Баталгаажуулсан ажлын бүтээл ба бүртгэсэн зарлага</Text></div><Space><Segmented value={scope} onChange={setScope} options={[{value:'all',label:'Бүх хугацаа'},{value:'day',label:'Өдөр'}]}/><DatePicker value={dayjs(date)} onChange={v=>v&&setDate(v.format('YYYY-MM-DD'))}/><Button icon={<DownloadOutlined/>} onClick={exportReport}>Excel татах</Button></Space></div><Alert showIcon type="info" message="Тооцооллын зарчим" description="Орлого = гүйцэтгэсэн бүтээл × төлөвлөгөөний нэгжийн орлого. Зарлага = бодит түлш × бүртгэсэн түлшний хамгийн сүүлийн нэгжийн үнэ + бусад зардал. Цалин, элэгдэл болон татвар ороогүй."/><div className="report-grid grid gap-4"><Card bordered={false}><Statistic title="Бүтээлийн орлого" value={m.revenue} formatter={money} suffix="₮" valueStyle={{color:'#2aaf77'}}/></Card><Card bordered={false}><Statistic title="Түлшний зарлага" value={m.fuelExpense} formatter={money} suffix="₮"/></Card><Card bordered={false}><Statistic title="Бусад зарлага" value={m.otherExpense} formatter={money} suffix="₮"/></Card><Card bordered={false}><Statistic title="Үр дүн" value={m.profit} formatter={money} suffix="₮" valueStyle={{color:m.profit<0?'#d94b58':'#392b75'}}/></Card></div><Row gutter={[18,18]}><Col xs={24} md={12}><Card bordered={false} title="Түлшний төлөвлөгөө"><div className="fuel-large">{money(m.usedFuel)} <small>/ {money(m.plannedFuel)} л</small></div><Progress percent={m.plannedFuel?Math.min(100,Math.round(m.usedFuel/m.plannedFuel*100)):0} strokeColor="#7956d8"/><div className="overview-row"><span>Зөрүү</span><b>{m.fuelVariance>=0?`${money(m.fuelVariance)} л хэмнэсэн`:`${money(-m.fuelVariance)} л илүү`}</b></div></Card></Col><Col xs={24} md={12}><Card bordered={false} title="Ажлын биелэлт"><div className="fuel-large">{m.completed.length} <small>/ {reportLists.assignments.length} ажил</small></div><Progress percent={reportLists.assignments.length?Math.round(m.completed.length/reportLists.assignments.length*100):0} strokeColor="#2bbf83"/><div className="overview-row"><span>Хийгээгүй</span><b>{reportSubs.filter(s=>s.status==='not_done').length} ажил</b></div></Card></Col></Row><ProductionSummary entries={lists.productionEntries} date={date} defaultPeriod="year"/><AllowanceReport lists={lists} date={date} scope={scope}/><AttendanceReport lists={lists} date={date} scope={scope}/><MotorHoursReport lists={lists} date={date} scope={scope}/><Card bordered={false} title="Илгээсэн гүйцэтгэл" className="table-card"><Table rowKey="id" dataSource={rows} scroll={{x:1000}} pagination={{pageSize:10}} columns={[{title:'Өдөр',dataIndex:'work_date'},{title:'Ажил',dataIndex:'title'},{title:'Ажилтан',render:(_,r)=>r.employee?`${r.employee.lastName} ${r.employee.firstName}`:'—'},{title:'Техник',render:(_,r)=>r.equipment?.parkNo || '—'},{title:'Төлөв',dataIndex:'status',render:v=><StatusTag value={v}/>},{title:'Цаг',dataIndex:'actual_hours'},{title:'Түлш л',dataIndex:'actual_fuel'},{title:'Бүтээл',dataIndex:'actual_output'},{title:'Орлого ₮',dataIndex:'income',render:money},{title:'Илгээсэн',dataIndex:'submittedByName'}]}/></Card></div>
}

function Users({users,camps,employees,refresh,currentUser,roleNames}) {
  const [open,setOpen]=useState(false);
  const [editing,setEditing]=useState(null);
  const [form]=Form.useForm();
  const [passwordOpen,setPasswordOpen]=useState(false);
  const [passwordForm]=Form.useForm();
  const [savingPassword,setSavingPassword]=useState(false);
  const selectedRole=Form.useWatch('role',form);
  async function save(values){try{await api(editing?`/users/${editing.id}`:'/users',{method:editing?'PATCH':'POST',body:JSON.stringify(values)});message.success('Хэрэглэгч хадгалагдлаа');setOpen(false);setEditing(null);form.resetFields();refresh()}catch(e){message.error(e.message)}}
  async function toggle(row){try{await api(`/users/${row.id}`,{method:'PATCH',body:JSON.stringify({active:!row.active})});await refresh();message.success(row.active?'Хэрэглэгчийг амжилттай идэвхгүй болголоо':'Хэрэглэгчийг амжилттай идэвхжүүллээ')}catch(e){message.error(e.message)}}
  function edit(row){form.resetFields();setEditing(row);form.setFieldsValue({username:row.username,name:row.name,role:row.role,campId:row.campId,employeeId:row.employeeId});setOpen(true)}
  function add(){setEditing(null);form.resetFields();setOpen(true)}
  async function changePassword(values){setSavingPassword(true);try{await api('/me/password',{method:'PATCH',body:JSON.stringify({currentPassword:values.currentPassword,newPassword:values.newPassword})});message.success('Нууц үг амжилттай солигдлоо');passwordForm.resetFields();setPasswordOpen(false)}catch(e){message.error(e.message)}finally{setSavingPassword(false)}}
  return <div className="page-stack flex flex-col gap-5"><div className="page-title-row flex items-end justify-between gap-4"><div><div className="eyebrow">ХАНДАХ ЭРХ</div><Title level={2}>Хэрэглэгчид</Title><Text type="secondary">Админ болон хээрийн бүртгэлийн эрхүүд</Text></div><Space wrap><Button onClick={()=>setPasswordOpen(true)}>Нууц үгээ солих</Button><Button type="primary" icon={<PlusOutlined/>} onClick={add}>Хэрэглэгч нэмэх</Button></Space></div><Card bordered={false} className="table-card"><Table rowKey="id" dataSource={users} scroll={{x:650}} columns={[{title:'Нэвтрэх нэр',dataIndex:'username'},{title:'Нэр',dataIndex:'name'},{title:'Эрх',dataIndex:'role',render:v=><Tag color="purple">{roleNames[v]}</Tag>},{title:'Ажилтан',dataIndex:'employeeId',render:id=>{const e=employees.find(e=>e.id===Number(id));return e?`${e.lastName} ${e.firstName}`:'—'}},{title:'Camp',dataIndex:'campId',render:id=>camps.find(c=>c.id===Number(id))?.name || '—'},{title:'Төлөв',dataIndex:'active',render:v=><Tag color={v?'green':'default'}>{v?'Идэвхтэй':'Идэвхгүй'}</Tag>},{title:'Үйлдэл',render:(_,r)=><Space><Button size="small" onClick={()=>edit(r)}>Засах</Button><Button size="small" onClick={()=>toggle(r)}>{r.active?'Идэвхгүй болгох':'Идэвхжүүлэх'}</Button></Space>}]}/></Card><Modal title={editing?'Хэрэглэгч засах':'Хэрэглэгч нэмэх'} open={open} footer={null} onCancel={()=>setOpen(false)}><Form form={form} layout="vertical" onFinish={save}><Form.Item name="username" label="Нэвтрэх нэр" rules={editing?[]:[{required:true}]}><Input disabled={!!editing}/></Form.Item><Form.Item name="name" label="Нэр" rules={[{required:true}]}><Input/></Form.Item><Form.Item name="employeeId" label="Ажилтан" rules={editing?[]:[{required:true,message:"Ажилтан сонгоно уу"}]}><Select showSearch optionFilterProp="label" options={employees.map(e=>({value:e.id,label:`${e.lastName} ${e.firstName} · ${e.position}`}))}/></Form.Item><Form.Item name="role" label="Эрх" rules={[{required:true}]}><Select options={Object.entries(roleNames).map(([value,label])=>({value,label}))}/></Form.Item>{selectedRole==='camp'&&<Form.Item name="campId" label="Хариуцах camp" rules={[{required:true,message:'Camp сонгоно уу'}]}><Select options={camps.map(c=>({value:c.id,label:c.name}))}/></Form.Item>}{!(editing && editing.id===currentUser.id)&&<Form.Item name="password" label={editing?'Шинэ нууц үг (хоосон бол хэвээр)':'Нууц үг'} rules={editing?[passwordRule]:[{required:true,message:'Нууц үг оруулна уу'},passwordRule]} help="8+ тэмдэгт · том үсэг · жижиг үсэг · тоо · тусгай тэмдэгт"><Input.Password/></Form.Item>}<div className="modal-actions"><Button onClick={()=>setOpen(false)}>Болих</Button><Button type="primary" htmlType="submit">Хадгалах</Button></div></Form></Modal><Modal title="Өөрийн нууц үгийг солих" open={passwordOpen} footer={null} onCancel={()=>{setPasswordOpen(false);passwordForm.resetFields()}} destroyOnHidden><Form form={passwordForm} layout="vertical" onFinish={changePassword}><Form.Item name="currentPassword" label="Одоогийн нууц үг" rules={[{required:true,message:'Одоогийн нууц үгээ оруулна уу'}]}><Input.Password autoComplete="current-password"/></Form.Item><Form.Item name="newPassword" label="Шинэ нууц үг" rules={[{required:true,message:'Шинэ нууц үгээ оруулна уу'},passwordRule]}><Input.Password autoComplete="new-password"/></Form.Item><Form.Item name="confirmPassword" label="Шинэ нууц үгээ давтах" dependencies={['newPassword']} rules={[{required:true,message:'Нууц үгээ давтаж оруулна уу'},({getFieldValue})=>({validator(_,value){return !value||getFieldValue('newPassword')===value?Promise.resolve():Promise.reject(new Error('Нууц үг таарахгүй байна'))}})]}><Input.Password autoComplete="new-password"/></Form.Item><div className="modal-actions"><Button onClick={()=>{setPasswordOpen(false);passwordForm.resetFields()}}>Болих</Button><Button type="primary" htmlType="submit" loading={savingPassword}>Нууц үг солих</Button></div></Form></Modal></div>
}

function PositionsPage({positions,employees,permissions,user,refresh}) {
  const [search,setSearch]=useState('');
  const [editing,setEditing]=useState(null);
  const [open,setOpen]=useState(false);
  const [saving,setSaving]=useState(false);
  const [form]=Form.useForm();
  const canCreate=user.role==='admin'||permissions.positions?.includes('create');
  const canUpdate=user.role==='admin'||permissions.positions?.includes('update');
  const canDelete=user.role==='admin'||permissions.positions?.includes('delete');
  const used=name=>employees.filter(row=>row.position===name).length;
  const show=row=>{setEditing(row);form.setFieldsValue({name:row?.name||''});setOpen(true)};
  async function save({name}){setSaving(true);try{await api(`/records/positions${editing?`/${editing.id}`:''}`,{method:editing?'PUT':'POST',body:JSON.stringify({name:name.trim()})});await refresh();setOpen(false);message.success('Албан тушаал хадгалагдлаа')}catch(error){message.error(error.message)}finally{setSaving(false)}}
  async function remove(row){try{await api(`/records/positions/${row.id}`,{method:'DELETE'});await refresh();message.success('Албан тушаал хасагдлаа')}catch(error){message.error(error.message)}}
  return <div className="page-stack flex flex-col gap-5"><div className="page-title-row flex flex-wrap items-end justify-between gap-3"><div><div className="eyebrow">ТОХИРГОО</div><Title level={2}>Албан тушаал</Title><Text type="secondary">Ажилтны бүртгэлд сонгох албан тушаалууд</Text></div>{canCreate&&<Button type="primary" icon={<PlusOutlined/>} onClick={()=>show(null)}>Албан тушаал нэмэх</Button>}</div><Card bordered={false}><Input prefix={<SearchOutlined/>} value={search} onChange={event=>setSearch(event.target.value)} placeholder="Албан тушаал хайх" style={{maxWidth:300,marginBottom:16}}/><Table rowKey="id" dataSource={positions.filter(row=>row.name.toLowerCase().includes(search.toLowerCase())).sort((a,b)=>a.name.localeCompare(b.name,'mn'))} pagination={{pageSize:15}} columns={[{title:'Албан тушаал',dataIndex:'name'},{title:'Ажилтны тоо',render:(_,row)=>used(row.name),width:150},{title:'Үйлдэл',width:170,render:(_,row)=><Space>{canUpdate&&<Button size="small" onClick={()=>show(row)}>Засах</Button>}{canDelete&&<Popconfirm title="Албан тушаалыг хасах уу?" description={used(row.name)?'Ажилтан ашиглаж байгаа тул эхлээд өөр албан тушаал онооно уу.':undefined} onConfirm={()=>remove(row)}><Button size="small" danger disabled={used(row.name)>0}>Хасах</Button></Popconfirm>}</Space>}]}/></Card><Modal title={editing?'Албан тушаал засах':'Албан тушаал нэмэх'} open={open} onCancel={()=>setOpen(false)} footer={null} destroyOnHidden><Form form={form} layout="vertical" onFinish={save}><Form.Item name="name" label="Албан тушаалын нэр" rules={[{required:true,message:'Нэр оруулна уу'},{min:2,max:100,message:'2–100 тэмдэгт байна'}]}><Input maxLength={100}/></Form.Item><div className="modal-actions"><Button onClick={()=>setOpen(false)}>Болих</Button><Button type="primary" htmlType="submit" loading={saving}>Хадгалах</Button></div></Form></Modal></div>;
}

function RolesPage({roles,users,refresh}) {
  const [editing,setEditing]=useState(null);
  const [open,setOpen]=useState(false);
  const [saving,setSaving]=useState(false);
  const [form]=Form.useForm();
  const count=key=>users.filter(user=>user.role===key).length;
  const show=row=>{setEditing(row);form.setFieldsValue({name:row?.name||''});setOpen(true)};
  async function save({name}){setSaving(true);try{await api(editing?`/roles/${editing.key}`:'/roles',{method:editing?'PUT':'POST',body:JSON.stringify({name:name.trim()})});await refresh();setOpen(false);message.success('Эрхийн нэр хадгалагдлаа')}catch(error){message.error(error.message)}finally{setSaving(false)}}
  async function remove(row){try{await api(`/roles/${row.key}`,{method:'DELETE'});await refresh();message.success('Эрх хасагдлаа')}catch(error){message.error(error.message)}}
  return <div className="page-stack flex flex-col gap-5"><div className="page-title-row flex flex-wrap items-end justify-between gap-3"><div><div className="eyebrow">ТОХИРГОО</div><Title level={2}>Эрхийн нэрс</Title><Text type="secondary">Хэрэглэгчид оноох эрхүүд. Хуудасны зөвшөөрлийг “Эрхийн тохиргоо”-нд өгнө.</Text></div><Button type="primary" icon={<PlusOutlined/>} onClick={()=>show(null)}>Эрх нэмэх</Button></div><Card bordered={false}><Table rowKey="key" dataSource={roles} pagination={false} columns={[{title:'Эрхийн нэр',dataIndex:'name'},{title:'Хэрэглэгчийн тоо',render:(_,row)=>count(row.key),width:170},{title:'Үйлдэл',width:180,render:(_,row)=><Space><Button size="small" onClick={()=>show(row)}>Нэр засах</Button>{row.key!=='admin'&&<Popconfirm title="Энэ эрхийг хасах уу?" onConfirm={()=>remove(row)}><Button size="small" danger disabled={count(row.key)>0}>Хасах</Button></Popconfirm>}</Space>}]}/></Card><Modal title={editing?'Эрхийн нэр засах':'Эрх нэмэх'} open={open} onCancel={()=>setOpen(false)} footer={null} destroyOnHidden><Form form={form} layout="vertical" onFinish={save}><Form.Item name="name" label="Эрхийн нэр" rules={[{required:true,message:'Нэр оруулна уу'},{min:2,max:60,message:'2–60 тэмдэгт байна'}]}><Input maxLength={60}/></Form.Item><div className="modal-actions"><Button onClick={()=>setOpen(false)}>Болих</Button><Button type="primary" htmlType="submit" loading={saving}>Хадгалах</Button></div></Form></Modal></div>;
}

function PermissionsPage({projectId,onSaved,roleNames}) {
  const [role,setRole]=useState('admin');
  const [matrix,setMatrix]=useState({});
  const [saving,setSaving]=useState(false);
  useEffect(()=>{api('/permissions').then(setMatrix).catch(e=>message.error(e.message))},[projectId]);
  const actions=[['read','Харах'],['create','Нэмэх'],['update','Засах'],['delete','Устгах']];
  const current=matrix[role] || {};
  const toggle=(type,action,checked)=>setMatrix(previous=>({...previous,[role]:{...(previous[role]||{}),[type]:checked?[...(previous[role]?.[type]||[]),action]:((previous[role]?.[type]||[]).filter(item=>item!==action))}}));
  async function save(){setSaving(true);try{const result=await api(`/permissions/${role}`,{method:'PUT',body:JSON.stringify({permissions:matrix[role] || {}})});setMatrix(previous=>({...previous,[role]:{...previous[role],...result.permissions}}));message.success('Эрхийн тохиргоо амжилттай хадгалагдлаа');void Promise.resolve(onSaved?.()).catch(()=>{})}catch(e){message.error(e.message)}finally{setSaving(false)}}
  return <div className="page-stack flex flex-col gap-5"><div className="page-title-row flex flex-wrap items-end justify-between gap-3"><div><div className="eyebrow">ХАНДАХ ЭРХ</div><Title level={2}>Эрхийн тохиргоо</Title><Text type="secondary">Хуудас бүрийн харах, нэмэх, засах, устгах эрх</Text></div><Space><Select value={role} onChange={setRole} style={{width:175}} options={Object.entries(roleNames).map(([value,label])=>({value,label}))}/><Button type="primary" onClick={save} loading={saving}>Хадгалах</Button></Space></div><Card bordered={false}><Table rowKey="type" pagination={false} scroll={{x:600}} dataSource={[...Object.entries(schemas).map(([type,schema])=>({type,title:schema.title})),{type:'documents',title:'Тушаал, маягт'},...viewPages.map(view=>({type:view.key,title:view.label,view}))]} columns={[{title:'Хуудас',dataIndex:'title',fixed:'left',width:210},...actions.map(([action,label])=>({title:label,width:95,align:'center',render:(_,row)=><Checkbox checked={row.type==='rosterSketch'?!!current.rosterEntries?.includes('read'):role==='admin'&&action!=='read'?false:row.type==='permissions'&&role==='admin'&&action==='read'||(current[row.type]||[]).includes(action)} disabled={row.type==='rosterSketch'||row.view&&(action!=='read'||row.view.alwaysVisible&&role==='admin'||row.view.adminOnly&&role!=='admin'||row.view.campOnly&&role!=='camp')||role==='admin'&&action!=='read'} onChange={event=>toggle(row.type,action,event.target.checked)}/> }))]}/></Card></div>;
}

function AuditPage({projectId,roleNames}) {
  const [rows,setRows]=useState([]);
  const [batches,setBatches]=useState([]);
  const [role,setRole]=useState('');
  const [page,setPage]=useState('');
  const [detail,setDetail]=useState(null);
  const load=async()=>{try{const [logs,imports]=await Promise.all([api(`/audit?role=${encodeURIComponent(role)}&page=${encodeURIComponent(page)}`),api('/imports')]);setRows(logs);setBatches(imports)}catch(e){message.error(e.message)}};
  useEffect(()=>{load()},[projectId,role,page]);
  const actionLabel={create:'Нэмсэн',update:'Зассан',delete:'Устгасан',import:'Импортолсон',import_undo:'Импорт буцаасан',submit:'Илгээсэн',reset:'Хуучин өгөгдлийг цэвэрлэсэн'};
  async function undo(batch){try{const result=await api(`/imports/${batch.id}/undo`,{method:'POST'});message.success(`${result.count} мөрийн импорт буцаагдлаа`);load()}catch(e){message.error(e.message)}}
  return <div className="page-stack flex flex-col gap-5"><div className="page-title-row flex flex-wrap items-end justify-between gap-3"><div><div className="eyebrow">ХЯНАЛТ</div><Title level={2}>Аудит лог</Title><Text type="secondary">Хэрэглэгчийн хийсэн өөрчлөлт, цаг хугацаа, импорт</Text></div><Button onClick={load} icon={<ReloadOutlined/>}>Шинэчлэх</Button></div><Card bordered={false} title="Үйлдлийн түүх" extra={<Space wrap><Select value={role} onChange={setRole} style={{width:145}} options={[{value:'',label:'Бүх эрх'},...Object.entries(roleNames).map(([value,label])=>({value,label}))]}/><Select value={page} onChange={setPage} style={{width:175}} options={[{value:'',label:'Бүх хуудас'},...Object.entries(schemas).map(([value,item])=>({value,label:item.title})),{value:'users',label:'Хэрэглэгчид'},{value:'permissions',label:'Эрх'},{value:'documents',label:'Тушаал, маягт'}]}/></Space>}><Table rowKey="id" dataSource={rows} pagination={{pageSize:15}} onRow={record=>({onClick:()=>setDetail(record),style:{cursor:'pointer'}})} columns={[{title:'Цаг',dataIndex:'createdAt',render:v=>dayjs(v).format('YYYY.MM.DD HH:mm:ss')},{title:'Хэрэглэгч',dataIndex:'username'},{title:'Эрх',dataIndex:'role',render:v=>roleNames[v]||v},{title:'Хуудас',dataIndex:'page',render:v=>v==='equipmentAllData'?'Техник · ALL DATA':schemas[v]?.title||v},{title:'Үйлдэл',dataIndex:'action',render:v=>actionLabel[v]||v}]}/></Card><Card bordered={false} title="Excel импортын түүх"><Table rowKey="id" dataSource={batches} pagination={{pageSize:8}} scroll={{x:650}} columns={[{title:'Файл',dataIndex:'filename'},{title:'Хуудас',dataIndex:'type',render:v=>schemas[v]?.title||v},{title:'Мөр',dataIndex:'rowCount'},{title:'Огноо',dataIndex:'createdAt',render:v=>dayjs(v).format('YYYY.MM.DD HH:mm')},{title:'Буцаах',render:(_,row)=>row.undoneAt?<Tag>Буцаасан</Tag>:<Popconfirm title="Импортын бүх мөрийг буцаах уу?" onConfirm={()=>undo(row)}><Button size="small" danger>Буцаах</Button></Popconfirm>}]}/></Card><Modal title="Үйлдлийн дэлгэрэнгүй" open={!!detail} onCancel={()=>setDetail(null)} footer={null}><Descriptions column={1} bordered size="small" items={detail?[{key:'time',label:'Цаг',children:dayjs(detail.createdAt).format('YYYY.MM.DD HH:mm:ss')},{key:'user',label:'Хэрэглэгч',children:detail.username},{key:'role',label:'Эрх',children:roleNames[detail.role]||detail.role},{key:'page',label:'Хуудас',children:schemas[detail.page]?.title||detail.page},{key:'action',label:'Үйлдэл',children:actionLabel[detail.action]||detail.action},{key:'record',label:'Бүртгэлийн ID',children:detail.recordId||'—'},{key:'details',label:'Дэлгэрэнгүй',children:<pre className="max-h-64 overflow-auto whitespace-pre-wrap text-xs">{JSON.stringify(detail.details,null,2)}</pre>}]:[]}/></Modal></div>;
}

const documentKinds={hiring:'Ажилд томилох тушаал',termination:'Ажлаас чөлөөлөх тушаал',clearance:'Тойрох хуудас',extension:'Сунаж ажиллах хуудас',certificate:'Ажилтны тодорхойлолт'};
function DocumentsPage({employees,projectId,user,permissions}) {
  const [form]=Form.useForm();
  const [rows,setRows]=useState([]);
  const [kind,setKind]=useState('hiring');
  const [saving,setSaving]=useState(false);
  const [preview,setPreview]=useState(null);
  const [selected,setSelected]=useState(null);
  const canCreate=user.role==='admin'||permissions.documents?.includes('create');
  const canDelete=user.role==='admin'||permissions.documents?.includes('delete');
  const options=employees.map(e=>({value:e.id,label:`${e.lastName||''} ${e.firstName||''} · ${e.position||'Албан тушаалгүй'} · ${e.register||''}`}));
  const load=async()=>{try{setRows(await api('/documents'))}catch(error){message.error(error.message)}};
  useEffect(()=>{load()},[projectId]);
  useEffect(()=>()=>{if(preview?.url)URL.revokeObjectURL(preview.url)},[preview?.url]);
  const pdf=async row=>{
    try {
      const project=sessionStorage.getItem('mpc-project-id');
      const response=await fetch(`/api/documents/${row.id}/pdf`,{credentials:'same-origin',headers:project?{'X-Project-ID':project}:{}});
      if(!response.ok)throw new Error((await response.json().catch(()=>({}))).error||'PDF уншихад алдаа гарлаа');
      const url=URL.createObjectURL(await response.blob());setPreview({row,url});
    }catch(error){message.error(error.message)}
  };
  const submit=async values=>{setSaving(true);try{
    const row=await api('/documents',{method:'POST',body:JSON.stringify({employeeId:values.employeeId,kind,approverIds:values.approverIds||[],fields:{...values,date:values.date?.format('YYYY-MM-DD'),startDate:values.startDate?.format('YYYY-MM-DD'),endDate:values.endDate?.format('YYYY-MM-DD'),effectiveDate:values.effectiveDate?.format('YYYY-MM-DD')}})});
    message.success('Баримт амжилттай үүслээ');await load();await pdf(row);
  }catch(error){message.error(error.message)}finally{setSaving(false)}};
  const fields=kind==='hiring'?['date','orderNumber','effectiveDate','trialMonths','salaryAmount','legalBasis','executiveName','preparedBy','reviewedBy']:kind==='termination'?['date','orderNumber','effectiveDate','legalBasis','initiator','reason','executiveName','preparedBy','reviewedBy']:kind==='clearance'?['date','approverIds']:kind==='extension'?['date','startDate','endDate','location','reason','approvalDecision','payMode','payCondition','approverIds']:['date','orderNumber','companyAddress','companyPhone','companyEmail','contractType','salaryAmount','purpose','executiveName'];
  const fieldLabels={date:'Баримтын огноо',orderNumber:'Тушаал / баримтын дугаар',effectiveDate:'Хүчинтэй болох өдөр',trialMonths:'Туршилтын хугацаа (сар)',salaryAmount:'Үндсэн цалин (₮)',legalBasis:'Хуулийн болон гэрээний үндэслэл',initiator:'Санаачилга',reason:'Шалтгаан',location:'Ажиллах байршил',startDate:'Эхлэх өдөр',endDate:'Дуусах өдөр',payCondition:'Цалингийн нөхцөл',approvalDecision:'Зөвшөөрлийн төлөв',payMode:'Цалингийн сонголт',purpose:'Тодорхойлолтын зорилго',companyAddress:'Компанийн хаяг',companyPhone:'Компанийн утас',companyEmail:'Компанийн и-мэйл',contractType:'Гэрээний төрөл',preparedBy:'Боловсруулсан',reviewedBy:'Хянасан',executiveName:'Гүйцэтгэх захирал',approverIds:'Тооцоо нягтлах / батлах ажилтнууд'};
  return <div className="page-stack flex flex-col gap-5"><div className="page-title-row"><div><div className="eyebrow">HR · БАРИМТ</div><Title level={2}>Тушаал, маягт</Title><Text type="secondary">Ажилтны мэдээллээр PDF бэлдэж, урьдчилан харж баталгаажуулна.</Text></div></div><Alert type="info" showIcon message="Баримт нь төсөл байна" description="Гарын үсэг, хуулийн үндэслэл болон тооцоог HR шалгасны дараа хэвлэж баталгаажуулна."/>{canCreate&&<Card bordered={false}><div className="mb-5 flex flex-wrap gap-2">{Object.entries(documentKinds).map(([key,label])=><Button key={key} type={kind===key?'primary':'default'} onClick={()=>setKind(key)}>{label}</Button>)}</div><Form form={form} layout="vertical" onFinish={submit} initialValues={{date:dayjs()}}><Form.Item name="employeeId" label="Ажилтан" rules={[{required:true,message:'Ажилтан сонгоно уу'}]}><Select showSearch optionFilterProp="label" options={options} placeholder="Нэр, регистр эсвэл албан тушаалаар хайх" onChange={setSelected}/></Form.Item>{selected&&<Alert className="mb-5" showIcon type="success" message={options.find(x=>x.value===selected)?.label}/>}<div className="grid gap-x-4 sm:grid-cols-2">{fields.map(key=><Form.Item key={key} name={key} label={fieldLabels[key]} rules={key==='legalBasis'&&kind==='termination'?[{required:true,message:'Үндэслэл оруулна уу'}]:undefined}>{key==='trialMonths'?<InputNumber min={0} max={12} className="w-full" placeholder="Жишээ: 3"/>:key==='salaryAmount'?<InputNumber min={1} className="w-full" placeholder="Хоосон бол ажилтны үндсэн цалинг авна"/>:key==='approvalDecision'?<Select allowClear options={[{value:'approved',label:'Зөвшөөрсөн'},{value:'rejected',label:'Зөвшөөрөөгүй'}]}/>:key==='payMode'?<Select allowClear options={[{value:'paid_1_5',label:'Цалинтай 1.5'},{value:'unpaid',label:'Цалингүй'}]}/>:key==='approverIds'?<Select mode="multiple" showSearch optionFilterProp="label" options={options} maxCount={8} placeholder="Албан тушаалаар хайж сонгох"/>:['date','effectiveDate','startDate','endDate'].includes(key)?<DatePicker className="w-full" format="YYYY-MM-DD"/>:<Input.TextArea autoSize={{minRows:1,maxRows:3}} placeholder={key==='legalBasis'?'Зөв хуулийн заалт / гэрээний үндэслэлээ бичнэ үү':''}/>}</Form.Item>)}</div><Button type="primary" size="large" htmlType="submit" loading={saving} disabled={!employees.length}>PDF үүсгэх</Button></Form></Card>}<Card bordered={false} title="Үүсгэсэн баримтууд" extra={<Button icon={<ReloadOutlined/>} onClick={load}>Шинэчлэх</Button>}><Table rowKey="id" dataSource={rows} pagination={{pageSize:10}} scroll={{x:700}} columns={[{title:'Огноо',dataIndex:'createdAt',render:v=>dayjs(v).format('YYYY.MM.DD HH:mm')},{title:'Ажилтан',dataIndex:'employeeId',render:id=>{const e=employees.find(x=>x.id===Number(id));return e?`${e.lastName} ${e.firstName}`:`#${id}`}},{title:'Баримт',dataIndex:'kind',render:v=>documentKinds[v]||v},{title:'Үйлдэл',render:(_,row)=><Space><Button size="small" onClick={()=>pdf(row)}>Харах / татах</Button>{canDelete&&<Popconfirm title="Баримтыг устгах уу?" onConfirm={async()=>{try{await api(`/documents/${row.id}`,{method:'DELETE'});message.success('Баримт амжилттай устлаа');load()}catch(error){message.error(error.message)}}}><Button size="small" danger>Устгах</Button></Popconfirm>}</Space>} ]}/></Card><Modal title={preview?`${documentKinds[preview.row.kind]} · PDF`:''} open={!!preview} width={850} onCancel={()=>setPreview(null)} footer={preview?<Space><Button onClick={()=>{const link=document.createElement('a');link.href=preview.url;link.download=`hr-${preview.row.kind}-${preview.row.id}.pdf`;link.click()}}>Татах</Button><Button type="primary" onClick={()=>{const frame=document.getElementById('hr-document-preview');frame?.contentWindow?.print()}}>Хэвлэх</Button></Space>:null}>{preview&&<iframe id="hr-document-preview" title="PDF урьдчилан харах" src={preview.url} className="h-[70vh] w-full border-0"/>}</Modal></div>;
}

function Shell({user,onLogout}) {
  const [helpOpen,setHelpOpen]=useState(false);
  const [projectId,setProjectId]=useState(()=>{const value=Number(sessionStorage.getItem('mpc-project-id'))||Number(user.projectId);if(value)sessionStorage.setItem('mpc-project-id',String(value));return value});
  const [projects,setProjects]=useState([]);
  const [projectOpen,setProjectOpen]=useState(false);
  const [projectName,setProjectName]=useState('');
  const [permissions,setPermissions]=useState({});
  const [roleDefinitions,setRoleDefinitions]=useState(Object.entries(builtinRoleNames).map(([key,name])=>({key,name,builtin:true})));
  const roleNames=Object.fromEntries(roleDefinitions.map(({key,name})=>[key,name]));
  const [page,setPage]=useState(user.role==='admin'?'dashboard':user.role==='camp'?'campCheck':'tasks');
  const [collapsed,setCollapsed]=useState(false);
  const [mobileOpen,setMobileOpen]=useState(false);
  const [isMobile,setIsMobile]=useState(()=>window.matchMedia('(max-width: 760px)').matches);
  const [date,setDate]=useState(today());
  const [lists,setLists]=useState(Object.fromEntries(Object.keys(schemas).map(k=>[k,[]])));
  const [submissions,setSubmissions]=useState([]);
  const [users,setUsers]=useState([]);
  const [events,setEvents]=useState([]);
  const [loading,setLoading]=useState(true);
  const [notificationOpen,setNotificationOpen]=useState(false);
  const [selectedNotification,setSelectedNotification]=useState(null);
  const [notificationsSeenAt,setNotificationsSeenAt]=useState(()=>localStorage.getItem(`mpc-notifications-${user.id}-${user.projectId}`)||new Date().toISOString());
  async function refresh(){try{const [data,projectRows,eventRows]=await Promise.all([api('/bootstrap'),user.role==='admin'?api('/projects'):Promise.resolve([]),api('/notifications')]);setLists(Object.fromEntries(Object.keys(schemas).map(type=>[type,data.records[type] || []])));setSubmissions(data.submissions || []);setUsers(data.users || []);setEvents(eventRows || []);setPermissions(data.permissions || {});setRoleDefinitions(data.roles || []);setProjects(projectRows)}catch(e){message.error(e.message)}finally{setLoading(false)}}
  useEffect(()=>{refresh()},[projectId]);
  useEffect(()=>{const key=`mpc-notifications-${user.id}-${projectId}`;let seen=localStorage.getItem(key);if(!seen){seen=new Date().toISOString();localStorage.setItem(key,seen)}setNotificationsSeenAt(seen)},[projectId,user.id]);
  useEffect(()=>{const timer=setInterval(()=>{if(document.visibilityState==='visible')refresh()},120000);return()=>clearInterval(timer)},[projectId]);
  const notifications=useMemo(()=>{
    const actions={create:'нэмсэн',update:'зассан',delete:'устгасан',import:'импортолсон',import_undo:'импорт буцаасан',submit:'илгээсэн',reset:'цэвэрлэсэн'};
    return events.map(event=>{
      const record=lists[event.page]?.find(row=>row.id===Number(event.recordId));
      const pageName=schemas[event.page]?.singular||({users:'Хэрэглэгч',permissions:'Эрхийн тохиргоо',documents:'Баримт',projects:'Төсөл',desktopRelease:'Windows програм'})[event.page]||event.page;
      const role=roleNames[event.role]||event.role;
      return {key:`audit-${event.id}`,page:event.page,title:`${event.actorName} (${role}) · ${pageName} ${actions[event.action]||event.action}`,at:event.createdAt,detail:record||{},date:record?.date,actorName:event.actorName,username:event.username,role,action:actions[event.action]||event.action,pageName,recordId:event.recordId};
    });
  },[events,lists]);
  const unreadNotifications=notifications.filter(row=>new Date(row.at)>new Date(notificationsSeenAt)).length;
  const timeAgo=value=>{const minutes=Math.max(0,Math.floor((Date.now()-new Date(value).getTime())/60000));return minutes<1?'Саяхан':minutes<60?`${minutes} минутын өмнө`:minutes<1440?`${Math.floor(minutes/60)} цагийн өмнө`:`${Math.floor(minutes/1440)} өдрийн өмнө`};
  function openNotifications(){const stamp=new Date().toISOString();localStorage.setItem(`mpc-notifications-${user.id}-${projectId}`,stamp);setNotificationsSeenAt(stamp);setNotificationOpen(true)}
  async function createProject(){try{const row=await api('/projects',{method:'POST',body:JSON.stringify({name:projectName})});setProjectOpen(false);setProjectName('');sessionStorage.setItem('mpc-project-id',String(row.id));setProjectId(row.id);message.success('Төсөл амжилттай үүслээ')}catch(e){message.error(e.message)}}
  useEffect(()=>{const query=window.matchMedia('(max-width: 760px)');const sync=()=>setIsMobile(query.matches);query.addEventListener('change',sync);return()=>query.removeEventListener('change',sync)},[]);
  const canRead=key=>user.role==='admin'&&key==='projects'||permissions[key]?.includes('read');
  useEffect(()=>{
    if(loading||!Object.keys(permissions).length||canRead(page))return;
    const fallback=user.role==='admin'?'permissions':['tasks','campCheck',...Object.keys(schemas)].find(key=>canRead(key));
    if(fallback&&fallback!==page)setPage(fallback);
  },[loading,page,permissions,user.role]);
  const menuItem=(key,label,icon)=>canRead(key)?{key,label,icon}:null;
  const items=[canRead('dashboard')?{key:'dashboard',icon:<DashboardOutlined/>,label:'Хяналтын самбар'}:null,{key:'hr',icon:<TeamOutlined/>,label:'HR',children:[menuItem('employees','Ажилтан'),menuItem('attendance','Цаг бүртгэл'),canRead('timesheet')?{key:'timesheet',label:'Цагийн мэдээ'}:null,canRead('payroll')?{key:'payroll',label:'Цалин бодолт'}:null,canRead('roster')?{key:'roster',label:'Ээлжийн мэдээ'}:null,canRead('rosterSketch')?{key:'rosterSketch',label:'Ростерын зураглал'}:null,menuItem('shiftOverrides','Ээлж солилцоо'),menuItem('travelExpenses','Замын зардал'),canRead('documents')?{key:'documents',label:'Тушаал, маягт'}:null].filter(Boolean)},{key:'operations',icon:<ApartmentOutlined/>,label:'Үйл ажиллагаа',children:[menuItem('plans','Бүтээлийн төлөвлөгөө'),menuItem('productionEntries','Бүтээлийн гүйцэтгэл'),menuItem('equipment','Техник'),menuItem('equipmentTransfers','Сэлбэг салгалтын бүртгэл'),menuItem('camps','Кемп'),menuItem('campStays','Хоног, хоол'),menuItem('guests','Зочид'),menuItem('mealMenus','Хоолны цэс'),menuItem('mealFeedback','Хоолны санал'),menuItem('bedAssignments','Орны бүртгэл'),menuItem('maintenance','Засварын мэдээ / зогсолт'),menuItem('technicalReadiness','7 хоногийн тойм'),menuItem('machineLogs','Мото цаг'),menuItem('fuel','Түлш'),menuItem('other','Бусад')].filter(Boolean)},{key:'mpc',icon:<ApartmentOutlined/>,label:'MPC бараа материал',children:[menuItem('mpcItems','Барааны жагсаалт'),menuItem('mpcBalance','Агуулахын үлдэгдэл'),menuItem('mpcOrders','Захиалга'),menuItem('mpcPurchases','Худалдан авалт'),menuItem('mpcIncome','Орлого, нэхэмжлэх'),menuItem('mpcIssues','Зарлага'),menuItem('mpcTransfers','Дотоод хөдөлгөөн')].filter(Boolean)},canRead('campCheck')?{key:'campCheck',icon:<CheckCircleOutlined/>,label:'Хүмүүсээ шалгах'}:null,canRead('tasks')?{key:'tasks',label:'Ажлын хуваарь',icon:<FileDoneOutlined/>}:null,canRead('reports')?{key:'reports',icon:<BarChartOutlined/>,label:'Тайлан'}:null,{key:'settings',icon:<SettingOutlined/>,label:'Тохиргоо',children:[menuItem('projects','Төслийн нэрс'),menuItem('positions','Албан тушаал'),canRead('roles')?{key:'roles',label:'Эрхийн нэрс'}:null,canRead('users')?{key:'users',label:'Хэрэглэгчид'}:null,canRead('permissions')?{key:'permissions',label:'Эрхийн тохиргоо'}:null,canRead('audit')?{key:'audit',label:'Аудит лог'}:null,canRead('desktopRelease')?{key:'desktopRelease',label:'Windows програм'}:null,canRead('mpcIntegration')?{key:'mpcIntegration',label:'MPC API холболт'}:null].filter(Boolean)}].filter(item=>item && (!item.children || item.children.length));
  const title={dashboard:'Хяналтын самбар',employees:'Ажилтан',attendance:'Цаг бүртгэл',timesheet:'Цагийн мэдээ',payroll:'Цалин бодолт',roster:'Ээлжийн мэдээ',rosterSketch:'Ростерын зураглал',shiftOverrides:'Ээлж солилцоо',travelExpenses:'Замын зардал',documents:'Тушаал, маягт',campCheck:'Хүмүүсээ шалгах',plans:'Бүтээлийн төлөвлөгөө',productionEntries:'Бүтээлийн гүйцэтгэл',equipment:'Техник',equipmentTransfers:'Сэлбэг салгалтын бүртгэл',camps:'Кемп',campStays:'Хоног, хоол',guests:'Зочид',mealMenus:'Хоолны цэс',mealFeedback:'Хоолны санал',bedAssignments:'Орны бүртгэл',maintenance:'Засварын мэдээ',technicalReadiness:'7 хоногийн техникийн тойм',reports:'Тайлан',warehouses:'Агуулах',tasks:'Ажлын хуваарь',machineLogs:'Мото цаг',fuel:'Түлш',other:'Бусад',positions:'Албан тушаал',projects:'Төслийн нэрс',roles:'Эрхийн нэрс',users:'Хэрэглэгчид',permissions:'Эрхийн тохиргоо',audit:'Аудит лог',desktopRelease:'Windows програм',mpcIntegration:'MPC API холболт',mpcItems:'Барааны жагсаалт',mpcBalance:'Агуулахын үлдэгдэл',mpcOrders:'Захиалга',mpcPurchases:'Худалдан авалт',mpcIncome:'Орлого, нэхэмжлэх',mpcIssues:'Зарлага',mpcTransfers:'Дотоод хөдөлгөөн'}[page];
  const mobileKeys=(user.role==='camp'?['campCheck','tasks','employees','camps']:user.role==='admin'?['dashboard','employees','attendance','tasks']:user.role==='hr'?['attendance','employees','tasks','camps']:user.role==='dispatcher'?['tasks','machineLogs','equipment','employees']:['tasks','maintenance','equipment','camps']).filter(key=>canRead(key));
  const mobileIcons={dashboard:<DashboardOutlined/>,employees:<TeamOutlined/>,attendance:<CalendarOutlined/>,campCheck:<CheckCircleOutlined/>,tasks:<FileDoneOutlined/>,camps:<HomeOutlined/>,machineLogs:<ToolOutlined/>,maintenance:<ToolOutlined/>,equipment:<ToolOutlined/>};
  let content=null;
  if (page==='dashboard') content=<Dashboard lists={lists} submissions={submissions} date={date} setDate={setDate} onNavigate={setPage}/>;
  else if (page==='tasks') content=<TasksPage lists={lists} submissions={submissions} refresh={refresh} user={user} date={date} setDate={setDate}/>;
  else if (page==='campCheck') content=<CampCheck lists={lists} user={user} date={date} setDate={setDate} refresh={refresh}/>;
  else if (page==='roster') content=<RosterPage lists={lists} date={date} setDate={setDate}/>;
  else if (page==='rosterSketch') content=<RosterSketch lists={lists} permissions={permissions} user={user} projectId={projectId}/>;
  else if (page==='technicalReadiness') content=<WeeklyReadiness lists={lists} refresh={refresh} permissions={permissions} user={user}/>;
  else if (page==='timesheet') content=<TimesheetPage lists={lists} date={date} refresh={refresh} user={user} permissions={permissions}/>;
  else if (page==='payroll') content=<PayrollPage lists={lists} date={date} refresh={refresh} permissions={permissions} user={user}/>;
  else if (page==='reports') content=<Reports lists={lists} submissions={submissions} date={date} setDate={setDate}/>;
  else if (page==='positions') content=<PositionsPage positions={lists.positions} employees={lists.employees} permissions={permissions} user={user} refresh={refresh}/>;
  else if (page==='roles') content=<RolesPage roles={roleDefinitions} users={users} refresh={refresh}/>;
  else if (page==='users') content=<Users users={users} camps={lists.camps} employees={lists.employees} refresh={refresh} currentUser={user} roleNames={roleNames}/>;
  else if (page==='permissions') content=<PermissionsPage projectId={projectId} onSaved={refresh} roleNames={roleNames}/>;
  else if (page==='audit') content=<AuditPage projectId={projectId} roleNames={roleNames}/>;
  else if (page==='desktopRelease') content=<DesktopReleasePage/>;
  else if (page==='mpcIntegration') content=<MpcIntegrationSettings projectId={projectId}/>;
  else if (page==='projects') content=<ProjectsPage projects={projects} projectId={projectId} refresh={refresh} onSelect={value=>{sessionStorage.setItem('mpc-project-id',String(value));setProjectId(value)}}/>;
  else if (mpcViewPages[page]) content=<MpcReadPage key={`${projectId}:${page}`} view={mpcViewPages[page]}/>;
  else if (page==='documents') content=<DocumentsPage employees={lists.employees} projectId={projectId} user={user} permissions={permissions}/>;
  else if (schemas[page]) content=<RecordPage type={page} lists={lists} submissions={submissions} refresh={refresh} user={user} date={date} setDate={setDate} projectName={projects.find(row=>Number(row.id)===Number(projectId))?.name} permissions={permissions} onHelp={()=>setHelpOpen(true)}/>;
  return <Layout className="app-layout">
    <Sider width={232} collapsedWidth={72} collapsible collapsed={collapsed} trigger={null} className="sidebar"><div className="sidebar-brand"><div className="brand-symbol">Т</div>{!collapsed&&<div><strong>ТҮР HR</strong><span>Mining workforce</span></div>}</div><Menu mode="inline" selectedKeys={[page]} defaultOpenKeys={['hr','operations']} items={items} onClick={({key})=>setPage(key)} className="side-menu"/><div className="sidebar-bottom">{!collapsed&&<span>ДОТООД УДИРДЛАГА · 2026</span>}</div></Sider>
    <Layout><Header className="topbar"><div className="topbar-left"><Button type="text" aria-label="Цэс" icon={isMobile?<MenuUnfoldOutlined/>:collapsed?<MenuUnfoldOutlined/>:<MenuFoldOutlined/>} onClick={()=>isMobile?setMobileOpen(true):setCollapsed(!collapsed)}/><span className="topbar-title">{title}</span></div><div className="topbar-right">{user.role==='admin'&&<Space size={4}><Select aria-label="Төсөл сонгох" value={projectId||undefined} onChange={value=>{sessionStorage.setItem('mpc-project-id',String(value));setProjectId(value);setPage('dashboard')}} style={{minWidth:125}} options={projects.map(p=>({value:p.id,label:p.name}))}/><Button type="text" icon={<PlusOutlined/>} title="Төсөл нэмэх" onClick={()=>setProjectOpen(true)}/></Space>}<Badge count={unreadNotifications} size="small"><Button type="text" icon={<BellOutlined/>} onClick={openNotifications} aria-label="Мэдэгдэл" title="Мэдэгдэл"/></Badge><Button type="text" icon={<QuestionCircleOutlined/>} onClick={()=>setHelpOpen(true)} aria-label="Энэ хуудасны заавар" title="Энэ хуудасны заавар"/><span className="topbar-date"><CalendarOutlined/> {dayjs().format('YYYY.MM.DD')}</span><div className="user-avatar"><UserOutlined/></div><div className="user-copy"><strong>{user.name}</strong><small>{roleNames[user.role]}</small></div><Button type="text" icon={<LogoutOutlined/>} title="Гарах" onClick={onLogout}/></div></Header><Content className="main-content">{loading?<div className="loading-screen">Ачаалж байна...</div>:<><div className="help-page-bar"><Button className="help-page-button" icon={<QuestionCircleOutlined/>} onClick={()=>setHelpOpen(true)}>Энэ хуудсыг яаж ашиглах вэ?</Button></div>{content}</>}</Content></Layout>
    <Modal title="Төсөл нэмэх" open={projectOpen} onCancel={()=>setProjectOpen(false)} onOk={createProject} okText="Үүсгэх"><Input value={projectName} onChange={e=>setProjectName(e.target.value)} placeholder="Төслийн нэр"/></Modal>
    <HelpCenter open={helpOpen} onClose={()=>setHelpOpen(false)} page={page} role={user.role} roleName={roleNames[user.role]} onNavigate={setPage} isMobile={isMobile}/>
    <Drawer title="Мэдэгдэл" placement="right" width={isMobile?'100%':410} open={notificationOpen} onClose={()=>{setNotificationOpen(false);setSelectedNotification(null)}}>
      {selectedNotification?<div className="grid gap-4"><Button onClick={()=>setSelectedNotification(null)}>← Бүх мэдэгдэл</Button><div><strong className="text-base">{selectedNotification.title}</strong><p className="mt-1 text-xs text-slate-500">{timeAgo(selectedNotification.at)} · {dayjs(selectedNotification.at).format('YYYY.MM.DD HH:mm')}</p></div><Descriptions bordered size="small" column={1} items={[{key:'actor',label:'Өөрчилсөн ажилтан',children:selectedNotification.actorName},{key:'account',label:'Нэвтрэх нэр',children:selectedNotification.username},{key:'role',label:'Нэвтэрсэн эрх',children:selectedNotification.role},{key:'action',label:'Үйлдэл',children:`${selectedNotification.pageName} ${selectedNotification.action}`},{key:'record',label:'Бүртгэлийн ID',children:selectedNotification.recordId||'—'},...Object.entries(selectedNotification.detail).filter(([key,value])=>!['id','createdAt','updatedAt','sourceData'].includes(key)&&value!==undefined&&value!==null&&typeof value!=='object').slice(0,12).map(([key,value])=>({key,label:schemas[selectedNotification.page]?.fields.find(field=>field.key===key)?.label||key,children:String(value)}))]}/><Button type="primary" onClick={()=>{if(selectedNotification.date)setDate(selectedNotification.date);if(schemas[selectedNotification.page])setPage(selectedNotification.page);else if(selectedNotification.page==='users'||selectedNotification.page==='permissions')setPage(selectedNotification.page);setNotificationOpen(false);setSelectedNotification(null)}}>Хуудсыг нээх</Button></div>:notifications.length?<div className="grid gap-2">{notifications.map(item=><button key={item.key} type="button" onClick={()=>setSelectedNotification(item)} className="rounded-xl border border-slate-200 bg-white p-4 text-left hover:border-violet-400"><strong className="block text-sm text-slate-800">{item.title}</strong><span className="mt-1 block text-xs text-slate-500">{timeAgo(item.at)} · {dayjs(item.at).format('MM.DD HH:mm')}</span></button>)}</div>:<Empty description="Сүүлийн 7 хоногт мэдэгдэл алга"/>}
    </Drawer>
    {isMobile&&<><nav className="mobile-nav" aria-label="Үндсэн навигаци">{mobileKeys.map(key=><button key={key} type="button" className={page===key?'active':''} onClick={()=>setPage(key)}><span>{mobileIcons[key]}</span><small>{titleMap[key]}</small></button>)}<button type="button" onClick={()=>setMobileOpen(true)}><span><MoreOutlined/></span><small>Бүх цэс</small></button></nav><Drawer title="ТҮР HR · Цэс" placement="left" width={280} open={mobileOpen} onClose={()=>setMobileOpen(false)}><Menu mode="inline" selectedKeys={[page]} defaultOpenKeys={['hr','operations']} items={items} onClick={({key})=>{setPage(key);setMobileOpen(false)}} className="side-menu"/></Drawer></>}
  </Layout>
}

function OfflinePage(){return <main className="offline-page"><div className="offline-card"><div className="offline-icon"><DisconnectOutlined/></div><span className="offline-kicker">ТҮР HR · ХОЛБОЛТ</span><h1>Интернет холболтгүй байна</h1><p>Сүлжээний холболтоо шалгаад дахин оролдоно уу. Холболт сэргэхэд бүртгэлүүдээ үргэлжлүүлж болно.</p><Button type="primary" size="large" icon={<ReloadOutlined/>} onClick={()=>window.location.reload()}>Дахин оролдох</Button></div></main>}

export default function App(){const [user,setUser]=useState(null);const [checking,setChecking]=useState(true);const [online,setOnline]=useState(()=>navigator.onLine);useEffect(()=>{const update=()=>setOnline(navigator.onLine);window.addEventListener('online',update);window.addEventListener('offline',update);return()=>{window.removeEventListener('online',update);window.removeEventListener('offline',update)}},[]);useEffect(()=>{if(!online)return;api('/me').then(setUser).catch(()=>{}).finally(()=>setChecking(false))},[online]);async function logout(){try{await api('/logout',{method:'POST'})}finally{setUser(null)}}return <ConfigProvider theme={{token:{colorPrimary:'#7656d8',borderRadius:10,colorBgLayout:'#f7f8fb',fontFamily:'Inter, Arial, sans-serif'},components:{Menu:{itemSelectedBg:'#f3efff',itemSelectedColor:'#6845d1'}}}}><AntApp>{!online?<OfflinePage/>:checking?<div className="loading-screen">Ачаалж байна...</div>:user?<Shell user={user} onLogout={logout}/>:<Login onLogin={setUser}/>}</AntApp></ConfigProvider>}
